INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2011, 'Paik was also the first artist to broadcast his work on national television, which he did by purchasing advertising slots.', 2011, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2012, 'The work most often associated with him is a robot made from television monitors.', 2012, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2013, 'William Wegman', 2013, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2014, 'Wegman is an American artist who made a number of videos in the 1970s featuring himself and his pet dog, a Weimaraner named Fay Wray.', 2014, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2015, 'The dog performs a number of actions, such as licking up a line drawn in milk on the studio floor, which Wegman himself also tries to do, considerably less efficiently.', 2015, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2016, 'Two similar dogs sit face on to the camera following something off screen intently in perfect unison, the object of the dogs&#x2019; attention moving sometimes slowly and sometimes dramatically and violently.', 2016, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2017, 'The videos are filmed in black and white in a single shot with no editing.', 2017, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2018, 'Wegman went on to make colour photographs of the dog dressed in clothes.', 2018, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2019, 'EXPERIMENTAL FILM', 2019, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2020, 'Kenneth Anger', 2020, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2021, 'An underground filmmaker born in the 1950s whose best known film Scorpio Rising had an influence on a whole generation of artists and filmmakers.', 2021, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2022, 'A number of artists made site specific work that, like performance art, relied on photographic documentation for its dissemination and permanence.', 2022, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2023, 'This became known as land art.', 2023, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2024, 'LAND ART', 2024, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2025, 'Dennis Oppenheim', 2025, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2026, 'Much of Oppenheim&apos;s work was site specific land art with a performative endurance element.', 2026, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2027, 'For one of Oppenheim&#x2019;s best known works, Trench, he suspended his outstretched body by pressing with his hands and feet against the top of two opposite walls of a purpose built trench.', 2027, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2028, 'For another he lay in the sun until his skin was burnt and had changed colour, calling his sunburn the evidence that an artwork had been made.', 2028, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2029, 'Robert Smithson', 2029, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2030, 'Smithson&apos;s work is nearly always site specific and involves him altering the natural environment, either by rearranging it or by placing mirrors so that the landscape reflects itself.', 2030, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2031, 'He is interested in the perspective of the map in terms of making the ground his work surface or picture plane, and in creating &#x2018;images&#x2019; which, like the topography represented by a map, are only visible from the air.', 2031, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2032, 'In one sense, then, his work is intentionally invisible.', 2032, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2033, 'Smithson&#x2019;s use of mirrors is a development of this interest in making formal rearrangements of the natural world.', 2033, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2034, 'The mirror works occupied a variety of locations, including rural ones and one in Manhattan in which large mirrors are stood on the ground at specific angles.', 2034, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2035, 'Spiral Jetty is the best known work by any land artist.', 2035, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2036, 'It was made by taking several tonnes of small rock to a salt lake and building a walkway, which leaves the beach and follows a very large spiral that is only visible form the air.', 2036, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2037, 'Spiral Jetty has over the years been submerged by the lake and now ceases to exist.', 2037, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2038, 'However, it was documented in photographs and on film, like all of Smithson&#x2019;s work, and this is the form in which his work is most commonly experienced.', 2038, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2039, 'In fact Smithson was very interested in the dichotomy between the reality of his work experienced in situ and in a photograph (which shows the work in an entirely different way).', 2039, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2040, 'He made a number of other earthworks and plans for earthworks, and also made work using maps.', 2040, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2041, 'Mary Miss', 2041, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2042, 'American artist born in the late 1940s who made a number of earthwork sculptures, for example a cube shaped void sunk into the ground which had its top exactly level with the surface, and could be entered on ramps from ground level.', 2042, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2043, 'Miss subverted minimal sculptural forms being made by her contemporaries by making them absolutely concrete but invisible.', 2043, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2044, 'Agnes Denes', 2044, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2045, 'The American artist Denes planted and cultivated a field of wheat in Manhattan on a two acre landfill site in 1982.', 2045, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2046, 'Denes wanted to make a work about world trade, the economics of food production and famine.', 2046, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2047, 'Walter De Maria', 2047, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2048, 'Known for his permanent installation Lightning Field of 1987 which is a site in Arizona, in a specific area that has the highest frequency of lightning strikes in the world.', 2048, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2049, 'De Maria set out a square mile of lightning conductor poles linked by conductive wires which when struck by lightening animate the field in a spectacle of blue light and electrical activity.', 2049, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2050, 'SITE SPECIFIC ART', 2050, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2051, 'Gordon Matta Clark', 2051, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2052, 'American artist Matta Clark is best known for his work House, a suburban clapboard house that the artist cut in two vertically down the centre.', 2052, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2053, 'The two halves lean outwards and away from each other.', 2053, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2054, 'Matta Clark made a number of other works which involved cutting through buildings, for example a project at the opening of the Pompidou Centre in Paris in which he cut several circular and elliptical holes through a nearby building that was about to be redeveloped.', 2054, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2055, 'Although major in terms of their execution, Matta Clark&#x2019;s interventions are visually extremely simple.', 2055, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2056, 'Christo and Jeanne Claude', 2056, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2057, 'Beginning in the 1970s French artist Christo and his partner Jeanne Claude began wrapping objects, to transform one thing into another, solidify forms, change a hard form to an apparently soft one, graduating to larger and larger objects.', 2057, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2058, 'They began to work with fabric on a large scale, either wrapping buildings or the landscape.', 2058, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2059, 'They used parachute silk, vinyl and other kinds of industrial fabric with the required properties.', 2059, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2060, 'Several works exemplify what they do best.', 2060, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2061, 'For example, Valley Curtain, made in the early 1980s, was a large orange curtain hung across a valley somewhere in California.', 2061, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2062, 'Running Fence is a mile long fence of red fabric that follows the contours of a hill.', 2062, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2063, 'The artists installed a large number of table umbrellas dotted over a hillside.', 2063, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2064, 'The Island Skirts surround a number of small islands, following the shoreline and floating on the water for thirty metres or so.', 2064, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2065, 'As with all their work, the proportions of the intervention always take the view from a distance into account.', 2065, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2066, 'The work is by its nature temporary and is always made with the final photographic document in mind.', 2066, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2067, 'Thus the island skirts were designed to be wide enough to be clearly visible in an aerial photograph, and the locations are very carefully chosen with the final photograph in mind.', 2067, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2068, 'In the 1990s Christo and Jeanne Claude completed their most ambitious projects, the Wrapped Reichstag and the Wrapped Pont Neuf.', 2068, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2069, 'These structures were wrapped in a fabric that was light enough to fold and gather around the forms they covered, and bound with rope.', 2069, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2070, 'The Pont Neuf was wrapped in a gold fabric resulting in a transformation that was a triumph of planning, negotiation and construction.', 2070, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2071, 'There are still postcards of the work on every Parisian postcard rack.', 2071, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2072, 'FIGURATIVE PAINTING', 2072, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2073, 'In Britain in the early twentieth century many figurative painters were engaged in a gritty realism that echoed the post war reality.', 2073, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2074, 'Stanley Spencer', 2074, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2075, 'British artist Spencer painted English rural life and religious subjects, often combining the two.', 2075, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2076, 'He often showed god or Jesus in a scene set in an English village.', 2076, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2077, 'The paintings are sometimes large and the composition is crowded.', 2077, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2078, 'Spencer&#x2019;s figures are often solidly built with heavy limbs, almost statue like, and he kept to a palette of grey, brown and ochre.', 2078, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2079, 'Ivon Hitchens', 2079, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2080, 'Hitchens&#x2019;s English landscapes with vegetation and flowers are painted with loose flowing brushstrokes leaving parts of the canvas unpainted.', 2080, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2081, 'He favoured subdued earth colours, purples, blues and greens.', 2081, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2082, 'John Bratby', 2082, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2083, 'Bratby was one of a group known as the kitchen sink painters for their choice of domestic subject matter.', 2083, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2084, 'Bratby&apos;s interiors showed his own home and family, painted with thickly encrusted paint often squeezed directly from the tube and applied with a palette knife, in an almost na&#xef;ve style.', 2084, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2085, 'Cecil Collins', 2085, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2086, 'British twentieth century visionary painter.', 2086, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2087, 'LS Lowry', 2087, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2088, 'British artist Lowry lived and worked in the North of England and painted scenes of everyday and working class life in the cities of the North.', 2088, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2089, 'He became known as a kind of people&#x2019;s painter, a painter of &#x2018;matchstick men and matchstick cats and dogs&#x2019; immortalised in a popular music song.', 2089, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2090, 'Lowry&#x2019;s paintings showed the grey light of northern winters and the relentless coming and going of daily life, with buildings and a multitude of tiny people walking past.', 2090, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2091, 'The people are painted in two or three brushstrokes, suggestions of figures so that Lowry could paint a great number of them on one painting.', 2091, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2092, 'The paintings are often predominantly grey or white, the figures in dark colours with little hints of brighter colours.', 2092, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2093, 'Lucian Freud', 2093, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2094, 'A British figurative painter who was born in the 1930s, Freud began his career precociously in his teens and was still painting in 2003.', 2094, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2095, 'He paints portraits, usually of models, sometimes of friends, family, and sometimes of well known people, although he rarely accepts commissions.', 2095, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2096, 'His models are almost always nude, or semi clothed and painted in accurate detail, but with a psychological perspective.', 2096, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2097, 'They are often lying down.', 2097, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2098, 'The predominant colours of the paintings are consistent: skin tones, and the greys and browns of his studio are the background to all his works since he never paints anywhere else.', 2098, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2099, 'A painting may take up to twenty or so sittings, and some sitters are not able to continue.', 2099, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2100, 'He has often painted a favourite model repeatedly.', 2100, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2101, 'Some of Freud&#x2019;s paintings might be of two people lying together, or there may be a dog, often a greyhound.', 2101, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2102, 'He favours gaunt loose skinned physiques but has also painted larger people.', 2102, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2103, 'Freud&#x2019;s subjects include himself, his lovers, his models (sometimes the two are the same), his daughters, artist Leigh Bowery, the Queen of England and the fashion model Kate Moss.', 2103, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2104, 'Francis Bacon', 2104, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2105, 'Bacon was a very important British painter whose paintings are conceptual but theatrical figurative works with abstract qualities.', 2105, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2106, 'They are nearly always portraits in which the figure is distorted, often to grotesque effect, perhaps looking as if they have been melted or brushed away, appearing to be in discomfort.', 2106, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2107, 'The figures are rendered with rough brushstrokes, and are placed on a contrasting flat colour background, often within a delineated three dimensional space.', 2107, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2108, 'Bacon made many self portraits.', 2108, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2109, 'One of his best known works is the diptych Three Screaming Popes; three large canvases each with a portrait of a pope in a cope and mitre, within a kind of abstract geometric frame structure, on dark orange and red grounds.', 2109, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2110, 'The faces of the popes are blurred and distorted.', 2110, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2111, 'He also painted a dog that is either curled up or chasing its tail.', 2111, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2112, 'As with Bacon&#x2019;s other work, there is an impression of movement, as if a photograph has been taken on a long exposure and the sitter moved, leaving a trail of the movement on the image.', 2112, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2113, 'Bacon was almost as well known for his lifestyle as for his work.', 2113, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2114, 'A heavy drinking habitu&#xe9; of bars in Soho in London he lived a solitary and obsessive working life, rarely spending a day without painting.', 2114, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2115, 'His studio was famously untidy and dirty.', 2115, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2116, 'Bacon died in the 1990s.', 2116, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2117, 'Painting had begun to aspire to the condition of photography, particularly in America.', 2117, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2118, 'This was to become a major theme in the work of Richter and others later on, but initially there were only a few interested artists.', 2118, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2119, 'Photorealist painters literally mimicked the appearance of a photograph.', 2119, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2120, 'Chuck Close', 2120, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2121, 'Close initially made photo realist paintings but he is best known for his gridded paintings which, although they pre date digital technology, have the appearance of pixilated images.', 2121, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2122, 'Inspired by the printing process and the way an image is broken down into dots of three colours, Close developed a way of placing a grid of squares of about 3 by 3 cm over the image he wanted to paint, very often a self portrait.', 2122, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2123, 'He then produced the image by painting each square a different colour so that from a distance the image would be readable but close up the coloured squares would be predominate.', 2123, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2124, 'In doing so he was investigating both the effect of photographic printing and painting, making a painting that looked photographic, as painting had been trying to do, yet not in the conventional sense.', 2124, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2125, 'All this work was made before the digital revolution that has made Close&#x2019;s paintings look exactly like pixels.', 2125, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2126, 'As well as paintings, Close also made works on paper in watercolours.', 2126, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2127, 'He made a series of self portraits using black and greys that emulate black and white photos.', 2127, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2128, 'Reinhardt Voight', 2128, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2129, 'An American artist born around 1950, Voight makes paintings based on a grid.', 2129, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2130, 'In Voight&#x2019;s early work he translated a photographic image into a coloured grid, degrading the image almost entirely, an idea that prefigured pixellation by decades.', 2130, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2131, 'David Hockney', 2131, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2132, 'One of the best known of all British twentieth century artists, Hockney was born in the 1940s and began his career in the 1960s, becoming successful while he was still at college.', 2132, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2133, 'At this early stage he often added text to his paintings as in a work titled We Two Boys Together Swinging, where he added the title of the painting in white letters.', 2133, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2134, 'Hockney&#x2019;s most famous painting is called The Bigger Splash.', 2134, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2135, 'It shows an empty swimming pool and diving board with a villa in the background.', 2135, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2136, 'The pool is rendered in flat aquamarine and there is a white splash in the water as if someone had just dived in.', 2136, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2137, 'This is the best known representation of a splash in the history of painting.', 2137, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2138, 'Hockney went to live in Los Angeles and the swimming pool became his favourite subject.', 2138, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2139, 'He became very good at painting water and also painted in watercolour on tiled sheets of watercolour paper.', 2139, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2140, 'He continued to paint in watercolour in 2003, making large scale full length portraits.', 2140, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2141, 'Drawings constitute a major part of Hockney&#x2019;s oeuvre.', 2141, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2142, 'He used a single confident line, pencil or pen, and also made a number of lithographs and etchings.', 2142, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2143, 'His drawings are restrained and monochrome in comparison to his often bright paintings.', 2143, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2144, 'He drew his friends and lovers incessantly, and his mother, as well as still lifes, flowers, landscapes and animals, in particular cats and dogs.', 2144, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2145, 'In fact Hockney&#x2019;s work is extremely traditional in terms of his subject matter, it was rather his means of execution that attracted attention.', 2145, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2146, 'Another well known painting by Hockney is Mrs and Mrs Clarke at Home, a double portrait of Ossie and Celia Clarke, fashion designer friends of Hockney&#x2019;s, seated on opposite sides of a bay window in their London home with their cat next to them.', 2146, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2147, 'Hockney also designed a number of stage productions for opera companies, notably the Magic Flute and The Rake&#x2019;s Progress, painting backdrops as well as designing costumes.', 2147, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2148, 'Edward Hopper', 2148, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2149, 'An American artist who began his career in the 1940s, Hopper is one of the most popular painters of American life, mostly but not always choosing urban scenes.', 2149, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2150, 'He was particularly good at painting night scenes.', 2150, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2151, 'One painting shows a bar at night, a long and low corner building, green on the outside with mostly black on the canvas, but glowing with bright yellow light from its interior.', 2151, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2152, 'Inside is a woman waitress and a few solitary male customers.', 2152, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2153, 'Another painting shows a petrol station at night, another a person on a lonely road at by a payphone, caught in the headlights of an oncoming car.', 2153, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2154, 'Hopper depicted the melancholy and loneliness that he found in modern life.', 2154, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2155, 'Norman Rockwell', 2155, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2156, 'American artist who made paintings that represented the American way of life, and who became synonymous with a certain idealised view of America.', 2156, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2157, 'Rockwell painted rural scenes depicting life on farmsteads, domestic interiors, fireside scenes and landscapes.', 2157, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2158, 'A particularly well known work is a painting of a meadow filled with poppies in which a little girl is sitting.', 2158, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2159, 'Rockwell painted in a highly realistic illustrative style avoiding any reference to painting as object.', 2159, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2160, 'He spent his career making an impeccably painted record of America between the 1940s and 60s, many of which were printed on the cover of Picture Post and became images that entered into the national consciousness.', 2160, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2161, 'Georgia O&#x2019;Keefe', 2161, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2162, 'O&#x2019;Keefe is well known for her paintings of hugely enlarged flowers in very strong colours which also allude to the female anatomy.', 2162, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2163, 'O&#x2019;Keefe spent many years living in the desert in New Mexico from which she derived much of her inspiration, also making a series of works depicting bleached animal bones and skulls which she found there.', 2163, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2164, 'Through her flower paintings O&#x2019;Keefe succeeded in turning a traditionally delicate subject into large bold and even aggressive or threatening forms.', 2164, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2165, 'Frida Kahlo', 2165, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2166, 'This Mexican artist was born in the 1920s and made figurative paintings, largely self portraits.', 2166, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2167, 'Kahlo depicted the tragedy of her life in her paintings, which are graphic and detailed.', 2167, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2168, 'She shows herself in many guises, with her distinguishing eyebrows that meet in the middle, and her long braided hair and native Mexican dress.', 2168, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2169, 'She details her gynaecological problems and back problems stemming from a trolley bus accident as a young girl (which eventually took her life prematurely in the 1950s) in her paintings, in particular a number of miscarriages (she shows the foetus outside her womb, still attached by the umbilical cord, for example) and the restraining corset which she wore to support her spine in her last years.', 2169, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2170, 'Kahlo&apos;s discomfort and anger at her body&#x2019;s inability to fulfil its biological destiny, coupled with a feminist fury at the obstacles faced by a woman trying to succeed as a serious painter at that time, also fed into her work.', 2170, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2171, 'Kahlo&#x2019;s paintings are disturbing and often horrific but also full of bright colours and pattern.', 2171, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2172, 'Kahlo lived with the Mexican muralist Diego Rivera for part of her life.', 2172, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2173, 'Philip Guston', 2173, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2174, 'American Guston made abstract expressionist work at the beginning of his career in the 1950s and early 60s.', 2174, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2175, 'He then had a crisis of belief in abstraction and began to paint figuratively.', 2175, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2176, 'Guston developed a distinctive personal iconography that included cigarette butts, ashtrays, horseshoes, shoes, and Klu Klux Klansmen&#x2019;s pointed hats, painted in a cartoon like style with heavy black outlines.', 2176, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2177, 'The objects in particular can be seen as self portraits.', 2177, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2178, 'Paintings include a pile of shoes, old and battered boots with the odd horseshoe, an ashtray overflowing with giant, very fat cigarette butts, and a series of paintings of figures wearing Klansmen&#x2019;s hats in which the figures are often facing each other as if trying to converse.', 2178, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2179, 'Guston typically used either a monochrome palette of grey, brown, black and white (for example in the painting of a pile of horseshoes), or a bright palette.', 2179, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2180, 'His bright colours are blue, red and a fairly bright light pink, the pink often used as a background.', 2180, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2181, 'Some of the Klansmen paintings are black on white.', 2181, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2182, 'Guston depicts a lonely world, yet not without a bleak humour, spending long hours in the studio smoking and trying to communicate with the rest of the world.', 2182, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2183, 'Sam Fernandez', 2183, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2184, 'American artist Fernandez made psychedelic paintings in the 1960s and 70s, which were sometimes used for record covers.', 2184, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2185, 'They consist of a richly dense backgrounds of patterns and flowers flowing into the main element of the image.', 2185, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2186, 'Fernandez&#x2019;s work influenced graphic design and was re discovered in the 1990s by a new generation of artists.', 2186, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2187, 'Nancy Spero', 2187, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2188, 'Spero&#x2019;s narrative paintings include small figures.', 2188, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2189, 'She also made a work called A Tribute to Anna Mendieta (the wife of artist Carl Andre who died when she fell from the 30th floor of a building, reputedly pushed by Andre).', 2189, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2190, 'This work is a pair of red handprints at the top of the gallery wall, which are dragged in a red smear down the wall as if someone with bloody hands was trying to hold on.', 2190, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2191, 'Helmut Newton', 2191, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2192, 'Although not a painter, German photographer Newton was very influential among artists.', 2192, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2193, 'He made black and white or occasionally coloured photographs of women, naked or clothed, but always objectified as glamorous, made up and fashionable.', 2193, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2194, 'Newton always photographed his models wearing very high heels.', 2194, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2195, 'Newton&#x2019;s images fell out of favour for a time in the 1970s when feminist critics claimed back the female form, but he continued to make work.', 2195, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2196, 'Newton&#x2019;s women often seemed like objects for male pleasure but in fact they have a strange autonomy, despite their nakedness.', 2196, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2197, 'Sometimes several women might be photographed together as in a well known image of several models standing in a group staring at the camera.', 2197, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2198, 'EARLY TWENTIETH CENTURY SCULPTURE', 2198, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2199, 'Henry Moore', 2199, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2200, 'Moore, a British artist born at the beginning of the twentieth century, began as a figurative sculptor, but later became a pioneer of semi abstract sculptural form in Britain, and made many public commissions.', 2200, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2201, 'Like his peer Barbara Hepworth, Moore&#x2019;s sculptures often have holes through them and hollows; he too was interested in representing the &#x2018;void&#x2019; sculpturally.', 2201, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2202, 'He worked in stone, bronze and clay.', 2202, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2203, 'Unlike his contemporaries, however, Moore did not make smooth surfaced works; his roughly modelled sculptures are like giant bones, and always refer clearly to the human form.', 2203, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2204, 'For example a reclining nude (a favourite form for Moore) might be abstracted from a series of voids and hollows, as if it were a piece of driftwood that had been worn away.', 2204, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2205, 'A standing figure might have a large space where the belly would have been.', 2205, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2206, 'Heads are featureless and the proportions of the body adjusted to suit the form that Moore was trying to achieve.', 2206, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2207, 'Moore&#x2019;s sculptures are often sited in rural landscapes and parks, and indeed it was the way in which the human form could be made to look as if it were part of the landscape that interested Moore.', 2207, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2208, 'A late example of this is an arch (around 1960) made for a lakeside site in Hyde Park in London which seems to be constructed of three monumental bones, two standing on their ends, the other balancing across the two.', 2208, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2209, 'Moore made a large number of drawings, both as preparatory sketches and in their own right.', 2209, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2210, 'His drawings are realistic and anatomically accurate, as shown in a series of studies of hands.', 2210, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2211, 'As well as drawing the figure, he made a series of impressions of people sheltering from bombs in an underground station during World War Two.', 2211, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2212, 'Jacob Epstein', 2212, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2213, 'A British sculptor whose best known work is Rock Drill, the head and torso of a futuristic automaton like creature with a head shaped like an animal skull.', 2213, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2214, 'The breastplate ribcage is carved with angular geometric lines and the head is turned to one side.', 2214, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2215, 'Some of Epstein&#x2019;s work reflects the agony of war.', 2215, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2216, 'Epstein worked mostly in stone although he did make some bronze casts.', 2216, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2217, 'Jacob and the Angel is a massive male and female figure both with huge thick limbs embracing each other.', 2217, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2218, 'It is carved from a tan coloured but translucent stone.', 2218, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2219, 'Epstein made a similar carving of a prone figure, a little like an Egyptian mummy.', 2219, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2220, 'Elisabeth Frink', 2220, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2221, 'British artist born in the 1930s who has made bronze heads, busts and equestrian statues from the 1960s onwards.', 2221, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2222, 'Frink is particularly known for her distinctive thin figures riding horses bareback whose tiny heads have strangely flat features.', 2222, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2223, 'The surface of the sculptures is usually roughly modelled.', 2223, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2224, 'Frink&#x2019;s work can be seen in many public sites in London.', 2224, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2225, 'Niki De St Phalle', 2225, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2226, 'French artist who makes large and small (ranging from table sized to outdoor public sculptures) papier m&#xe2;ch&#xe9; and fibreglass sculptures of human and animal forms.', 2226, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2227, 'These are somewhat like totem poles or other tribal art objects, being mainly highly stylised white smoothed forms that are richly decorated with hand painted patterns particularly on the head and limbs.', 2227, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2228, 'Louise Bourgeois', 2228, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2229, 'Bourgeois is an American sculptor born in the 1920s.', 2229, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2230, 'She has had one of the longest careers of any female artists of her generation.', 2230, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2231, 'Bourgeois has made works that are both intimate and monumental in scale, and all her work has a strong female sensibility.', 2231, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2232, 'She has made, carved and cast sculpture and installations.', 2232, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2233, 'Notable are her carved marble works of the 1950s and 60s, they are often quite small organic curvy shapes suggestive of the inside of the body or of plant growth.', 2233, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2234, 'One of these is made in pink marble set on a plinth.', 2234, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2235, 'Installations include room structures that have furniture and objects in them.', 2235, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2236, 'Most recently she has made a monumental 30 metre high bronze spider.', 2236, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2237, 'Bourgeois repeatedly uses the same motifs such as the shoe and the spider.', 2237, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2238, 'Barry Flanagan', 2238, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2239, 'A British sculptor who mainly made semi abstract stone sculptures until the 1980s when he began to make figurative work and took the hare as his motif.', 2239, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2240, 'Flanagan achieved great success with a series of sculptures featuring the figure of a leaping hare roughly modelled in clay, its legs exaggerated in length, cast in bronze, often painted in ultramarine, set upon a plinth made of a crisscrossed rectangle of lengths of planed wood.', 2240, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2241, 'This hare and plinth combination was repeated in many different materials.', 2241, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2242, 'Ed Keinholz', 2242, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2243, 'Keinholz created several installations including the Beanery, a tiny kiosk set up as a bar that the viewer could enter to experience the disorienting scale of the space inside it.', 2243, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2244, 'Keinholz&apos;s installations usually featured life size figures cast from plaster, unpainted with real furniture, fittings and fabric.', 2244, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2245, 'Duane Hanson', 2245, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2246, 'An American artist who began making his very well known life casts of people in the 1970s.', 2246, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2247, 'Hanson&#x2019;s fibreglass casts of himself and others are the sculptural equivalent of photo realist paintings.', 2247, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2248, 'The casts are painted, have real hair added and are dressed to look as if they are real, prompting a double take by the viewer.', 2248, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2249, 'Hanson chose very ordinary subjects, for example a police officer, a museum attendant, a pair of overweight and badly dressed American tourists, a motorbike accident victim prostrate with his bike, and a cleaning woman.', 2249, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2250, 'Allen Jones', 2250, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2251, 'Jones is a British artist who achieved notoriety in the 1960s and 70s for his sculptures of women as furniture.', 2251, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2252, 'Feminists in particular found his work hard to accept and although his work declined in popularity during the 1980s the images of some of his sculptures are known all over the world.', 2252, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2253, 'Jones&#x2019;s sculptures are made by modelling idealised life size female figures.', 2253, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2254, 'These are cast in fibreglass, spray painted realistically and dressed in clothes, usually underwear.', 2254, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2255, 'A characteristic work is a coffee table &#x2013; a glass top is placed on the back of a kneeling woman who is wearing a basque, stockings and suspenders and extremely high heels.', 2255, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2256, 'Other furniture includes a similar table top placed on the shins of a woman lying on her back with her legs bent at hip and knee, shins parallel to the floor and bound with cords to form a &#x2018;z&#x2019; shaped support and a stool (a woman crouched over and bound with a specially made upholstered leather seat strapped on to her back, for example).', 2256, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2257, 'Jones also made paintings.', 2257, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2258, 'Daniel Spoerri', 2258, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2259, 'Italian sculptor who was part of the Arte Povera movement in the late 1960s and early 1970s.', 2259, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2260, 'Spoerri is best known for his upside down table wall piece, a table top strewn with the remains of a meal &#x2013; wine glass with dregs, dirty plate and brimming ashtray all fixed to the table and defying gravity.', 2260, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2261, 'Joseph Cornell', 2261, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2262, 'An American artist known for making work in boxes.', 2262, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2263, 'Cornell&#x2019;s boxes vary in size and materials, they sometimes have doors, or interior shelves or sections, are often painted, covered in fabric or leather, and contain found items and printed material.', 2263, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2264, 'They are like three dimensional collages.', 2264, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2265, 'Abstract sculptors found a wide range of new materials and working methods, expanding the definition of sculpture.', 2265, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2266, 'Lynda Benglis', 2266, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2267, 'An American sculptor working in the 1970s, Benglis made sculptures from brightly coloured polyurethane foam, poured onto the floor and allowed to expand and cohere.', 2267, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2268, 'Lee Bonteco', 2268, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2269, 'Bontecou&#x2019;s wall based constructions made from metal, acrylic sheet, perspex and rivets have the appearance of flowers but due to their materials they also reference aircraft fuselages.', 2269, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2270, 'Eva Hesse', 2270, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2271, 'Hesse was born in the 1940s and died in 1969 but her prodigious output is now seen as an important counterpoint to the new and radical minimal sculpture being made at the time, and as also as a turning point for women artists who were in the minority, particularly in this field.', 2271, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2272, 'Hesse combined current sculptural preoccupations with unorthodox and traditionally feminine materials and methods.', 2272, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2273, 'Her achievement was recognised very early and she was included in several seminal exhibitions including one curated by Lucy Lippard, defining the new work.', 2273, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2274, 'Hesse began her career around 1960 as a painter, training under Joseph Albers.', 2274, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2275, 'She made figurative paintings and self portraits, gradually turning to abstraction, until she had a crisis of confidence in her ability to paint.', 2275, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2276, 'Hesse ceased to make work until she and her husband travelled to Dusseldorf where a German industrialist collector had offered them a studio residency in a disused factory that he owned.', 2276, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2277, 'There she found an abundance of materials and machine parts lying around, and she began to draw these parts and experiment.', 2277, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2278, 'Working in the factory Hesse produced a number of odd abstract drawings based on the machine parts.', 2278, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2279, 'She began to make wall based three dimensional paintings, modelling the surface of the work and adding string following the shapes, as well as projecting elements, the whole of which she painted.', 2279, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2280, 'Then she went on to make sculptures with the materials she found on the factory floor.', 2280, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2281, 'Her first successful ones were cubes of steel mesh sheets, open on one side.', 2281, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2282, 'Hesse pushed equal lengths of rubber tubing through the holes in the mesh in the manner of rug tufting, to create a furry effect on the interior of the box.', 2282, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2283, 'This painstaking task produced two sculptures (one with black tubing, one with transparent tubing), which combined the (traditionally female) techniques of handicraft with those (traditionally male) of industrial fabrication used to make minimal sculpture.', 2283, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2284, 'Hesse continued to make wall reliefs from modelling materials, string and paint including Rosy, a breast like form on a buff coloured round with a spiral of string painted in graduated shades from pink to red.', 2284, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2285, 'Hesse&#x2019;s interest in concentric circles was worked in these reliefs and in her Dot graph paper drawings, delicate pencil or pen drawings in which rectangles are filled with row of tiny small circles or rows of concentric circles coloured in with pencil.', 2285, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2286, 'The string forms resulted in a wall work consisting of a row of about 25 hemispheres 30 cm in diameter covered with string spiralling round, placed in a horizontal line on a long strip about 40 cm wide, at picture height on the wall.', 2286, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2287, 'From the centre of each hemisphere, cords project and extend to the floor where the ends lie.', 2287, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2288, 'The whole piece is painted grey.', 2288, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2289, 'Hang up (1967) is a seminal work by Hesse consisting of a two metre by one and a half metre empty frame on the wall, bound with cloth bandage and painted light grey.', 2289, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2290, 'A heavy gauge wire loop projects outwards from the frame that is also wrapped with cloth bandage.', 2290, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2291, 'The loop is attached on the bottom right and top left corners and looping out about two metres from the wall and back again.', 2291, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2292, 'The viewer may stand inside the loop, in which case they seem to be lassoed by the work.', 2292, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2293, 'This work is an abstract but concrete representation of the nature of looking at paintings.', 2293, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2294, 'String was one of Hesse&apos;s favoured materials along with latex and fibreglass.', 2294, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2295, 'She made a string mesh consisting of lengths of cord dipped in latex and strung from the ceiling to form an abject enlarged untidy web.', 2295, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2296, 'She took net shopping bags and stuffed them with scrunched up plastic sheeting, hanging them in clusters, which are strangely anthropomorphic, on the wall.', 2296, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2297, 'She photographed herself lying on a bed covered with a mass of string like spaghetti.', 2297, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2298, 'Hesse also used rubber tubing that she filled with plaster to create sausage like forms.', 2298, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2299, 'Her work often made allusions to the male and the female body.', 2299, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2300, 'The preoccupation with tubular forms and repetition characterises Hesse&#x2019;s later works, Accession and Accretion.', 2300, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2301, 'Accession consists of two 50 cm square black panels mounted on the wall with a space between them filled with a mass of silver wires.', 2301, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2302, 'Accretion is a row of one and a half m long fibreglass tubes, slightly crumpled, leaning against the wall placed at regular intervals.', 2302, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2303, 'Similar works are a casual arrangement of caved in fibreglass cylinders about 70 cm high and 50 cm wide standing on their ends on the floor, and rows of latex spheres on a sheet.', 2303, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2304, 'Dan Flavin', 2304, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2305, 'An American artist working in the 1970s and 80s, Flavin used fluorescent tubes and the coloured light they produce as his medium.', 2305, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2306, 'He created sculptures by leaning the tubes against the wall, sometimes two or three, sometimes a whole row, sometimes placed casually at different angles, sometimes measured and at the same angle.', 2306, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2307, 'Some tubes might be placed flat on the floor.', 2307, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2308, 'The transformers and cables are very visible and are part of the work.', 2308, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2309, 'Example of works are a cruciform formation of cold blue coloured tubes mounted on the wall and three tubes, one red, one blue and one green.', 2309, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2310, 'Maya Lin', 2310, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2311, 'Lin, an American artist, was chosen by competition to design the Vietnam War memorial in Washington.', 2311, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2312, 'She designed a long highly polished black marble wall, inscribed on which in columns are the names of all those who lost their lives in combat in the Vietnam War.', 2312, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2313, 'The wall is recessed at ground level, and appears to be gradually revealed as the ground in front of it is excavated to slope down.', 2313, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2314, 'The top of the wall remains level parallel with the ground and viewers descend passing along the wall, which becomes higher in relation to them the further along the wall they walk.', 2314, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2315, 'The memorial is extremely popular, due to its simple formal qualities and its gentle interactivity with the viewer.', 2315, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2316, 'The memorial invites participation and takes the viewer down below ground level to see the names symbolically buried but rising up to meet the light.', 2316, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2317, 'Its surface reflects the viewers, so that a multitude of faces appear on its surface.', 2317, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2318, 'The traditional methods of casting and carving continued to be popular, but many sculptors now began to use welded steel.', 2318, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2319, 'Ellsworth Kelly', 2319, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2320, 'An American sculptor who is best known for his 1960s to 80s work that consists of wall mounted steel shapes, distorted rhomboids, parallelograms and triangles.', 2320, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2321, 'They are immaculately spray painted in matt primary colours and black and white, and butted up together one colour and shape against another, to create abstract works that are both sculpture and painting and have a contemplative lyrical presence.', 2321, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2322, 'Michael Kenny', 2322, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2323, 'British artist Kenny made wood and metal abstract sculpture.', 2323, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2324, 'David Smith', 2324, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2325, 'British artist working from the 1960s onwards who made large welded steel sculptures.', 2325, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2326, 'Philip King', 2326, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2327, 'King is a British artist who made large steel sculptures between the 1960s and 80s.', 2327, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2328, 'King made a number of public commissions, many of which can still be seen, for example in Fulham in London there is a red painted tubular steel structure work.', 2328, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2329, 'King also made the designs for the decoration of the walls of Embankment underground station in London.', 2329, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2330, 'Hubert Dalwood', 2330, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2331, 'A British sculptor born in early 1930s who died in the 1970s, Dalwood made carved, cast and constructed sculptures from stone, bronze, acrylic resin, acrylic sheet and metal.', 2331, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2332, 'He also made a few paintings.', 2332, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2333, 'His early works were totemic stone objects and tabletop sculptures that were a bit like small abstract sculpture gardens, cast in aluminium or bronze.', 2333, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2334, 'He used tubular or square forms and wavy lines placed on a rectangular base that were cast in one piece and also made sculptures from acrylic with metal wire threaded through.', 2334, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2335, 'As he became successful Dalwood began to be commissioned and he made a number of public works.', 2335, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2336, 'One example is a construction in a park made from brushed steel tubes of a large diameter fixed vertically to the ground in a cluster, reaching about 5 metres in height, curving around at the top like giant geometric plant stalks.', 2336, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2337, 'Another is an egg shaped bronze sculpture about one and a half metres in length lying on its side with some detail on its surface.', 2337, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2338, 'Alexander Calder', 2338, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2339, 'British sculptor working in the 1940s to 60s who became best known for his kinetic sculpture and mobiles, Calder is one of the very few artists to have used the mobile successfully as a form in sculpture.', 2339, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2340, 'Calder&#x2019;s sculptures generally use circles, spheres and triangular shapes and rods.', 2340, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2341, 'They are made in sheet metal, painted typically in black and white with red, yellow and blue.', 2341, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2342, 'Antony Caro', 2342, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2343, 'Caro is a British artist who became very well known in the 1960s for his welded steel sculptures.', 2343, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2344, 'Caro was the most successful of a group of British artists who made large scale abstract steel sculptures in the 1960s and early 1970s.', 2344, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2345, 'His were either cut from steel plate, or made of round and square cross section steel tubes, rods and I beams which were sometimes left to rust, but sometimes spray painted in primary colours.', 2345, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2346, 'Caro was one of the first sculptors to make semi abstract works on such a large scale.', 2346, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2347, 'Caro was influenced by the scale of ambition of his American contemporaries but his subject matter was initially the English landscape; his sculptures depict landscapes, although they appear abstract.', 2347, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2348, 'Caro used steel to make very open structures, often rather long and low, about 12 metres long and 2 metres high describing a kind of vista in space.', 2348, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2349, 'One might be painted bright green, another bright yellow.', 2349, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2350, 'Smaller works might be made from shapes cut from sheet steel put together in which the ragged edge from the cutting tool is often left unfinished.', 2350, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2351, 'In the 1990s Caro made a number of small steel sculptures of a chair based on the chair in Van Gogh&apos;s painting of his own bedroom.', 2351, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2352, 'Caro had been synonymous with a style of sculpture that was predominant in Britain for a decade, not least due to his years of teaching at St Martins School of Art in London, then a leading sculpture school.', 2352, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2353, 'Lynn Chadwick', 2353, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2354, 'Chadwick&apos;s figurative bronzes range from life size to very small, around 30 cm high, human figures.', 2354, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2355, 'They are angular, with stick like legs, flattened irregular trapezoid bodies, and heads that are either pyramid or cube shaped to denote female and male figures.', 2355, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2356, 'Chadwick was interested in the difference between male and female forms in terms of body language.', 2356, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2357, 'The bronzes mostly have a blue green coppery patina.', 2357, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2358, 'John Chamberlain', 2358, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2359, 'Working in the 1960s American artist Chamberlain made sculptures from compressed dumped cars that he either retrieved from the compressing press or took to be compressed.', 2359, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2360, 'The resulting cubes were exhibited as sculpture.', 2360, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2361, 'He sometimes extracted compressed parts of cars that he combined to make into sculptures.', 2361, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2362, 'Eduardo Chillida', 2362, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2363, 'Mexican artist Chillida is a sculptor who made monumental steel sculptures which were usually site specific, often situated in natural environments.', 2363, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2364, 'For example, one of his characteristic M or comb like structures is placed on a cliff top to rust and acquire its orange red colour.', 2364, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2365, 'During the 1980s, artists began to have a far greater variety of media at their disposal.', 2365, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2366, 'Home video made it possible for anyone to shoot and edit films and large colour photographic prints were affordable.', 2366, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2367, 'Digital technology was in its infancy but desk top publishing, graphics programmes and digital printing began to make an impact on artist&apos;s practise.', 2367, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2368, 'POSTMODERNISM', 2368, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2369, 'In the 1970s modernism had reached an impasse.', 2369, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2370, 'The art object was no longer considered to have an autonomous existence; its meaning was constructed by the subjective interaction of the viewer.', 2370, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2371, 'The work of Walter Benjamin on the aura of art, of Jean Baudrillard, Frederic Jamieson and Roland Barthes on art, culture and the nature of reality and Ferdinand de Saussure on semiotics were influential.', 2371, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2372, 'All cultural forms were re examined and language was subjected to a rigorous philosophical analysis by structuralism writers and psychoanalytic theorists.', 2372, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2373, 'Feminist theorists argued for an entire redefinition of subjectivity on psychoanalytical and semiotic grounds, influenced by the work of Jacques Lacan.', 2373, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2374, 'Conceptual artists had been making work that examined the condition of art and the status of the art object, and soon artists working in all media began to follow suit.', 2374, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2375, 'The 1980s was the era of conceptualism, of theory based practise, appropriation and the real.', 2375, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2376, 'For most post modern theorists, the real world was no more real than the reconstructed world of representation For many artists the act of appropriation was a way of understanding the point in its history that art had reached.', 2376, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2377, 'They freely borrowed elements from the works of others and added these to their own.', 2377, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2378, 'The paintings of David Salle are an example of this.', 2378, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2379, 'Artists also investigated the nature of reality, known as &apos;the real&apos; and suggested another &apos;hyper reality&apos; through acts of mimesis.', 2379, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2380, 'Postmodernism made it possible to argue that art was by definition conceptual and that subjectivity was essential in the construction of meaning of an art object.', 2380, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2381, 'ACTIVIST ART', 2381, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2382, 'Act Up', 2382, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2383, 'Act Up were a group of gay rights activists that included artists, working in America in the 1980s.', 2383, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2384, 'Act Up created poster campaigns, subverted advertising and made use of official statistics to point out discriminatory practise.', 2384, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2385, 'Group Material', 2385, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2386, 'A Toronto based group of artists and activists, producing collaborative works, solo works, publishing, running a gallery, and commissioning projects and books who included the painter Jochen Klein.', 2386, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2387, 'Guerilla Girls', 2387, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2388, 'A group of anonymous feminist activists who were working in New York in the late 1980s and early 90s, the Guerilla Girls were named for their wearing of gorilla masks when they went to organised demonstrations.', 2388, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2389, 'They also used the banana as an emblem, along with the gorilla suit a prop of slapstick humour and a visual pun on both the diet of gorillas and the offering of an opportunity to institutions who fail to represent women adequately to &#x2018;slip up&#x2019; (on the proffered banana skins).', 2389, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2390, 'The group is thought to have included a number of members who went on to become prominent artists, for example Sue Williams.', 2390, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2391, 'The Guerilla Girls were a product of an era in which feminism was well established and attention was turned from campaigning against discriminatory practises in everyday life, work and the home, to those in culture.', 2391, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2392, 'The group produced a number of seminal posters and postcards for example a list of reasons &#x2018;Why There are no Great Women Artists&#x2019;, and a list of statistics about the proportional representation of women artists in art museums.', 2392, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2393, 'These texts achieved widespread distribution because they were clever in their use of graphics and advertising to get message across, and because the appearance of the gorilla suited members staging demonstrations at institutions and relevant events was always newsworthy.', 2393, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2394, 'PHOTOGRAPHY', 2394, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2395, 'Berndt and Hilla Becher', 2395, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2396, 'German husband and wife working together born around 1950 whose work became known in the 1980s, series of black and white photos of industrial sites, silos and water towers that imbue the subjects with a formal sculptural quality.', 2396, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2397, 'Nan Goldin', 2397, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2398, 'During the 1980s and early 1990s American artist Goldin obsessively recorded the lives of her friends photographically.', 2398, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2399, 'People are photographed sleeping, eating, sober, drunk, fixing up, having sex, getting dressed, in the bath, on the toilet, kissing, cooking, talking, singly and in groups, meeting the camera or looking away.', 2399, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2400, 'Most of them are artists, musicians, actors and their friends; there are straight and gay couples, single parents, families and children.', 2400, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2401, 'Goldin creates a sense of a window on private lives but never a sense of intrusion.', 2401, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2402, 'A subject might have a black eye, or be menstruating.', 2402, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2403, 'The subjects are always relaxed in the presence of the camera.', 2403, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2404, 'The resulting hundreds of images were exhibited in groups, usually printed fairly small, approximately fifty cm high.', 2404, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2405, 'The groups of images became larger and they were installed in grid formation.', 2405, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2406, 'Ultimately they were shown as a continuously running slide projection of hundreds of images.', 2406, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2407, 'Goldin&#x2019;s work became a testament to and document of the lives of a generation many of her whom were of the generation that was most drastically affected by HIV.', 2407, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2408, 'This body of work is a memorial, although it is not in any sense melancholic but experienced as a record of the intimate lives of one generation of New Yorkers.', 2408, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2409, 'James Casebeere', 2409, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2410, 'Casebeere made a series of photographs in the late 1980s of scenes that he had constructed entirely from cut, folded and shaped paper, for example a rural scene with a river, trees and a canoe, photographed in black and white.', 2410, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2411, 'There is no particular attempt at realism or trompe l&#x2019;oeil, the scenes are a combination of fairytale and cartoon, given a sombre seriousness by the use of black and white.', 2411, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2412, 'This relates them back to early twentieth century American landscape photography.', 2412, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2413, 'John Coplans', 2413, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2414, 'Coplans, a British artist born in the 1950s, made black and white photographs of his own naked body and parts of his more or less average male body, including his genitalia, in detailed close up.', 2414, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2415, 'The texture of his skin, hairs and wrinkles are sharp and nothing is left to the imagination.', 2415, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2416, 'Coplans presents the male body as a counter to the over exposed female body.', 2416, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2417, 'His presentation of the male body reveals its frailty, and significantly it is an entirely unsexualised presentation.', 2417, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2418, 'Philipe Lorca di Corcia', 2418, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2419, 'Photographer who takes images of everyday scenes and shows them in groups.', 2419, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2420, 'Michel Francois', 2420, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2421, 'Belgian artist who makes large scale photographic installations.', 2421, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2422, 'Gilbert and George', 2422, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2423, 'Two British artists born in the 1950s who have lived and worked together in a longstanding partnership.', 2423, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2424, 'They began to work together in their twenties, when they moved into a house in London&#x2019;s East End and began their existence life as living art, their daily lives rigidly habitual.', 2424, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2425, 'Gilbert and George became as well known for their lifestyle and their deadpan personae as for their work; in the early years of their careers rarely speaking about their work or lives together.', 2425, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2426, 'They parried all interviewers&#x2019; questions by assuming an impenetrably eccentric manner so that was never clear whether or not they were having the last laugh.', 2426, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2427, 'Gilbert and George lived together in a sparsely furnished house, wore tweed suits, hats and overcoats, ate in the same caf&#xe9; every day of the year, and were never seen without each other.', 2427, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2428, 'Their early work was performance: they held soir&#xe9;es with invited performers, conducted with an anachronistic formality, including letterpress invitation cards.', 2428, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2429, 'They became well known for their work &#x2018;Underneath the Arches&#x2019;, made in about 1975, for which they became &#x2018;singing sculptures&#x2019;.', 2429, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2430, 'They stood on a plinth, their clothes and bodies entirely covered in silver paint, underneath the arches of one of the bridges over the river Thames and sang the music hall song of the same name continuously.', 2430, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2431, 'In the 1980s Gilbert and George began to make the collaborative photographic work for which they are now known, photo collages made by taking self portraits, in which they appeared full length, usually one on each side of the image using the kind of symmetry found in religious diptychs.', 2431, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2432, 'Initially these were small black and white works, the subject matter of which included images of London, flowers and plants, often repeated in a mirror image.', 2432, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2433, 'Later they began to photograph young men and boys that they had met around London and the compositions began to have a scatological and sexual theme and were often directly abusive.', 2433, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2434, 'By the 1990s, Gilbert and George were making works that set out to shock, using images of human faeces and naked men, including themselves.', 2434, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2435, 'The images are printed in square sections which are placed together in a grid to make a large image often three metres square.', 2435, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2436, 'Each section has a thin frame which is usually red so that there is no pretence that the work is one large image.', 2436, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2437, 'The Gilbert and George photo collage became an instantly recognisable trademark.', 2437, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2438, 'John Hilliard', 2438, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2439, 'British artist who makes photographs of landscape and architecture, presented on wall mounted light boxes.', 2439, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2440, 'Sylvia Kowalski', 2440, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2441, 'American conceptual artist.', 2441, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2442, 'Robert Mapplethorpe', 2442, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2443, 'A photographer working in New York in the 1980s and early 90s, Mapplethorp became notorious for his photographs of gay men.', 2443, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2444, 'The men are often naked or semi clothed, and the images are sexually unambiguous such as Man in a Polyester Suit which shows an African American man resting his penis on a stool, and another photograph showing a man urinating into another&#x2019;s mouth, both men dressed in leather.', 2444, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2445, 'Photographs like these led to Mapplethorpe being attacked by the Christian right and his exhibitions were denounced as pornography.', 2445, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2446, 'The fact that museums spent public money on exhibiting Mapplethorpe&apos;s work led to a full scale row in the United States senate and other artists were dragged into the debate.', 2446, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2447, 'Senator Jesse Helms led the attack supported by The Association for the American Family and religious organisations.', 2447, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2448, 'The result was a substantial decrease in the amount of support given to artists by the National Endowment for the Arts, the United States government arts subsidy fund.', 2448, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2449, 'The existing obscenity laws were reassessed and there was a call for a revision of the censorship laws in order to make it easier to close an exhibition or require special conditions to be met.', 2449, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2450, 'There were many counter claims, not just by Mapplethorpe, of discrimination on the grounds of sexuality.', 2450, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2451, 'Mapplethorpe said of his work that he photographed images of love and trust, and that even the most &#x2018;sado masochistic&#x2019; of his images represented supreme trust, love and vulnerability on the part of the participants.', 2451, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2452, 'His defenders claimed that if his images were of heterosexual couples there would have been no such outcry.', 2452, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2453, 'The case went to court and a ruling was made that the photographs defined as obscene could only be exhibited in a specially constructed screened off area, with a clear indication to the public of the contents of these works.', 2453, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2454, 'The case increased the public interest in the work and made Mapplethorpe one of the best known photographers in the world.', 2454, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2455, 'Mapplethorpe&#x2019;s themes were love, sex and death.', 2455, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2456, 'He made many self portraits the best known of which shows him wearing a leather biker jacket with chains and a leather cap.', 2456, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2457, 'Another shows Mapplethorpe as a young man standing on a fire escape with the singer Patti Smith.', 2457, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2458, 'A photograph taken just before his death shows a visibly frail Mapplethorpe holding a cane topped with a skull and crossbones emblem.', 2458, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2459, 'Mapplethorpe made a series of photographs of flowers, mostly lilies and other exotic flowers, which are also sexual images, sometimes reminiscent of Georgia O&#x2019;Keefe paintings, usually in black and white but some are colour.', 2459, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2460, 'He also photographed the body builder Lisa Lyon, whose physique he considered to be perfect.', 2460, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2461, 'Robert Mapplethorpe died in 1994.', 2461, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2462, 'Andres Serrano', 2462, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2463, 'Serrano, an American artist born in the 1950s, is notorious for his work Piss Christ, which caused a furore and demands for its censorship on the grounds of obscenity and blasphemy from American right wing and religious groups.', 2463, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2464, 'Serrano immersed a cheap plastic figure of Christ on the cross in a tank of his own urine with a light behind it and took a photograph.', 2464, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2465, 'Christ is seen submerged in a red and golden light resulting in an image of glorification.', 2465, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2466, 'Serrano, brought up as a Catholic, continued to make controversial images such as the Last Supper and a Pieta (both black statuettes immersed in tanks, with the bubbles adhering to them adding texture.', 2466, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2467, 'He made a series of photographs of the blending of blood and milk in a dish, and of spurts of semen frozen in mid air at the point of ejaculation &#x2013; white streams on a black background, and a series of images made in a morgue of corpses titled by the way in which they died; drowned, poisoned, stabbed.', 2467, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2468, 'Serrano stated that all his work was an entirely respectful investigation into sex, life and death and the relation of these to spirituality and religion.', 2468, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2469, 'John Stezaker', 2469, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2470, 'British artist born in the 1950s who makes photographic collage and printed work.', 2470, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2471, 'Stezaker has made photographs of landscapes reflected in water, which he presents upside down so that they appear to be the right way up at first.', 2471, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2472, 'He has made a series of large black and white prints based on an old photograph of a nude, which he has distorted.', 2472, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2473, 'Susan Trangmar', 2473, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2474, 'British artist born in the late 1950s who makes photographic work.', 2474, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2475, 'Hannah Villiger', 2475, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2476, 'Villiger made a series of Polaroid photographs of her own naked body holding the camera at arms length.', 2476, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2477, 'The resulting series of images (it took several to document the whole of her body in this way) are printed enlarged so that the parts of Villiger are life size, and exhibited in a row.', 2477, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2478, 'Jo Spence', 2478, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2479, 'A British artist born in the late 1940s who made photographic work from the 1970s onwards.', 2479, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2480, 'Spence, a large woman, used herself and her male partner as models to make a number of works that explore preconceived ideas about ideal beauty, masculine and feminine identity and relations.', 2480, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2481, 'The photographs were sometimes printed life size.', 2481, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2482, 'In the 1980s Spence developed breast cancer but continued to photograph her ravaged body during and after mastectomy and radiotherapy.', 2482, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2483, 'Spence&#x2019;s photographs are often accompanied with written text in a diary format.', 2483, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2484, 'PERFORMANCE', 2484, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2485, 'Bobby Baker', 2485, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2486, 'A British performance artist born around 1950 who made a series of performances based on food in the 1980s.', 2486, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2487, 'Baker returned to art in her late forties after raising a family and training as painter, but began to make performance art when she found that a painter&#x2019;s life was not compatible with bringing up a family.', 2487, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2488, 'She found a parallel between painting and its history and the creativity inherent in domestic and family life.', 2488, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2489, 'In her first performance, &#x2018;Drawing on a Mothers Experience&#x2019; she made a &#x2018;painting&#x2019; by telling the story of the night one of her children was born by presenting samples of the food that she consumed before and during her labour and using it to make a painting on a bed sheet.', 2489, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2490, 'She dripped black treacle, splattered jam, and printed with steaks.', 2490, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2491, 'The resulting work was intended to be compared to an abstract expressionist painting.', 2491, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2492, 'Baker obliterated it by sieving icing sugar over it and rolled herself up in the sheet.', 2492, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2493, 'An Edible Family in a Mobile Home was a family constructed from cake and icing and placed in a caravan.', 2493, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2494, 'Baker also staged a performance in her own home, inviting the audience into her kitchen to watch her discuss menial domestic tasks and what she enjoys about them, for example the freshness of washed cabbage leaves and the fun of icing (she poses on a revolving cake stand).', 2494, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2495, 'After each action she pins a symbolic item onto her white coat.', 2495, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2496, 'Baker also did a performance in which she gets into a bath of chocolate custard.', 2496, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2497, 'Baker draws on the work of 1970s feminist artists who made the domestic their subject but adds humour.', 2497, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2498, 'Leigh Bowery', 2498, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2499, 'A British fashion designer, club promoter and artist whose work defies definition but was very influential, Bowery always wore his own designs, usually involving heavily padded lycra, to change his shape substantially.', 2499, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2500, 'He was known for his mask like make up, often with big black eyes, rubber and fetish wear, extremely high heeled shoes and boots.', 2500, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2501, 'He morphed between a male and female look, both sexual and asexual.', 2501, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2502, 'Bowery&apos;s club night Taboo inspired a generation of people to dress up, and he became an icon, eventually exhibiting himself in the window of a London gallery as a living work of art.', 2502, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2503, 'Bowery died in the 1990s in his late thirties.', 2503, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2504, 'Cosey Fanni Tutti', 2504, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2505, 'British video and performance artist who has been working since the 1960s.', 2505, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2506, 'Fanni Tutti&#x2019;s most recent work is painting.', 2506, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2507, 'The work for which she is best known is a series of live events made on her own and with the band COUM transmission (later to become Throbbing Gristle).', 2507, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2508, 'Fanni Tutti often appeared half naked.', 2508, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2509, 'One image is always associated with her showing her reclining on a bed, wearing underwear but bare breasted and wearing a blindfold.', 2509, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2510, 'She made a number of photographic works imitating soft porn photography.', 2510, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2511, 'Karen Finley', 2511, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2512, 'Karen Finley is an American performance artist whose work, like Mapplethorpe&apos;s, attracted the attention of the American Christian Right.', 2512, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2513, 'Finley received public funding and became notorious when she was banned from performing a work in which she inserted pieces of yam into her vagina.', 2513, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2514, 'When she brought this work to London the venue at which she was to perform was forced to bow to local authority pressure and ban it.', 2514, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2515, 'Finley continued to make controversial performance work centring around themes of child abuse, sexual identity and the female body, often in the form of a monologue by a character who was in turns aggressive and profane.', 2515, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2516, 'Rose Finn Kelcey', 2516, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2517, 'British artist born in the 1950s, Finn Kelcey made a number of performance works in the 1980s and early 1990s, one using shadow puppets.', 2517, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2518, 'In the late 1990s she made Matador, a work for which she trained as a matador in Spain and took part in a bullfight, a work which existed only as documentation.', 2518, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2519, 'She later made an installation titled Steam Bed, which consisted of a large square brushed steel trough from which copious amounts of steam were emitted which was sucked towards an extractor fan of the same dimensions as the trough, creating an illusory solid form, a cube of steam between the two.', 2519, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2520, 'Ukeles Mierle Laderman', 2520, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2521, 'Laderman is an American artist who made a collaborative work with the New York Sanitation Department in the 1980s.', 2521, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2522, 'She staged a performance in which she shook the hand of every sanitation worked in New York, an action that highlighted the social invisibility of the waste disposal workers, those who carry out a daily task without which life would become untenable.', 2522, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2523, 'Another part of this project was the design and construction of a refuse collection cart with mirrored sides which was used on the daily refuse collection round.', 2523, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2524, 'As it travelled the city streets the people that created the refuse contained in it were reflected clearly in its sides.', 2524, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2525, 'James Luna', 2525, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2526, 'Born around 1950, Luna is a Native American living on a reservation who was known for his socio political art projects highlighting the discrimination against Native American Indians.', 2526, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2527, 'The best known of his works is a performed installation for which Luna had himself tranquillised and placed in a display case in a museum of native American artefacts during museum opening hours.', 2527, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2528, 'He remained in the case every day for a month, under close supervision.', 2528, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2529, 'Bruce Maclean', 2529, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2530, 'Scottish artist MacLean was born in the 1940s who made his best known work in London in the 1970s and 80s.', 2530, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2531, 'He made paintings, colourful gestural abstracts and performances, in which he was seen smoking a pipe and wearing a trilby hat.', 2531, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2532, 'Alistair Maclennan', 2532, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2533, 'A Scottish performance artist working in the late 1970s and 80s who made a controversial work at the Institute of Contemporary art in London in 1981 call Still Tills.', 2533, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2534, 'McLennan spent a week living in the gallery eating and sleeping surrounded by food, detritus and waste including bodily waste.', 2534, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2535, 'He also sorted through and arranged bags of refuse, which as the press reported included sanitary protection and nappies.', 2535, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2536, 'The title of the work was a comment on the end of consumerism and shopping and the beginning of a new self sufficiency and the artist was trying to show the possibility of this by living without purchasing anything for a week.', 2536, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2537, 'Other works of McLennan&apos;s were similarly time and endurance based.', 2537, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2538, 'Hermann Nitsch', 2538, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2539, 'Austrian performance artist who pioneered Viennese Actionism which is the name he gave to his live art practise which consisted of solo works and events or happenings that involved a large number of people.', 2539, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2540, 'Nitsch&apos;s performances usually took the form of some kind of self devised ritual, echoing religious, pagan or tribal sacrificial events and usually involves a degree of self inflicted pain or endurance, and often large amounts of animal blood and carcasses.', 2540, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2541, 'The events are conducted with great solemnity and conviction.', 2541, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2542, 'The large scale events have taken place in various locations, sometimes outdoors.', 2542, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2543, 'In one a number of volunteers were crucified and the participants covered in blood.', 2543, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2544, 'Nitsch thought of the blood as paint which he used to record of the event, producing large numbers of paintings and works on paper as well as photo and video.', 2544, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2545, 'Nitsch is perhaps best known for a performance in which he reputedly cut off (or at least mutilated) his own penis.', 2545, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2546, 'This is apparently documented by a series of photographs, which show Nitsch bandaging various parts of his body.', 2546, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2547, 'Gina Pane', 2547, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2548, 'British performance artist who made endurance works, most infamously one in which she continually bit her fingers in an attempt to loosen and remove her fingernails, periodically rinsing them in a bowl of milk.', 2548, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2549, 'She also made a performance during which she inserted rose thorns into her skin.', 2549, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2550, 'Pane was one of a number of artists working in Britain in the 1980s that resisted the idea of art as a commodity instead using their own bodies as medium and subject.', 2550, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2551, 'Annie Sprinkle', 2551, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2552, 'An American ex prostitute, artist and performer who is best known and in fact notorious for a live work in which she reclines on an armchair and invites the audience to examine her vagina through a speculum, to masturbate her and to ask her any questions they want.', 2552, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2553, 'Station House Opera', 2553, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2554, 'British performance art group led by Julian Maynard Smith who came to prominence in the 1980s with highly formalised repetition based works.', 2554, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2555, 'Performers dressed in ordinary clothes and not speaking would carry out everyday actions repetitively, without making allowance for each other&#x2019;s movements but avoiding collision.', 2555, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2556, 'The performers obeyed a set of rules and together a counterpoint effect was achieved as in the work Table Move, which consisted of performers moving furniture obsessively around a stage.', 2556, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2557, 'Later works built on the idea of physical risk, involving the performers in a variety of increasingly dangerous endurance based works.', 2557, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2558, 'One involved the performers sitting on and using furniture including tables, chairs and cupboards, while suspended high above a pedestrian area from the outside of a building.', 2558, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2559, 'Another, Bastille Dances, consisted of a day long construction and dismantling of a model of the Bastille form polystyrene blocks.', 2559, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2560, 'Stelarc', 2560, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2561, 'Australian artist who made performance works involving physical endurance and technology.', 2561, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2562, 'For one performance he inserted several hooks into his flesh and suspended himself from these, his body hanging horizontally from a bridge over Sydney Harbour.', 2562, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2563, 'Stelarc was interested in the body as a machine and for another work he had a robotic arm constructed, which was connected to his brain via electrodes so that he could control it by thought.', 2563, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2564, 'Gary Stevens', 2564, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2565, 'British artist born in the 1950s who made a number of performance works in the 1980s which took place in galleries.', 2565, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2566, 'In his work Stevens adopted a stylised performing persona and often used large numbers of soft toys.', 2566, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2567, 'Andre Stitt', 2567, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2568, 'British performance artist.', 2568, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2569, 'Steven Taylor Woodrow', 2569, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2570, 'A British performance artist who made a number of solo and group performances in the 1980s, his solo work consisting mainly of theatrical poetry readings, in which Taylor Woodrow appeared as a kind of Victorian gothic character behind a lectern reading Dada poetry accompanied with pyrotechnics and fire breathing.', 2570, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2571, 'Taylor Woodrow is best known for The Triptych Man and The Living Paintings, made between 1985 and 88.', 2571, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2572, 'The Triptych man was a performance for three people who were inserted into a costume made from three men&#x2019;s suits sewn together so that it had only three arms and legs each wide enough for two people&#x2019;s limbs.', 2572, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2573, 'The wearing of this forced the performers into a triangular formation, facing outwards, bound to and supporting each other but unable to see each other and only able to move by bouncing.', 2573, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2574, 'The Triptych man performed for several hours at a time, never speaking but often approaching people and sometimes remaining still for long periods while the performers rested.', 2574, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2575, 'The Living Paintings was static work for three performers, who were hung from the wall by a concealed harness wearing suits, painted a solid colour with matching makeup on any exposed skin and hair and contact lenses that featured an enlarged cornea with a white iris.', 2575, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2576, 'These performers also remained silent, relying for effect on inspiring embarrassment, uncertainty, and a desire to communicate in the viewer.', 2576, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2577, 'Wolf Vostell', 2577, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2578, 'Vostell, a German action artist working in the 1980s, organised large public performances in German cities, often involving pyrotechnics and explosives.', 2578, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2579, 'His interventions into public life were deliberately meant to refer to terrorist actions, and were intended to be disruptive although the formal and sculptural qualities of his actions were as important as their political aspect.', 2579, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2580, 'For one action he released a large amounts of smoke at a specific sites and times.', 2580, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2581, 'He led a group of people about a city ending in a derelict excavated site.', 2581, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2582, 'His ambitious works were extensively documented and Vostell wrote in detail about each one.', 2582, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2583, 'Sylvia Ziranek', 2583, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2584, 'British performance artist who made a number of works in the 1980s and has also published written work.', 2584, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2585, 'Ziranek&apos;s invented persona was central to her work and this was carried through into her appearance &#x2013; she always dressed in bright pink and often has pink hair.', 2585, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2586, 'INSTALLATION ART', 2586, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2587, 'Sophie Calle', 2587, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2588, 'A French artist born in the 1950s who has made a large body of project and research based work.', 2588, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2589, 'Calle&apos;s Following Piece is perhaps her best known work, a performative project made in Venice for which she selected a man to follow for a month.', 2589, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2590, 'He never became aware of her constant presence until the project was over since Calle adopted the techniques of undercover surveillance in her project, keeping a detailed diary with photographs, which she made into a series of text panels and presented as a documentary installation.', 2590, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2591, 'For another incognito work, Chambermaid, presented as text and image on the wall, Calle got a job as a chambermaid in a hotel.', 2591, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2592, 'She searched the rooms and luggage that she cleaned and made lists of what she found and what she deduced about the occupants of the room &#x2013; the kind of people they were, what their occupations were, why they were staying in the hotel.', 2592, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2593, 'She photographed the rooms and things in them that interested her.', 2593, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2594, 'Calle&apos;s interest in these works was in what the viewer could discover about an absent subject from the visual world that surrounds them and in how that subject can be reconstituted.', 2594, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2595, 'The viewer of the work is made aware of their position as voyeur which they share with the artist.', 2595, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2596, 'Calle subsequently continued her interest in subjectivity but began to work with people rather than observing them unseen.', 2596, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2597, 'The Blind involved asking blind from birth and those who had lost their sight since birth to describe images.', 2597, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2598, 'These descriptions are presented in place of images on the walls of a gallery giving a privileged place to the images of the mind&apos;s eye, images that would never normally become concrete.', 2598, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2599, 'For a similar work made with museum attendants Calle asked those who worked in a certain museum to describe the paintings that they observed daily in the course of their employment when those paintings were not present because they were on loan.', 2599, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2600, 'The resulting descriptions were placed on the wall in the place of the loaned exhibit.', 2600, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2601, 'The discrepancies in the descriptions made the viewers subjectivity very obvious; descriptions of the same work would vary greatly, placing an object in a painting that was not there for example, adding something new to a painting or changing the composition of the colours.', 2601, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2602, 'Guillaume Bijl', 2602, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2603, 'Belgian artist Bijl is known for his perfect recreations of very ordinary spaces.', 2603, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2604, 'Each installation he creates in a gallery is a recreation down the last detail of a particular place, for example a gym, a supermarket, a beauty salon, another gallery and a bookshop.', 2604, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2605, 'These spaces would be usable for their projected purpose, such is the attention to detail, but their remain functionless and empty, and such is their purpose.', 2605, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2606, 'They are three dimensional facsimiles, all the more unreal for being so real.', 2606, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2607, 'Christian Boltanski', 2607, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2608, 'Boltanski is a German artist who made large scale installation and site specific works and is particularly interested in socio political issues, in the memorial, and in the legacy left for the living by the dead.', 2608, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2609, 'One work was sited in a gap in a terrace of houses, a bombed out house never rebuilt.', 2609, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2610, 'Boltanski discovered the names of the people who had lived in the house and inscribed them on the walls that still retained details of the interior of the house such as fireplaces, wall paper and paint.', 2610, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2611, 'Another work consisted of a larger number of leather suitcases that referred to the luggage left by those killed during the holocaust.', 2611, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2612, 'Sonia Boyce', 2612, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2613, 'British artist working in the 1980s onwards who made work dealing with racial awareness and black identity.', 2613, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2614, 'Ian Breakwell', 2614, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2615, 'A British artist whose career began in the 1970s, Breakwell is best known for his written diaristic work.', 2615, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2616, 'He made a number of pieces with large amounts of densely handwritten text, often detailing his own life and observations about life.', 2616, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2617, 'He also used photographs.', 2617, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2618, 'In the 1980s he made a performance in which the audience was confronted with a stage curtain.', 2618, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2619, 'When it opened they were faced with a painted audience and the back of a proscenium arch, and in fact they themselves were on stage.', 2619, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2620, 'Jan Fabre', 2620, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2621, 'Belgian artist Fabre is very interested in insects and since the 1970s he has been making large scale theatrical performances usually featuring himself and others dressed as insects or in costumes covered with insects.', 2621, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2622, 'Fabre also makes objects and paintings encrusted with insects, particularly beetles, the dark iridescence of their wings and shells fascinates him.', 2622, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2623, 'Ovind Fahlstrom', 2623, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2624, 'Sylvie Fleury', 2624, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2625, 'French artist working from the 1980s onwards.', 2625, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2626, 'Fleury is interested in consumerism and in the relation between fashion and desire.', 2626, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2627, 'One work consisted of shopping bags from different high fashion shops, placed in a casual arrangement on a plinth so that the bags themselves took on a significance beyond their actual existence as carrier of luxury goods, to even transcend this, so clearly did their names, logos, colours and designs advertise a particular way of life, style and aspiration.', 2627, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2628, 'Fleury also made works with shoes.', 2628, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2629, 'Susan Collins', 2629, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2630, 'UK artist who pioneered the use of holograms in art in the early 1980s, Collins later worked with sound digital technology and the internet.', 2630, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2631, 'Ian Hamilton Finlay', 2631, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2632, 'Scottish artist who since the 1970s has made, and continues to make site specific outdoor installations.', 2632, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2633, 'Hamilton Finlay carves text into stone panels and blocks, inscribed in simple classical fonts, single words and phrases that relate to landscape in which they are placed.', 2633, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2634, 'His intention is to integrate words with landscape.', 2634, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2635, 'These installations are sometimes small scale but may also be installed over a large area of land, such as in a park often as a permanent work.', 2635, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2636, 'Hamilton Finlay&apos;s work is probably best known as photographic documentation.', 2636, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2637, 'David Hammons', 2637, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2638, 'Artist whose work investigates cultural and ethnic identity.', 2638, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2639, 'Mona Hatoum', 2639, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2640, 'Hatoum is a British artist born in the 1950s in Lebanon who makes installation and video work.', 2640, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2641, 'Hatoum&#x2019;s work investigates the extremes of human nature and cruelty, alluding to the repressive practises of certain regimes in the Middle East and their effect on the life of women in particular.', 2641, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2642, 'In an early video work the veiled face of a woman has the shadows of Arabic text falling across her face and a certain point a knife is drawn across her eyes as if to cut them open.', 2642, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2643, 'A later installation consists of a long totally dark corridor constructed within a gallery, at the end of which is dimly visible a red glow.', 2643, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2644, 'The curious viewer will walk along the corridor and the glow becomes brighter, revealing itself to be several vertical bars of red light.', 2644, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2645, 'Only at close proximity does it become apparent that the light source is electric heater elements.', 2645, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2646, 'The effect of this on the viewer is to give the sense that they might burn themselves by being lured towards the red hot bars.', 2646, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2647, 'Another installation employing a similar economy of means consists of three banks of wire mesh lockers, arranged to create a &#x2018;room&#x2019;.', 2647, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2648, 'Hanging from the ceiling is an unshaded electric light bulb which slowly descends and rises into and out of the locker space.', 2648, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2649, 'The shadows cast by the wire grid construction of the lockers grow large and shrink in the most sinister fashion.', 2649, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2650, 'In the late 1990s Hatoum moved on from the almost theatrical effects created by these installations to create more video work.', 2650, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2651, 'In a video installation called Deep Throat displayed in a wooden kiosk, Hatoum showed a film made by a medical camera travelling through the various orifices of a woman&#x2019;s body.', 2651, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2652, 'Like all her work the visceral impact of this work leads to secondary reflections on imprisonment and torture.', 2652, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2653, 'Susan Hiller', 2653, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2654, 'British artist born in the 1950s, Hiller makes installations usually with video which is often projected, works on paper and often three dimensional objects and structures.', 2654, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2655, 'She is interested myth, religion, ritual, literature, grand narrative, and psychoanalysis.', 2655, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2656, 'Belshazzar&apos;s Feast made in the late 1980s takes the biblical reference of its title as a starting point for one work.', 2656, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2657, 'A sitting room &#x2018;set&#x2019; with sofas, coffee table, lamps and sideboard contains a television where the fireplace would be.', 2657, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2658, 'On the television is a film of showing a burning fire, as if to illustrate that television is the hearth around which we gather.', 2658, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2659, 'On the wall is automatic writing (a reference to the writing on the wall by the unseen hand that takes place at Belshazzar&#x2019;s Feast) done by Hiller.', 2659, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2660, 'Another work features giant shadow puppets of Punch and Judy and other folkloric characters, made into a film projected to cover all four walls of a gallery space, the silhouetted characters looming and distorted.', 2660, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2661, 'Hiller made a site specific work at the Freud Museum in London (the home of Sigmund Freud) for which she presented a series of cardboard boxes containing text and objects and made photographs of Freud&#x2019;s ethnographic collection.', 2661, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2662, 'Jenny Holzer', 2662, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2663, 'Holzer works in a variety of media using text.', 2663, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2664, 'During the 1980s Holzer made a series of works featuring slightly altered popular sayings that she titled Truisms.', 2664, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2665, 'These were political statements that subverted commonly used truisms to make points about consumerism, subjectivity and art.', 2665, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2666, 'The Truisms featured on T shirts, till receipts in shops, park benches, digital display boards above Times Square and Piccadilly Circus, LED displays in public places, posters and leaflets.', 2666, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2667, 'Holzer employed the various methods of public display and dissemination of information for the presentation of her work.', 2667, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2668, 'Stewart Home', 2668, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2669, 'British artist and writer who has written about punk, art and performance, including writing and photographing performer Cosey Fanni Tutti.', 2669, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2670, 'Home has also made work on paper and installation, such as the Art Bed, an ordinary single bed with a bedspread on which the viewer is invited to recline.', 2670, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2671, 'Rebecca Horn', 2671, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2672, 'Artist born in the 1950s who makes sculptures that are largely concerned with the human body.', 2672, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2673, 'Horn&#x2019;s work is often presented as installations and she sometimes makes kinetic work.', 2673, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2674, 'An example of this is apiece called The Conductor, which is a white non sighted person&#x2019;s stick suspended in space over a metal plate.', 2674, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2675, 'An invisible magnetic field causes the stick to dance spasmodically, making a tapping and scraping sound when it touches the metal plate.', 2675, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2676, 'It seems to be wielded by an invisible person, and appears quite threatening to the viewer.', 2676, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2677, 'A piano hangs from the ceiling, its insides exploding out periodically, catching the viewer unaware as the lid springs open and all the strings sound and the hammers slide out.', 2677, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2678, 'Another work consists of a large number of hoses strewn over a whole exhibition space, all leading to something which is operated by an air bladder.', 2678, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2679, 'The hoses are full of compressed air and the whole operation seems to be random.', 2679, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2680, 'A work which is visually similar to this is a dressmaker&apos;s dummy holding a dress made from transparent tubing which is full of red liquid, which is pumped around the dress as if the tubes were an arterial system.', 2680, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2681, 'Horn has also made a dress, again displayed on a dummy, from large pieces of meat sewn together.', 2681, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2682, 'Much of Horn&#x2019;s work involves the construction of strange garments, such as the gloves with one metre long pointed finger extensions.', 2682, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2683, 'She often makes work which impedes and transforms the function of the body, or places its inner workings on the outside.', 2683, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2684, 'Her work has a fairy tale atmosphere that is quite frightening.', 2684, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2685, 'Ilya and Emilia Kabakov', 2685, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2686, 'The Kabakovs are a Russian artist couple who have made a large number of installations which comment on Russian (both Soviet and post soviet) social order, and on the position of the individual in a totalitarian society.', 2686, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2687, 'The Kabakov&apos;s work is often optimistic, sometimes didactic and engenders a feeling of the possibility of escape in the viewer.', 2687, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2688, 'A work made in the late 1980s consists of a bedroom constructed inside a gallery space, the structural walls entirely freestanding so that the viewer is presented with a wooden box.', 2688, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2689, 'Through the open door the viewer can see into the room which is full of books and comic books and magazines, a bed and some rudimentary furniture.', 2689, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2690, 'A life size realistic dummy of a aircraft pilot who has apparently ejected from a plane has parachuted through the ceiling, bring the ceiling down and spreading rubble over the tiny room.', 2690, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2691, 'The pilot is suspended, his parachute harness caught in the roof.', 2691, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2692, 'The Kabakov&#x2019;s also made a very large scale installation based on Vladimir Tatlin&apos;s tower, a spiral construction.', 2692, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2693, 'This installation consists of the tower, and several interlinked spaces with doors and windows, a kind of maze the whole of which is roughly constructed of unpainted light coloured wood.', 2693, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2694, 'Viewers enter the structure and negotiate the spaces, eventually climbing to the top of the tower on its helter skelter like steps.', 2694, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2695, 'At the top of the tower and in the rooms are various objects, images and texts to contemplate, often placed on school desks.', 2695, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2696, 'There is quite a lot to read.', 2696, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2697, 'Karen Knorr', 2697, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2698, 'British artist born around 1960 whose conceptual text and photographic image work is concerned with the interrogation of the institution.', 2698, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2699, 'Jannis Kounellis', 2699, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2700, 'Greek artist who was very successful in the 1980s with a number of large installations to do with the relation of cultural history to the modern world.', 2700, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2701, 'Kounellis used the image of the horse quite a lot, as well as working in steel construction and using soot or smoke like pigment.', 2701, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2702, 'Barbara Kruger', 2702, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2703, 'Kruger made a seminal body of work feminist and political in the 1980s using photographic collage and text.', 2703, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2704, 'Using skills developed in her paid job in graphic design Kruger began to juxtapose generic images with generic phrases and slogans that she slightly altered to make a political point, appropriating graphic styles from Russian constructivist art and socialist graphics.', 2704, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2705, 'For example, a female hand with long immaculately manicured nails in black and white with the slogan in bold Helvetica black &#x2018;protect me from what I want&#x2019; diagonally across the image.', 2705, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2706, 'A closed eye appropriated from a surrealist photograph is captioned &#x2018;I am your almost nothing&#x2019;.', 2706, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2707, 'One of her most copied slogans is &#x2018;I shop therefore I am&#x2019;.', 2707, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2708, 'Kruger&#x2019;s skill was in the juxtaposition of slogan and image producing a powerful effect.', 2708, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2709, 'She rarely used colour but when she did it was almost always red.', 2709, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2710, 'Her work was produced as postcards and achieved wide dissemination making her one of the best known artists of her generation.', 2710, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2711, 'Lucia Nogueira', 2711, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2712, 'South American artist born in the 1950s and died in the 1990s who made installations from glass beads and blown glass placed on the floor and hanging.', 2712, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2713, 'Cady Noland', 2713, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2714, 'American artist who is known for her scatter works in the 1980s in which she placed objects on the floor of a gallery and for her scaffolding pole constructions.', 2714, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2715, 'Cornelia Parker', 2715, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2716, 'British artist born in the 1950s whose best known work is Cold Dark Matter an Exploded View made in the late 1980s.', 2716, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2717, 'This work consists of the hundreds of fragments of a garden shed and its contents, destroyed by the artist in a controlled explosion.', 2717, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2718, 'The fragments are displayed hung from invisible thread to form a shed shape, as if the shed has been frozen in the act of exploding and the fragments stopped in time.', 2718, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2719, 'For Thirty Pieces of Silver Parker flattened silver ware and other silver plated objects such as a trumpet and suspended the silver on threads to hover just above the floor.', 2719, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2720, 'A similar work used a steam roller to roll over a trail of silver ware.', 2720, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2721, 'Parker&#x2019;s interest in the transformation or destruction and representation of objects continued with a work in which she melted down a gun and recast it as a solider and therefore unusable form, an LP which she reduced to shavings by playing it with a blade instead of a needle, and other works involving dust and shadows.', 2721, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2722, 'Adrian Piper', 2722, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2723, 'British artist who makes work about ethnicity.', 2723, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2724, 'Lawrence Wiener', 2724, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2725, 'American artist born in the 1940s who is an influential conceptual artist working exclusively with text.', 2725, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2726, 'Wiener made a replica of the Rosetta stone that is ten metres across.', 2726, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2727, 'He made a great number of gallery installations that consist of transfer lettering applied to the wall to his specification, presenting a text that he had written, much or all of which is often crossed through.', 2727, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2728, 'He also made typed and printed work on paper and paintings of text.', 2728, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2729, 'Wiener&#x2019;s work was an investigation into the nature of language and specifically into the written word, taking the postmodern debate about language as a system of signs and signifiers and making it the subject of his work.', 2729, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2730, 'In Wiener&#x2019;s work the meaning of the words, the action of reading by the viewer and the visual presence of the words combine to make a work of art.', 2730, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2731, 'Fred Smith', 2731, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2732, 'American artist working from the 1980s onwards who makes socially engaged installation art.', 2732, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2733, 'Smith is interested in ethnicity, cultural identity and institutional representations of different cultures.', 2733, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2734, 'He has often been invited to make installations in museums, for example he has swapped exhibits from ethnographic collections with those from nineteenth century decorative arts collections.', 2734, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2735, 'Kate Smith', 2735, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2736, 'British artist born around 1960 who makes installation and photographic work, which has sometimes featured shoes.', 2736, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2737, 'Smith&#x2019;s work is rooted in her interest in psychoanalytical and feminist theory.', 2737, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2738, 'Rosemarie Trockel', 2738, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2739, 'Artist born in the 1950s who makes knitted paintings, panels made on a knitting machine using jacquard techniques placed on stretches, as well as balaclavas and gloves.', 2739, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2740, 'Trockel uses various motifs such as the hounds tooth from the check pattern, and the playboy bunny, both of which appear incongruous when translated into knitting.', 2740, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2741, 'FILM AND VIDEO', 2741, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2742, 'Cheryl Donegan', 2742, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2743, 'Donegan is an American video artist whose work investigates the sculptural and painterly possibilities of everyday activities.', 2743, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2744, 'In Sunflower, she spins on grass with a bottle of yellow paint attached to her waist, it sprays out and slowly paints a circle.', 2744, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2745, 'In Kiss My Royal Irish Ass she paints her buttocks green and sits on sheets of paper, three times on each to make a clover leaf painting.', 2745, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2746, 'In another work she suggestively and lasciviously drinks milk that is spraying slowly from a hole made in the side of a plastic bottle and when her mouth is full she sprays the milk on the wall.', 2746, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2747, 'In another she holds a French stick between her knees and eats it as far down as she can reach.', 2747, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2748, 'In many ways Donegan&apos;s concerns bear comparison to the work of Sarah Lucas, with her interest in how the banal and the domestic can be both sexually suggestive and formally sculptural and humorous.', 2748, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2749, 'Donegan also makes reference to abstract expressionism and to the ejaculatory possibilities that can be seen in the work of Jackson Pollock, and mocks the machismo inherent in his work with her own abject attempts.', 2749, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2750, 'Jack Goldstein', 2750, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2751, 'American artist born in the 1950s who has made a number of 16 mm films and videos.', 2751, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2752, 'Goldstein&#x2019;s work often has a formal simplicity that belies his choice of medium; he may choose to film something that is barely there or hardly moves.', 2752, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2753, 'He adds animation to the film, for example in a film of a willow pattern plate, which simply shows the plate seen face on in a static shot, one of the birds in the pattern comes to life and flies off the plate.', 2753, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2754, 'In another a figure of a person is outlined in tiny red lights and moves, the lights shining blurrily.', 2754, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2755, 'Chris Marker', 2755, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2756, 'Very influential British underground filmmaker working from the 1970s onwards, whose work is often a collage of images and film clips.', 2756, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2757, 'Marker&#x2019;s films are presented as an installation.', 2757, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2758, 'For example one work is shown on a tower of monitors placed one on top of the other, the same film playing on each but at a different point, so that the images are never the same.', 2758, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2759, 'Tony Oursler', 2759, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2760, 'American artist who became known for his video installations in the early 1990s for which he filmed himself and other people talking.', 2760, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2761, 'He made scarecrow like figures with white pillows for heads, some life size some doll sized.', 2761, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2762, 'The videos are projected on to the pillows, the projector either wall mounted or placed on the floor directly in front of the figure and are very much part of the work.', 2762, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2763, 'The figures then &#x2018;speak&#x2019; to the viewer, usually stream of consciousness babble, often sounding as if they are talking to some kind of therapist or analyst.', 2763, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2764, 'Sometimes they become distressed and scream.', 2764, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2765, 'Although patently unreal, the figures seem very real and the viewer has a poignant attachment to them.', 2765, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2766, 'In one case the projection is onto a heap of clothes as if the person who inhabited them has gone and there is just a soul remaining.', 2766, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2767, 'In another a pillow on a sofa might carry the projection, or one squashed under a toppled chest of drawers, or stuffed into a suitcase.', 2767, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2768, 'The general impression is of tortured souls whispering and babbling in uncomfortable positions.', 2768, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2769, 'Ulrike Rosenbach', 2769, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2770, 'Artist who made video performance work in the 1980s, of which Spinning is an example.', 2770, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2771, 'The viewer sees an wobbling apparently abstract circular image of spinning dots, which are reflective.', 2771, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2772, 'On inspection it can be seen that the image is of a woman (probably the artist) wearing a wide net skirt with large sequins on it, who is spinning in one place, seen from directly above her head with her arms clasped around her torso so that only the skirt and the top of her head are visible.', 2772, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2773, 'The effect is of a spinning glittering disc.', 2773, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2774, 'As the spinning continues the unsteadiness of the image becomes puzzling as well as disorientating for the viewer.', 2774, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2775, 'After ten minutes the woman falls down when she is too dizzy to continue.', 2775, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2776, 'The viewer is also dizzy.', 2776, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2777, 'When the woman is still but the image is still unsteady it becomes clear that the film is not shot from above but from the ground into a mirror placed above her head, and that it is the mirror that is wobbling.', 2777, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2778, 'SCULPTURE', 2778, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2779, 'Richard Artschwager', 2779, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2780, 'American artist who made sculptures of furniture in the late 1970s and early 80s, around the same time as Ettore Sottsass&apos;s Memphis group was making furniture from laminate in Milan.', 2780, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2781, 'He made a table from a box covered in different printed laminates to indicate legs and a pink tablecloth.', 2781, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2782, 'Artschwager also made a series of Chippendale chairs flattened out and laminated in unlikely patterns and designs.', 2782, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2783, 'In these works he was interested in making unlikely combinations of generic form with generic material, forms from the classical era or from antiquity with modern materials.', 2783, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2784, 'Edward Allington', 2784, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2785, 'Allington is a British sculptor who was part of a group of artists who were making large scale ambitious work in the 1980s and early 90s.', 2785, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2786, 'His best known work is Horn of Plenty, a cornucopia of found objects.', 2786, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2787, 'He uses the cornucopia extensively as motif, and was one of the artists invited to propose a work for the empty plinth in Trafalgar square in London in 2001.', 2787, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2788, 'Ashley Bickerton', 2788, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2789, 'American Bickerton was part of the Neo Geo group of artists who worked in New York in the 1980s.', 2789, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2790, 'He made a number of wall mounted sculptures that consisted of closed metal boxes, shallow but projecting some distance from the wall, which he covered with stickers and logos, giving them the appearance of both an item of luggage and a sign, its function entirely ambivalent.', 2790, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2791, 'The stickers themselves were created by Bickerton and were generic types that had no actual reference in the real world to a company, an instruction or an advertisement.', 2791, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2792, 'Bickerton also made a work in which a life size rubber shark was hung from the ceiling with block and tackle.', 2792, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2793, 'Hanging from the ropes were also a number of small yachts fenders along with sealed transparent plastic film bags containing some kind of blue gel.', 2793, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2794, 'Scott Burton', 2794, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2795, 'American artist who made work with furniture.', 2795, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2796, 'Tony Carter', 2796, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2797, 'British artist born around 1950 made a number of installation works in the 1980s based around an existing narrative or historical events and heavily theorised, for which he created highly finished elements often including printed text and drawings.', 2797, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2798, 'One such work contained Carter&apos;s own casts of several silver buttons from an eighteenth century character&#x2019;s jacket.', 2798, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2799, 'Carter gave detailed attention to the display of the elements of his installations, fabricating highly finished display cases and plinths.', 2799, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2800, 'Helen Chadwick', 2800, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2801, 'A British artist born in the late 1950s Chadwick made sculptural installations and photographic work, often combining the two.', 2801, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2802, 'Her work dealt with the female body and ideal beauty.', 2802, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2803, 'One work consisted of light boxes on plinths with photographic images of luxurious and sensual arrangements of hair, ribbon and entrails, and for example length of intestine, braided together.', 2803, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2804, 'Chadwick often associated the visceral with the luxurious and the interior of the body with its clothed exterior.', 2804, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2805, 'She was regarded as a feminist artist and in common with other women artists of her generation produced much work dealing with the female body.', 2805, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2806, 'Another work consisted of a series of wooden boxes of different shape and dimensions, produced to correspond with the size of her own body at various stages in her life so that the box for her birth is new born child sized, another is curved as if a child were curled up, others are standing adult sized.', 2806, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2807, 'The boxes have photographic transfers in black ink of images of Chadwick at these different ages and they stand in a group.', 2807, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2808, 'Around the walls of the space in which the boxes are installed are wooden panels with similar images with Latin texts describing the ages of a woman running around the four edges of the panels.', 2808, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2809, 'The work for which Chadwick is best known is probably Piss Flowers.', 2809, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2810, 'These are painted casts taken from the space made in snow when Chadwick and her male partner urinated in it.', 2810, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2811, 'When cast as a positive this space is revealed to have a central column going down and a petal like circle surrounding it, made by the splashes of hot urine on the snows surface and the main stream melting deep into the snow.', 2811, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2812, 'The male &#x2018;flower&#x2019; has a much wider petal arrangement and a shorter &#x2018;stalk&#x2019;.', 2812, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2813, 'The female &#x2018;flower&#x2019; is the opposite, a result which fired Chadwick&#x2019;s interest.', 2813, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2814, 'The Piss Flowers are a nod to Duchamp&#x2019;s casts of the negative space of male and female genitalia.', 2814, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2815, 'Chadwick died in the 1990s.', 2815, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2816, 'Stephen Cox', 2816, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2817, 'British artist born in the 1950s who made carved stone tondos with classical imagery and inscriptions in the 1980s.', 2817, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2818, 'Dorothy Cross', 2818, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2819, 'Irish artist who makes work from leather and fabric, a kind of feminist surrealism, for example a corset made from leather tanned from a cow&#x2019;s udders with the udders sticking out.', 2819, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2820, 'Grenville Davey', 2820, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2821, 'British artist born around 1960 who made very large cast and lacquered fibreglass sculptures in the 1980s and early 90s.', 2821, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2822, 'Davey created abstract forms that had a functionality about them, like giant lids, plugs or covers, often round, sometimes pairs that seemed that they might fit together.', 2822, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2823, 'These were perfectly constructed, painted in shiny cream, grey, or white and placed on the gallery floor, often on their curved sides.', 2823, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2824, 'Jimmy Durham', 2824, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2825, 'A Native Australian artist who makes junk sculptures, which appear to be fetish objects and often have text applied.', 2825, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2826, 'Durham&#x2019;s work is concerned with the displacement of the Aboriginal people and their culture.', 2826, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2827, 'Brian Falconbridge', 2827, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2828, 'Born around 1950, Falconbridge made very small and detailed finely constructed sculptures, often relying on balance and tension in their construction.', 2828, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2829, 'Jochen Gerz', 2829, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2830, 'Gerz and his partner realised several public sculptures most notably two holocaust memorials.', 2830, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2831, 'The Sinking Monument is a lead covered square column which is gradually sinking into the ground on which it stands so that over a number of years it will eventually fill a hole exactly its size and disappear for ever.', 2831, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2832, 'The soft lead surface invites graffiti, as it is very easy to scratch into and the public are invited in to add to it in a reversal of the customary civic practise of removing any graffiti or making it difficult to carry out.', 2832, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2833, 'Some people engrave the names of those they lost and the monument will take these names underground and they will remain there forever, a subterranean plinth to a memorial plaque on the surface.', 2833, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2834, 'The other memorial is sited in front of the Reichstag in Berlin.', 2834, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2835, 'The Gerzs researched with help from student volunteers into a number of Jewish cemeteries known to have been destroyed and built over.', 2835, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2836, 'Lists of the names of those buried in these places were obtained.', 2836, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2837, 'At night they removed cobblestones from the street in front of the building and carved the name of one of the deceased on the bottom.', 2837, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2838, 'The stones would then be replaced.', 2838, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2839, 'Eventually all of those whose graves had been lost were symbolically reburied in a permanent and subversive act.', 2839, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2840, 'Laura Godfrey Isaacs', 2840, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2841, 'British artist born around 1960 who made wall reliefs that eventually led to polyurethane foam sculptures reminiscent of the work of Lydia Benglis.', 2841, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2842, 'The foam in Godfrey Isaacs&#x2019; sculptures is brightly coloured with forms often jokily alluding to the female body.', 2842, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2843, 'Andy Goldsworthy', 2843, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2844, 'British artist born in the 1950s who makes site specific sculptures placed in the landscape.', 2844, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2845, 'Goldsworthy began in the 1980s to make small sculptures from leaves and twigs, which he would photograph in the landscape.', 2845, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2846, 'Sometimes he arranged leaves, for example grading the different colours of fallen autumn leaves and arranging them in a pattern or floating them on water.', 2846, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2847, 'He also used growing plants, staking the branches of willow trees to form a living structure, weaving twigs into circles.', 2847, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2848, 'He then also used snow to make sculptural forms.', 2848, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2849, 'Goldsworthy&#x2019;s work makes reference to the history of ritual and nature and the resulting artefacts.', 2849, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2850, 'Gradually Goldsworthy&#x2019;s work became larger scale as he travelled widely in search of new landscapes to work with, for example to Alaska.', 2850, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2851, 'Antony Gormley', 2851, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2852, 'British artist born in the 1950s who became very well known in Britain when he made a large scale public commission called The Angel of the North.', 2852, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2853, 'This thirty meter high sculpture is a standing figure with no facial features or detail.', 2853, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2854, 'Its outstretched arms have become aeroplane wings, the arms spanning about forty meters.', 2854, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2855, 'The sculpture, which is made from steel is sited by the motorway and railway line from London to Scotland.', 2855, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2856, 'It can be seen for miles around, and is probably the most visible and best known piece of public art in Britain.', 2856, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2857, 'Gormley made lead casts of parts of his body for a number of years in the 1980s and 90s.', 2857, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2858, 'He then began to cast his whole body and make sculptures from beaten moulded and welded lead sheet.', 2858, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2859, 'The resulting figures are life size and have no detail or features.', 2859, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2860, 'Where the lead sheets meet they are seamed as if they are made of stitched together pieces of fabric.', 2860, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2861, 'Some are prone and some are standing.', 2861, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2862, 'Gormley has conducted a most thorough investigation into the male human form, using a visual anonymity to allow the figures to stand for every person.', 2862, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2863, 'Gormley became known to a much wider public when he made the participatory work Field in the early 1990s.', 2863, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2864, 'Field consists of hundreds of forty cm high clay figures, roughly alike, placed shoulder to shoulder in a mass on the floor of the gallery.', 2864, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2865, 'Field was partly inspired by the terracotta army of seventh century Chinese sculptures found in a burial ground.', 2865, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2866, 'Wherever field is exhibited it is created anew by local people, each person making their own figure from local clay.', 2866, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2867, 'Dan Graham', 2867, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2868, 'American artist working in from the 1970s onwards, Graham makes architectural sculptures, usually site specific, from glass and mirrors, simple structures that invite the viewer to enter them.', 2868, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2869, 'The reflections or the surrounding landscape and of the structure itself cause a sense of disorientation, in particular in terms of which parts of the sculpture are transparent and which are reflective so that there is a confusion about what is a real image and the nature of that reality.', 2869, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2870, 'The structures are extremely simple and formal, usually human height, often no more that a series of vertical planes placed together at angles and ramps.', 2870, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2871, 'They are usually placed in the open air as the light of the sky plays an important role in the reflectivity that is part of the work.', 2871, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2872, 'Thomas Grunefeld', 2872, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2873, 'German artist born in the 1950s known for his stuffed animal sculptures in which different parts of animals are combined to form one hybrid creature that could never exist.', 2873, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2874, 'Grunefeld uses highly skilled taxidermists to renders these creatures objectively completely convincing as if they were the result of some kind of perverse genetic engineering project.', 2874, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2875, 'The animals, for example a roster&#x2019;s feet on a furry mammals body with the tail of a lizard, could have no imaginable purpose, thus they seem like contemporary fantastic beasts.', 2875, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2876, 'Shirazeh Houshiary', 2876, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2877, 'British artist who makes sculptures, often of metal, with references to Islamic architecture.', 2877, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2878, 'The surfaces of the sculptures are often etched with Arabic text and Islamic patterning.', 2878, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2879, 'Bethan Huwys', 2879, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2880, 'Welsh artist who makes very small scale sculptures from natural materials.', 2880, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2881, 'Neil Jeffries', 2881, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2882, 'British artist who has made folded and painted sheet metal sculptures of people and vehicles from the 1980s onwards which have a toy like, mad inventor quality.', 2882, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2883, 'Anish Kapoor', 2883, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2884, 'A British artist who began in the late 1970s to make works using pigment, Kapoor was first known for his varying shaped piles of very bright and densely coloured pure pigment arranged on the floor of the gallery.', 2884, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2885, 'Kapoor then began to make spherical and other shaped structures that he placed on the floor and attached to the wall, the interior of which were coated with pigment.', 2885, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2886, 'The intense matt quality of the dry powder sucked in light creating oddly disorientating effects and tricks of the eye, something like the effects created by the light works of James Turrell.', 2886, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2887, 'He also made some work in which large boulders of rock were drilled with cavities filled with pigment.', 2887, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2888, 'Kapoor made an extremely large installation for a London museum which consisted of a 50 metre high 200 metre long trumpet like structure that tapered into a tube running the length of the museums entrance hall and curved into a second funnel.', 2888, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2889, 'The work was made with a steel frame attached to which is a dark red rubber skin stretched to a smooth tautness.', 2889, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2890, 'Jeff Koons', 2890, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2891, 'American artist, formerly a banker, born in the late 1950s who became known in the 1980s for his photographic works based on advertisements.', 2891, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2892, 'Koons invented magazine advertisements based on existing ones and had them professionally photographed featuring himself as the model.', 2892, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2893, 'He then placed these ads in art magazines in effect advertising himself, a strategy was intended to show that an artist and a career could be invented and promoted.', 2893, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2894, 'Having achieved this Koons began to make sculptural works.', 2894, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2895, 'He first made a marble bust of himself, which he had carved by the best stone carver he could find in white marble with a slight sparkle to it.', 2895, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2896, 'Koons was one of number of new York artists making work that became known as Neo Geo.', 2896, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2897, 'His first works were objects in glass cases, for example a baseball, apparently suspended in mid air inside a vitrine on a plinth, and a number of pristine vacuum cleaners in a large case (a pun on the idea of the airless vacuum).', 2897, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2898, 'Koons then began to design sculptures based on trinkets and souvenirs enlarged to many times their original size and presented on plinths, works which called attention to the status of the work of art, its value, the skill of its making and its authorship, because Koons rarely made anything himself.', 2898, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2899, 'Instead he ordered his works to be made to his detailed plans by the best crafts people he could find in the medium that interested him.', 2899, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2900, 'The first was a serried of porcelain sculptures for example one of Michael Jackson reclining with a poodle, some large flowers taken from a children&#x2019;s model set, and one of an enlarged children&#x2019;s Cabbage Patch doll.', 2900, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2901, 'The sculptures were made by the best porcelain artists (in eastern Europe), hand painted, gilded and extremely kitsch but very striking due to their size (about one metre high usually).', 2901, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2902, 'Koons was interested in how an object of little value other than sentimental value which may however have cost the owner quite a lot (the nature of souvenirs) might be transformed into an art object of immense value despite its bad taste, lack of traditional fine art values and lack of the artists hand in its making.', 2902, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2903, 'Koons made several groups of works in a similar way, for example cast metal which was highly chromed (a train set which is a decanter glasses and coaster holder, a balloon rabbit), and polychromed wood vases of flowers, extremely detailed pieces of virtuoso carving made in Germany by master carvers.', 2903, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2904, 'He later made a number of extremely large site specific works, the flower sculptures, for which he again borrowed the talents of others.', 2904, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2905, 'The first of these was a twenty metre high Scottie dog covered with flowers the colours of which in some way functioned like the dots on a billboard poster.', 2905, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2906, 'In the mid 1990s Koons married la Cicciolina an Italian porn actress and made a series of photographic works which were styled as stills from a porn film, using professional stylists and photographers once again.', 2906, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2907, 'The images had a degree of shock value since some featured clearly visible penetration.', 2907, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2908, 'Koons and Cicciolina stared out at the viewer.', 2908, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2909, 'The images were odd hybrids of pornography and portrait.', 2909, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2910, 'After a much publicised divorce from la Cicciolina Koons began in the late 1990s to make two or three metre high paintings of enlarged parts of things, such as balloons, mixtures of toys, household objects and natural things, so enlarged and partially visible as to be hard to interpret.', 2910, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2911, 'These are painted by his studio assistants to Koons&#x2019;s designs.', 2911, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2912, 'Richard Long', 2912, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2913, 'British artist born in the 1950s, Long is a land artist and as such his site specific work exists mostly as documentation.', 2913, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2914, 'Long began by making walks and documenting them with photographs.', 2914, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2915, 'He would then mount these photographs relate them to sections of large scale survey maps showing the walk and the north south orientation, and print below them the distance walked as proportion of the total distance of the walk.', 2915, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2916, 'In doing so he was developing ideas put into practice by American land artist Dennis Oppenheim in the 1960s and 70s, and anther artist who walked along coastlines, the walk, he declared, making a drawing of a line, the line being the demarcation between land and water.', 2916, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2917, 'This idea of &#x2018;taking a line for a walk&#x2019; has been explored by several artists.', 2917, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2918, 'Long&apos;s walks were made all over Britain and then in other countries, they were mostly quite short.', 2918, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2919, 'In Longs work the land itself, the ground on which we tread and the landscape it forms, is the subject as is artist&apos;s subjectivity in terms of choice of and experience of the walk.', 2919, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2920, 'Long developed his interest in the ground underfoot into an interest in the materials this comprised of and brought clay, earth and stone into the gallery in various forms.', 2920, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2921, 'He made a number of temporary wall paintings made of mud and clay, thrown at the wall or splashed on with handprints, the mess and drips on the surrounding floor and wall allowed to remain.', 2921, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2922, 'Long made a circle of white clay splashes on a dark painted wall, or a horizontal band of dark mud on a white wall.', 2922, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2923, 'He also made rock floor sculptures, which make reference to the work of Carl Andre and Robert Smithson.', 2923, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2924, 'A piece of the rock from a particular landscape was cut into slices and then fragmented into enormous jagged shards laid out to fill a solid circle or band on the floor, in a sculptural reference to rock strata and man made intervention.', 2924, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2925, 'David Mach', 2925, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2926, 'British artist born in the 1950s, Mach became known when he made large sculptures from meticulously stacked magazines.', 2926, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2927, 'These monumental scale sculptures developed and Mach began to use other materials, for example a submarine made from scrapped car tyres, a train made from stacked bricks.', 2927, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2928, 'Constructed with no fixings, the sculptures have a casual appearance that belies the complexity of their construction, needed to prevent them from collapsing.', 2928, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2929, 'The sculptures gain their intrinsic strength from the way the stacks are formed and interlinked, but they remain potentially un fixed and are impermanent despite their bulk and weight.', 2929, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2930, 'Mario Merz', 2930, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2931, 'Italian painter born in 1940s who made sculptures and wall based works which incorporated some illuminated neon tubing.', 2931, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2932, 'For example and igloo like structure with neon on floor.', 2932, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2933, 'Paintings with neon arrows.', 2933, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2934, 'Carl Plackman', 2934, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2935, 'British sculptor who made assemblages with natural materials and steel, particularly favouring pebbles.', 2935, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2936, 'Sabin, Andrew', 2936, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2937, 'British sculptor who made work with coloured hanging chains.', 2937, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2938, 'Kiki Smith', 2938, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2939, 'American artist born in the 1940s who makes sculpture characterised by her use of ephemeral and delicate materials like paper, fabric, and beads.', 2939, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2940, 'Smith often makes life size human figures, animals and birds from paper; sometimes the figures are wearing paper clothes.', 2940, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2941, 'Her work describes the condition of femininity and of childhood.', 2941, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2942, 'A naked female figure lies on her side on the ground, strings of glass beads issuing from between her legs as if toe represent blood.', 2942, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2943, 'A peacock&#x2019;s tail on the wall has the detail drawn on in pen.', 2943, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2944, 'like all of Smiths work these are made from white paper stuck together and varnished, so that the final appearance is of a translucent yellowed skin, three dimensional forms which are hollow skins, fragile and ephemeral.', 2944, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2945, 'Haim Steinbach', 2945, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2946, 'American artist born in the 1950s who became well known in the 1980s for his work including small sculptures on shelves, using cast metal, plastic and laminate.', 2946, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2947, 'Richard Wentworth', 2947, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2948, 'British artist born in the 1950s who makes sculpture and photographic work.', 2948, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2949, 'Wentworth observes the everyday life of and use objects and makes sculptures that observe the way in which one thing can be used for another using aluminium buckets, tools, ladders and rope.', 2949, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2950, 'One work made in the 1980s is called Sinking of the Belgrano and consists of a model battleship in an aluminium bucket on a false surface.', 2950, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2951, 'Another is a book with a large number of sweet wrappers inserted between the pages in an exaggeration of the potential use of one as a bookmark.', 2951, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2952, 'For twenty years Wentworth has been photographing the area around Caledonian Road in London where he lives every day.', 2952, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2953, 'He has a particular interest in the interaction of handcraft, artisanship and making do with the built environment.', 2953, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2954, 'His collection includes documentation of changing shop fronts and names, appropriate, unusual or inappropriate uses for street furniture, railings and doorways, graffiti, litter and makeshift solutions to broken objects and parts of buildings.', 2954, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2955, 'Wentworth has also made a large collection of photographs of the way one object is used for a new purpose, for example a saucer wedged in to keep a window open.', 2955, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2956, 'Alison Wilding', 2956, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2957, 'British artist who makes sculptures from transparent acrylic sheet, slotted together to form complex three dimensional grid structures that take advantage of the way that the edge of the acrylic can be seen as lines in space.', 2957, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2958, 'Wilding&#x2019;s sculptures are solid forms that give the impression of being light and delicate.', 2958, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2959, 'She also makes working drawings which are in effect technical perspective drawings for the sculptures.', 2959, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2960, 'Hermione Wilshire', 2960, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2961, 'British artist born in the 1950s who makes installations and sculpture.', 2961, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2962, 'Wilshire has often worked with glass.', 2962, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2963, 'She blows large globules and droplets of glass and places them over photographs of parts of the human body which are then viewed through the glass, magnified and glowing.', 2963, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2964, 'One work consisted of glass droplets extruded into stalks which were fixed projecting form the wall, on the bottom of which were fixed photographs of finger prints, as if these had been left in the air.', 2964, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2965, 'Another consisted of a large number of variable sized glass pebbles on the underneath of which were attached photographs of penises, arranged on the floor as if they had been scattered in a allusion to ejaculation.', 2965, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2966, 'Bill Woodrow', 2966, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2967, 'British artist born in the 1950s who made installations from collections of waste plastic bottles and containers, arranged by colour and shape on the wall or floor to create an image.', 2967, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2968, 'Woodrow also made a series of works using discarded refrigerators, washing machines.', 2968, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2969, 'He cut the form of an object for example a guitar from the metal walls of a washing machine and by bending and folding the metal coaxed it into a convincing representation which remains attached to the washing machine.', 2969, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2970, 'He also fashioned a broken umbrella into a crow.', 2970, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2971, 'PAINTING', 2971, 2, '1.3', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2972, 'Craigie Aitchison', 2972, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2973, 'Aitchison is a Scottish painter best known for his 1980s paintings of his pet Bedlington terrier.', 2973, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2974, 'The dogs are painted in profile on large brightly and flatly coloured canvases.', 2974, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2975, 'Michael Andrews', 2975, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2976, 'British painter.', 2976, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2977, 'Basil Beattie', 2977, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2978, 'A figurative painter of the Glasgow school born in the late 1930s Beattie painted fishing boats, ship builders and chip shops lyrically and colourfully.', 2978, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2979, 'Ida Applebroog', 2979, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2980, 'Applebroog&apos;s paintings and free standing works from the late 1980s and early 90s are concerned with memory, childhood and narrative.', 2980, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2981, 'She often uses the predella form, and uses an image of a film negative as a framing device.', 2981, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2982, 'The paintings are often constructed from several canvases butted together and freestanding works are propped on the floor upright or placed horizontally.', 2982, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2983, 'Applebroog made a film with her daughter, film maker and artist Beth B, which is a loose narrative of unhappy childhood with a dreamlike quality.', 2983, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2984, 'Art and Language', 2984, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2985, 'British artist duo born around 1950 known for their conceptual work text paintings.', 2985, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2986, 'John Baldessari', 2986, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2987, 'American artist working in the 1970s and 80s who made photo collages typically consisting of black and white photographed images with bold graphic lines and forms added in colour.', 2987, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2988, 'Jean Michel Basquiat', 2988, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2989, 'Graffiti artist from the Bronx in New York, Basquiat was born in 1973 and died in 1998.', 2989, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2990, 'He was discovered by a dealer who fostered him and provided him with studio and materials, enabling Basquiat to paint on canvas.', 2990, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2991, 'He became hugely successful, his work commanded high prices and he was feted by the art world for his work, his looks and his rebelliousness.', 2991, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2992, 'Basquiat used graffiti tags combined with idiosyncratic signs and symbols creating a way of making a painting that successfully combined street and Afro Caribbean consciousness with abstraction.', 2992, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2993, 'The outline of a crown, a reference to his own self determined kingship, was his signature, the skull often appeared.', 2993, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2994, 'He mostly painted in black and bright colours on white ground, drawing in outline and rarely filling in, sometimes used white on black to give a blackboard effect.', 2994, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2995, 'The apparent na&#xef;ve style used to issue a series of commands and demands on the world and his viewers, which are both egotistical and irresistible.', 2995, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2996, 'Unable to cope with his success he became addicted to heroin and died of overdose before he was thirty.', 2996, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2997, 'Andy Warhol befriended Basquiat towards the end of his life and they made large collaborative paintings together.', 2997, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2998, 'Basquiat was later mythologised in a feature film of his life made by artist turned director Julian Schnabel.', 2998, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (2999, 'Glen Baxter', 2999, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3000, 'A British artist born in the late 1940s whose cartoon drawings accompanied by text depict events, happenings and people that illustrate a typical Englishness with self deprecating humour, and surreal, slapstick narrative.', 3000, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3001, 'These cartoons were used by advertisers in the 1990s and Baxter&#x2019;s work became extremely widely known.', 3001, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3002, 'Ross Bleckner', 3002, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3003, 'Bleckner was one of a number of painters in working in New York in the 1980s and early 90s who were making monumental scale works.', 3003, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3004, 'He had a solo exhibition at the Guggenheim in 1992 in which he showed a number of abstract works that looked like starry pieced domes, wavy stripes with ribbon rosettes dotted among them and fuzzy chandelier and flower like compositions.', 3004, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3005, 'Bleckner&apos;s work is sometimes interpreted as having a memorial quality.', 3005, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3006, 'Eric Bulatov', 3006, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3007, 'Russian artist working in the 1980s and 90s who combined socialist realist imagery, blue skies, and fields with large text painted across the image.', 3007, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3008, 'Simon Callery', 3008, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3009, 'British artist born around 1960 who made a series of white paintings of banal urban landscapes in the early 1990s.', 3009, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3010, 'These relied on impasto and tiny amounts of colour in the white to create an almost intangible image.', 3010, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3011, 'Vija Celmins', 3011, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3012, 'Artist born in the 1940s who has made a large number of paintings and drawings of the sky and the ground.', 3012, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3013, 'Celmins paints on small landscape format canvases about sixty cm wide or slightly more, using very small brushes or makes drawings of a similar size using pencil.', 3013, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3014, 'In either case she will draw the most minimal view &#x2013; a patch of dust on the ground with a few tiny chips of gravel becoming as important as if it were the surface of the moon.', 3014, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3015, 'She has also drawn the surface of the moon.', 3015, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3016, 'A tiny part of the night sky becomes a deep blue painting of tiny diamonds.', 3016, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3017, 'Celmins work brings the minute and the gigantic together but the works have a deceptively modest unassuming appearance.', 3017, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3018, 'Francesco Clemente', 3018, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3019, 'Italian American painter born in the late 1940s who was extremely successful in the 1980s.', 3019, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3020, 'Clemente makes figurative painting and works on paper, as well as small scale sculpture and ceramics.', 3020, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3021, 'His work shows his interest in Indian art, in its colours and in its often spiritual themes.', 3021, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3022, 'Beryl Cook', 3022, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3023, 'British artist born in the 1940s, usually termed &#x2018;na&#xef;ve&#x2019;.', 3023, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3024, 'Cook paints ordinary women, often rather large both in size and in personality, going about their daily life.', 3024, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3025, 'Her paintings are humorous and have a strong narrative and simple appeal.', 3025, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3026, 'Cook is extremely well known in Britain.', 3026, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3027, 'Enzo Cucchi', 3027, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3028, 'Italian artist who made large scale drawings of classical nudes using an obsessive cross hatched style for which he became very well known in the 1980s.', 3028, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3029, 'Rita Donagh', 3029, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3030, 'British artist who makes geometric drawings.', 3030, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3031, 'Paul Eachus', 3031, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3032, 'British painter.', 3032, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3033, 'Gerard Hemsworth', 3033, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3034, 'British painter born in the 1940s who has taken generic graphic forms and visual jokes as his subject matter.', 3034, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3035, 'Hemsworth&apos;s paintings are made with entirely flat smooth colour and hard edged lines.', 3035, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3036, 'Typically he will choose one or several diagrammatic representations, such as a cloud, a rabbit or a vase for example, simplify this to the minimum number of lines required and paint it on a pale coloured ground in black.', 3036, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3037, 'Marlene Dumas', 3037, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3038, 'Dutch painter who makes large figurative works on paper using water colour that usually depict women.', 3038, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3039, 'Carroll Dunham', 3039, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3040, 'Abstract paintings made from the 1970s to the 2000s, brightly coloured but using a lot of white and the forms outlined in black, featuring blob and disc shapes, painted thickly, like lumps or pompoms.', 3040, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3041, 'Nicole Eisenman', 3041, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3042, 'American artist who was one of the so called &#x2018;bad girls&#x2019;, women artists working in the 1990s in New York, using pornographic or otherwise potentially offensive imagery in their work.', 3042, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3043, 'Eisenman made wall sized paintings depicting pseudo classical scenes.', 3043, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3044, 'Rainer Fetting', 3044, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3045, 'German painter born in the 1950s who made large figurative paintings, for example one of a row of men in the shower, painted in blues and whites, in an expressionistic style.', 3045, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3046, 'Gunther Forg', 3046, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3047, 'German artist born in the 1950s who makes paintings, photographs and bronze sculpture.', 3047, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3048, 'Forg typically places a two meter high black and white photograph in a frame butted up against an abstract painting of a similar size, consisting of very broad straight single brushstrokes and rectangular areas of colour in for examples orangey red and green.', 3048, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3049, 'His photographs are very often of women (head and shoulders) who look serious.', 3049, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3050, 'Forg&#x2019;s bronze sculptures are the same size as the paintings and photographs, in fact they could be described as sculptures of paintings.', 3050, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3051, 'The bronzes are about thirty cm deep and two metres high rectangular panels standing, in portrait format, on bases which slope straight down from, and are one piece with the panels.', 3051, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3052, 'The surface of the bronze is covered with impasto marks presumably made in clay with a palette knife, as if to indicate that this might be a cast of a painting.', 3052, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3053, 'These monolithic objects are placed around the gallery space in relation to the works on the wall.', 3053, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3054, 'Rebecca Fortnum', 3054, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3055, 'British artist born in the 1960s whose abstract paintings made in the 1980s and 90s have been described as feminist abstraction.', 3055, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3056, 'Fortnum often painted a cut or slit as a metaphor for the female body, the interior, a metaphor employed by many women artists in the 1980s and early 90s.', 3056, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3057, 'This arose from readings of Lacan, a French psychoanalyst whose ideas about &#x2018;lack&#x2019; in the female psyche and about language and femininity were taken up by feminist artists and theorists.', 3057, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3058, 'Fortnum was also interested in a general discussion about the female body as a &#x2018;text&#x2019; (in the sense of the term used in literary theory) and the &#x2018;writing out&#x2019; or performing of that text being essential to the representation of femininity.', 3058, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3059, 'Fortnum&#x2019;s paintings were intended to symbolise this lack, and the writing out of the female, by the painted slit or cut, (never an actual cut) and by text she wrote on the canvas, sometimes unreadable writing like marks, sometimes actual words.', 3059, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3060, 'Fortnum&#x2019;s paintings are very large, up to three metres high, and she predominantly used dark reds and browns, fairly flat colours except where she chose to paint the slit, which is made with very thick paint squeezed and brushed.', 3060, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3061, 'Writing is done with a small brush in a flowing hand, usually a single line of text running horizontally across the painting.', 3061, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3062, 'Gillian Ayres', 3062, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3063, 'British artist who made brightly coloured, abstract impasto paintings throughout the 60s to the 90s.', 3063, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3064, 'Pamela Golden', 3064, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3065, 'British painter.', 3065, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3066, 'Maggi Hambling', 3066, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3067, 'British artist who began painting portraits in the 1960s.', 3067, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3068, 'Keith Haring', 3068, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3069, 'American artist, now dead, who began as a graffiti artist in the early 1980s in New York.', 3069, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3070, 'Haring developed a distinctive graphic style, using bold lines to outline his figures, animals and symbols, and filling them in with plain flat colour.', 3070, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3071, 'Once he became known, Haring began to make his work on canvas and made a lot of printed works, books and ultimately merchandise.', 3071, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3072, 'Today Haring&#x2019;s simple lexicon of symbols and figures is instantly recognisable.', 3072, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3073, 'He always outlined them in black and filled the background in with small marks, painting hearts, hands, animals and figures which rarely have features.', 3073, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3074, 'One of his best known images is of a red heart on a yellow background, the heart surrounded by lines as if to indicate that it is beating.', 3074, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3075, 'Haring most often used the primary colours yellow and red, and black.', 3075, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3076, 'Haring made a lot of political posters about AIDS, and his graphic style was particularly suited to campaigning on various issues.', 3076, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3077, 'Tim Head', 3077, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3078, 'Since the late 1970s Head has made work in a variety of media.', 3078, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3079, 'He has often focused on generic and graphic imagery which he has abstracted and reconstructed in various ways, both as sculptural form, painting and works on paper.', 3079, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3080, 'In the 2000s Head began to work with digital animations, using the pixels that usually constitute the image of video and manipulating their colours to create abstract colour fields of constantly changing coloured squares.', 3080, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3081, 'These are projected very large, and make immediate visual connection with pointillism and with the dot matrix printing process familiarised by advertising hoardings.', 3081, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3082, 'Head has created a moving abstract work from pixels, literally the stuff that images are now made from.', 3082, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3083, 'Peter Howson', 3083, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3084, 'British artist who makes paintings and drawings, travelling to several war zones as a war artist.', 3084, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3085, 'John Hoyland', 3085, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3086, 'British painter who makes figurative paintings.', 3086, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3087, 'Jorg Immendorff', 3087, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3088, 'German artist Immendorff achieved success in the 1980s with his expressionist twentieth century history paintings often featuring the eagle of the third Reich, nightclub and caf&#xe9; scenes and musicians.', 3088, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3089, 'Immendorff&apos;s earlier work had been performative: he invented a concept called Lidl, which consisted of an imaginary town and trailed a brick with the world Lidl on it in and out of shops.', 3089, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3090, 'Immendorff was arrested by the police a few times for his performance activities.', 3090, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3091, 'Callum Innes', 3091, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3092, 'Innes is best known for his work white on white abstract paintings made in the early 1990s.', 3092, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3093, 'Bert Irvin', 3093, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3094, 'British painter born in the 1930s who made large abstract paintings usually by pouring very brightly coloured paint onto a white ground, sometimes only a few stripes of red yellow, green and blue paint across the bottom corners of a canvas.', 3094, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3095, 'Vanessa Jackson', 3095, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3096, 'British artist born around 1950 who makes abstract paintings.', 3096, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3097, 'Ben Johnson', 3097, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3098, 'British photo realist painter born in the late 1950s.', 3098, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3099, 'Joy Clair', 3099, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3100, 'British painter born in around 1960 who painted skies with clouds in the 1980s and later made pattern paintings.', 3100, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3101, 'Alex Katz', 3101, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3102, 'American painter who has made large figurative paintings since the early 1970s on the subject of landscape and his family.', 3102, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3103, 'Katz paints with flat acrylic paint, making each work in a day applying the paint simply and with no texture.', 3103, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3104, 'Katz painted a row of autumnal trees, trees in blossom, his wife (repeatedly), his children and groups of friends, all shown in casual poses.', 3104, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3105, 'The photographic source of Katz&apos;s work is deliberately evident because he is interested in highlighting that conjunction of distance and intimacy.', 3105, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3106, 'John Keene', 3106, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3107, 'British painter chosen to record the Gulf War for Britain.', 3107, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3108, 'Keene later travelled to Afghanistan to record the war there, having become very interested in the depiction of armed conflict.', 3108, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3109, 'Bhupen Khakur', 3109, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3110, 'Artist born around 1930 who is one of the few Indian contemporary painters to become well known outside of India.', 3110, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3111, 'Khakur&#x2019;s figurative paintings depicted his life, often intimately, and included sexual acts with male partners.', 3111, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3112, 'Khakur showed India in a contemporary way unhampered by the history of Indian art but at the same time he made this a part of his work, which shows in particular the influence of Indian miniatures.', 3112, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3113, 'Khakur died 2003.', 3113, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3114, 'Anselm Kiefer', 3114, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3115, 'Keifer is a German expressionist painter who has made paintings and sculpture, both on a large scale, tending towards the monumental from the 1970s onwards.', 3115, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3116, 'He is often considered to be one of the most important painters of the 1980s because he evolved a contemporary purpose for expressionistic painting and because of the operatic scale of his work.', 3116, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3117, 'Keifer&#x2019;s paintings generally depict bare depopulated interiors, for example one that shows an attic like space, which is entirely composed of painted wooden planks.', 3117, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3118, 'He used a restrained palette of earth colours, black and white with dark reds and blues, and his work often has a atmosphere of darkness and foreboding.', 3118, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3119, 'Keifer&#x2019;s sculpture is often presented as an installation, for example a row of hospital beds, the sheets actually made of lead sheet, draped over the beds, in the centre of which are shallow depressions some of which are filled with water, as if to denote the transformation or passing of the occupant of the bed.', 3119, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3120, 'Martin Kippenberger', 3120, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3121, 'One of the greatest German postmodern painters, born in the 1950s Kippenberger was extremely prolific, producing large and small paintings and objects, usually abstract with collaged elements.', 3121, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3122, 'He often added stickers and found labels to his paintings.', 3122, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3123, 'Kippenberger made a series of drawings on hotel notepaper every time he stayed anywhere.', 3123, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3124, 'He designed all his own invitation cards and other publicity, seeing these as part of his artistic output.', 3124, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3125, 'Linda Kitson', 3125, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3126, 'British painter and war artist.', 3126, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3127, 'Leapman David', 3127, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3128, 'British artist who began working in the mid 1980s making paintings which used repeating motifs on a plain ground, the lines themselves removed from the surface of the canvas revealing under the plain flat colour very bright multicoloured painting.', 3128, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3129, 'He later began to use fluorescent colours.', 3129, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3130, 'Rosa Lee', 3130, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3131, 'One of generation of British women artists born in the early 1960s who developed a self defined &#x2018;feminist abstraction&#x2019; that owed much to Brigit Riley.', 3131, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3132, 'Their work defined itself by its relation to the 1980s and 90s feminist critique of abstract painting, in particular the claiming of the painting as the body, and painting as being an act of &#x2018;writing the body&#x2019;.', 3132, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3133, 'Lee&#x2019;s work employed repeated decorative elements such as bows and ribbons on a brushstroke ground.', 3133, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3134, 'Sherrie Levine', 3134, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3135, 'American conceptual artist who became extremely successful in the 1980s and influenced a generation of younger artists with her postmodern appropriation works.', 3135, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3136, 'Levine&#x2019;s primary interest is in the status of the work of art and of the reproduction.', 3136, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3137, 'In this interest makes evident her interest in the work of Marcel Duchamp.', 3137, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3138, 'Levine made a number of chequer board works painted on wood, a number of paintings in which she simply reproduced a cartoon character in outline (such as Charlie Brown), a number of black and white photographs by famous photographers, and of a marble torso sculpture which she signed, declaring the work to be then authenticated by her and therefore made by her.', 3138, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3139, 'She made some works using wooden ply in which she utilised the oval insert of ply that fills the hole where there was a knot, as part of the image.', 3139, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3140, 'Some works using gold leaf dealt with another interest of hers in the perceived versus the intrinsic value of a work of art.', 3140, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3141, 'Levine&#x2019;s work is almost exclusively small, no bigger than eighty cm high.', 3141, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3142, 'Levine&#x2019;s work essentially borrows the work of other artists, which she either remade (as she did in a number of drawings and watercolours after certain artists, which are then signed and authenticated as by her), or transferred from one art form to the status of work of art.', 3142, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3143, 'Through appropriation Levine made fakery, plagiarism and false authentication into the subject of her work.', 3143, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3144, 'Simon Linke', 3144, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3145, 'British artist born around 1960 who became known in the late 1980s for his post modern conceptual painting.', 3145, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3146, 'Linke reproduced advertisements from art magazines on small canvases about sixty cm high, painting the text very accurately but using thick impasto.', 3146, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3147, 'He chose to reproduce mostly advertisements printed in black and white, the paintings appearing from a distance to be exactly what they represent.', 3147, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3148, 'The texture and application of the paint is what makes them paintings, reducing painting to its fundamentals.', 3148, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3149, 'These works became iconographic, and were seen to represent a particular moment in conceptual art when artists engaged with issues of reproduction, the condition of reality and the status of the subject.', 3149, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3150, 'Following this work in the late 1990s Linke began to work with text for its own sake, making the paintings in the same way but not reproducing anything.', 3150, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3151, 'Nicholas May', 3151, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3152, 'A British painter born 1962, May made a series of large paintings by pouring large pools of house paint, while the canvas was on the floor, and tipping them to manoeuvre the paint and allowing them to dry.', 3152, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3153, 'He often used different colours together, pouring one into the other, wet on wet, including metallic colours and powders, the resulting slick of paint forming the painting.', 3153, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3154, 'May made a number of these during the 1990s, after which he ceased to make art.', 3154, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3155, 'Len McComb', 3155, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3156, 'British artist born around 1940.', 3156, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3157, 'Len McComb mainly makes large scale pencil drawings, for example a sequence of cliff faces on the Anglesey coastline drawn on a number of pieces of paper tiled together to make a wall sized drawing.', 3157, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3158, 'Humphrey Ocean', 3158, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3159, 'British artist who makes semi abstract paintings.', 3159, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3160, 'Therese Oulton', 3160, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3161, 'British artist who became known in the 1980s for her thickly encrusted dark coloured semi abstract paintings.', 3161, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3162, 'Sydney Nolan', 3162, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3163, 'Australian twentieth century painter who is well known for painting the outlaw Ned Kelly, who he represented with a black square for a head.', 3163, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3164, 'Richard Prince', 3164, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3165, 'Prince is an American artist who took developed the legacy of pop art, from the 1970s onwards to make a variety of types of work.', 3165, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3166, 'He is most usually associated with two particular works: the Marlboro add and the joke paintings.', 3166, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3167, 'These illustrate Prince&#x2019;s prime interest in generic forms.', 3167, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3168, 'The Marlboro work is a reproduced advertisement for Marlboro cigarettes with the cowboy on the horse removed so that remains is still instantly recognisable because of the brand name, and the type of landscape.', 3168, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3169, 'It is a while before the viewer realises that the cowboy is not there, since the image is so familiar and this is what they expect to see, revealing clearly how embedded in visual memory the advertisement is.', 3169, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3170, 'Prince has made joke paintings throughout his career, very simple text paintings telling a joke on a plain coloured canvas in a san serif typeface.', 3170, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3171, 'The colours, typefaces and size of painting varies up to four metres high.', 3171, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3172, 'The jokes are mostly quite funny.', 3172, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3173, 'Prince has also made a large number of paintings using photographic screen printing mixed with painting, and abstract pattern paintings.', 3173, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3174, 'His prolific output is distinguished by its variety, but also by consistency within that variety.', 3174, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3175, 'Arnulf Rainer', 3175, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3176, 'German painter ! Paula Rego.', 3176, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3177, 'British artist who since the 1980s has made semi autobiographical narrative figurative paintings.', 3177, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3178, 'Rego has a direct style of drawing, and paints loosely but boldly using a generally subdued palette.', 3178, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3179, 'She often adapts scenes from her own childhood to represent collective rites of passage, or taboo subjects such as incest.', 3179, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3180, 'Little girls feature in many of her paintings, often with a man wearing military dress, a father figure.', 3180, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3181, 'Rego is interested in the psychology of her chosen subjects as well as representing an era.', 3181, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3182, 'Gerhard Richter', 3182, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3183, 'One of the most important twentieth century German artists, Richter made paintings in a variety of style and on a range of subjects but is best known for his exploration of the relation of painting to photography through his execution of &apos;the blur&apos;.', 3183, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3184, 'He is highly skilled at making photo realist paintings, which form a large part of his work.', 3184, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3185, 'Richter&#x2019;s colour photo realist works include one of his most popular works, a portrait of his daughter seen from behind, wearing a red floral print top with her blonde hair tied back.', 3185, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3186, 'This painting is made very realistic and the paint is smoothed soft so that there are no visible brushstrokes, emulating a photographs even in its physical surface.', 3186, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3187, 'He made similar paintings of a lighted candle and a baby.', 3187, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3188, 'A number of monochrome paintings of blocks of flats are given a more exaggerated blur, as are his numerous black and white paintings.', 3188, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3189, 'These include one of a chandelier, many landscapes and some trees.', 3189, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3190, 'Richter made two notable groups of painted photo portraits, all in the same format, one of the Baader Meinhof Gang and the other of German industrialists.', 3190, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3191, 'These are painted as direct copies from their source, including any text that was attached to the photo and the white edge of the photo.', 3191, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3192, 'Most of the photo based works are smallish, around one metre high or less.', 3192, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3193, 'A series of views of mountains are made to look like colour by numbers paintings, as if the image has been reduced to the essentials of light and dark.', 3193, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3194, 'Richter made some colour chart works, which are immaculately painted multi coloured shiny rectangles of colour within a white grid.', 3194, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3195, 'Taking the blur to its physical extreme his later work is a series of abstract paintings done with a giant squeegee dragged across the width of the canvas, spreading the various colours of paint into each other in one sweep.', 3195, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3196, 'Richter wrote a book called The Daily Practise of Painting.', 3196, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3197, 'David Salle', 3197, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3198, 'One of the best known postmodernist painters, Salle&#x2019;s paintings during the 1980s defined the term for painting of that period.', 3198, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3199, 'Salle borrowed elements and styles from paintings from any period in history and mixed them all up on the canvas.', 3199, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3200, 'His paintings are very large.', 3200, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3201, 'Julian Schnabel', 3201, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3202, 'Schnabel is an American artist known for the very large paintings (at least four metres high) made in the 1980s onto which he stuck broken crockery, mainly white dinner plates.', 3202, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3203, 'Schnabel has always worked on a large scale and in 2000 he made a ten metre high painting, painted on the floor, which had footmarks on it.', 3203, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3204, 'Mira Schor', 3204, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3205, 'American artist who makes abstract paintings that have feminist and psychoanalytic theoretical concerns.', 3205, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3206, 'Schor&#x2019;s paintings often contain a painted slit or vaginal motif.', 3206, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3207, 'Adrian Searle', 3207, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3208, 'British painter and critic who made small abstract paintings until the mid 1990s when he gave up painting to concentrate on writing about art.', 3208, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3209, 'Philippe Taaffe', 3209, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3210, 'American painter who first became successful in the 1980s with his large three metre high paintings using repeating patterns based on printed and woven fabric designs and geometric abstract drawings.', 3210, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3211, 'Taaffe&#x2019;s work exhibits a combination of precision, in the drawing of the pattern, and painterliness, in the application of paint over the whole and uses strong colours, for example yellow with black.', 3211, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3212, 'Mo Throp', 3212, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3213, 'British painter born in around 1950.', 3213, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3214, 'Tom of Finland', 3214, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3215, 'Pencil drawings of gay men variously dressed in leather, naked, sometimes in a state of sexual arousal often couples or threesomes, but sometimes alone.', 3215, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3216, 'They are realistic and detailed, made in the style of the drawings that used to be found in barbershop windows to illustrate hairstyles.', 3216, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3217, 'Tom of Finland&apos;s drawings document specific pleasures and codes of dress in a straightforward manner, but for all their sexually explicit subject matter they have a strange ambiguity in terms of their purpose.', 3217, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3218, 'Amikam Toren', 3218, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3219, 'British artist born around 1950 who makes works from found paintings onto which he stencils words, cutting out the letters to leave the wall behind the canvas visible.', 3219, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3220, 'Kyffin Williams', 3220, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3221, 'British artist born in the 1930s who spent his life painting the welsh landscape.', 3221, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3222, 'Williams&#x2019; impressionistic work is made with a very thick impasto, mostly paint applied with a palette knife to create a loose gestural interpretation using bright colours as well as a natural earth palette.', 3222, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3223, 'The paintings are rarely more than one metre high.', 3223, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3224, 'Sue Williams', 3224, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3225, 'American painter born around 1960 who makes figurative painting.', 3225, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3226, 'Her best known work is from the 1980s when she was known as one of a group of women artists described as Bad Girls for their strongly feminist, aggressive and angry work.', 3226, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3227, 'Pro Porn and Anti Porn, a painting from this period, shows a little girl&apos;s prone under a kneeling man seen from the rear, his erect penis and scrotum in full view.', 3227, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3228, 'There are other similarly explicit drawings on canvas with text.', 3228, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3229, 'The outline drawings in the paintings are done in black of grey on a coloured grounds.', 3229, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3230, 'Paul Winstanley', 3230, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3231, 'British artist who makes paintings of shadows cast by window frames, in which the structural elements of roofs, usually in black and white, are softened, the image becoming abstract.', 3231, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3232, 'By the 1990s digital technology and video had become commonplace.', 3232, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3233, 'Artists were increasingly working across a range of media, and were not necessarily confined to their studios.', 3233, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3234, 'Research based practises led artist to engage with institutions and with social groups.', 3234, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3235, 'Telecommunications and cheap travel made it possible for young artists to have international careers.', 3235, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3236, 'The art market grew.', 3236, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3237, 'The number of practising artists increased dramatically.', 3237, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3238, 'Painting, which had been said to have suffered a dip in popularity in the 1980s, became fashionable again.', 3238, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3239, 'Artists no longer sought to demonstrate the theoretical concerns underlying their practise.', 3239, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3240, 'The early part of the decade saw the emergence of so called &apos;dumbing down&apos;, art made as a reaction against the high production and intellectual values of 1980s art.', 3240, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3241, 'Faisal Abdul&#x2019;allah', 3241, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3242, 'In 2003 Abdul&#x2019;allah made an installation that invites the viewer to enter a large box like structure, people with light coloured eyes entering to the left, those with dark eyes to the right.', 3242, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3243, 'Once segregated by a genetic characteristic, the viewers find themselves in one of two spaces.', 3243, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3244, 'One is a small room with highly polished metallic floor walls and ceiling in a copper coloured metal that functions like a mirror and creates a glowing light.', 3244, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3245, 'On the floor is an inscribed text that addresses the viewer personally and asks them to consider their feelings on arrival in this space.', 3245, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3246, 'The other space, which is the larger remainder of the box like structure, is pitch black.', 3246, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3247, 'On entry it can be seen that the small room projects into this space, and is in fact constructed from a material that allows one way vision.', 3247, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3248, 'From the dark space the viewers in the small space can be seen clearly.', 3248, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3249, 'Although this would seem like a privileged space due to the materials of its construction, the people in it seem to be imprisoned, regarded secretly by the watchers in the larger space.', 3249, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3250, 'Tomma Abts', 3250, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3251, 'German painter born around 1970 who paints small abstract geometric works using very specific and carefully chosen combinations of colours and shapes.', 3251, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3252, 'The surfaces of the works show traces of intensive reworking and over brushing, evidence of the time taken to make the paintings.', 3252, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3253, 'Reverend Ethan Acres', 3253, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3254, 'Ordained clergyman from California who also works as an artist, making live works that combine a religious service with performance, usually involving a sermon, and other performers.', 3254, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3255, 'Add N to X', 3255, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3256, 'A partnership of two musicians, both born in the 1970s, who made video works in the late 1990s and early 2000s, on example is a continually changing colour grid was controlled by the soundtrack which accompanied it.', 3256, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3257, 'Shahin Affrassiabi', 3257, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3258, 'A British artist born in 1960, Affrassiabi&#x2019;s conceptual installations employ household items and materials to make formal sculptural constructions which reference other works of art.', 3258, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3259, 'Doug Aitken', 3259, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3260, 'American film and installation artist born in 1975.', 3260, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3261, 'Aitken first worked in commercials and used the experience gained in this field to make a series of multi screen and projected video installations.', 3261, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3262, 'Diamond Sea featured a deserted mining town in Namibia, which is not marked on state maps to ensure that its location remains secret.', 3262, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3263, 'A sense of the people who worked there is evoked (and their exploitation implied).', 3263, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3264, 'Aitken makes his own soundtracks, which form an integral part of the installations, sometimes several films are shown at once resulting in a blend of soundtracks.', 3264, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3265, 'Another work, a film of the audience attending a travelling cinema in India, was screened in a tented room with sand on the floor.', 3265, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3266, 'Aitken&#x2019;s work deals with location and presence, with a sense of place being a priority.', 3266, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3267, 'Philip Akkerman', 3267, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3268, 'Akkerman makes a self portrait every day of his life, each one in a different style.', 3268, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3269, 'The paintings are about fifty cm high.', 3269, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3270, 'Philip Allen', 3270, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3271, 'Allen is a British painter born 1970s whose almost abstract paintings of the early 2000s mark a change from his previous representational work.', 3271, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3272, 'The paintings have a roughly painted background and a multicoloured scallop motif on top, referencing landscape and abstract painting.', 3272, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3273, 'Darren Almond', 3273, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3274, 'Almond, a British artist born in the 1970s, is interested in time.', 3274, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3275, 'He made a large clock of the type that has the 24 hour time display in figures that flip over.', 3275, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3276, 'It shows the time going very fast so that a minute is a second and an hour is reached in a minute, and is to be mounted in a public institution or railway station.', 3276, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3277, 'He also made a large aeroplane propeller painted white and mounted it horizontally on the floor of a gallery so that its blades nearly touch the walls leaving just enough room for a person to pass.', 3277, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3278, 'He set up a live video link between a gallery and an empty prison cell, permitting the viewer a fly on the wall visit to a prison cell.', 3278, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3279, 'Almond also made a video titled Ghost Train, which is filmed in black and white in a ghost train at a fairground somewhere in Austria.', 3279, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3280, 'Shot from one of the cars, the film is grainy and visually lyrical as the low light conditions of the video affect what can be seen dramatically.', 3280, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3281, 'The sound of the train and the sound effects of the ride are edited with a musical soundtrack.', 3281, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3282, 'Another work is a replica of a bus shelter from a town where near a Nazi concentration camp.', 3282, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3283, 'Kai Althoff', 3283, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3284, 'Artist born around 1960 who makes bright water colour paintings on paper.', 3284, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3285, 'Francis Alys', 3285, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3286, 'Born in the 1950s, Alys is a Brazilian artist who made a series of works in the early 1990s by commissioning a sign painter to paint a sign, which he then placed in his studio and made a painting of the scene including the sign.', 3286, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3287, 'Janine Antoni', 3287, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3288, 'American artist born in the late 1970s who has made a series of performance works and installations.', 3288, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3289, 'Chocolate Gnaw and Lard Gnaw involved the artist chewing as much chocolate as she could from a one metre cube and melting the resulting chocolate to make chocolate pieces.', 3289, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3290, 'The lard chewed from a similar sized block was made into lipsticks and the residual blocks are displayed as part of the work.', 3290, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3291, 'She also cast busts of herself from the chewings.', 3291, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3292, 'The chocolate and lipstick products were displayed in luxurious packaging in a mirrored and gilt edged display case of the kind that might be seen in a department store.', 3292, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3293, 'She thereby made a connection between the basic act of chewing and eating, female relationships to food and body image (fat and chocolate) and cosmetics, and the role of packaging in the stimulation of desire.', 3293, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3294, 'In &#x2018;Harmony Hair Colour&#x2019; she used her long dark hair as a brush to make paintings with hair dye on large pieces of paper on the floor, referencing Yves Klein&#x2019;s blue paintings made using women&#x2019;s bodies as brushes.', 3294, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3295, '&#x2018;Sleep&#x2019; was an installation in which Antoni slept at night, wired up to a machine which recorded her REM patterns.', 3295, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3296, 'She transferred the resulting line on the graph drawn by the machine on a continuous sheet of paper onto a specially constructed wooden loom in the same room and wove on it a white fabric with the sleep patterns as a blue line.', 3296, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3297, 'The resulting fabric length was as long as the sleep graph, defined by the number of days Antoni slept in the gallery.', 3297, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3298, 'Antoni made the fabric into a nightgown.', 3298, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3299, 'Reza Aramesh', 3299, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3300, 'A British Iranian artist born in the 1960s who works in mixed media, made paintings of the branches of trees, and installations with furniture, wallpaper and real stuffed animals.', 3300, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3301, 'Liz Arnold', 3301, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3302, 'British artist born 1963 who painted women and anthropomorphised cats, very often with flowers, inhabiting story book universes, in strong colours with lots of black in a neat way.', 3302, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3303, 'Arnold&#x2019;s creatures inhabit the real world in an unreal way and often seem to be undertaking serious but mysterious business.', 3303, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3304, 'They are fashionably dressed and wear jewellery and have long eyelashes.', 3304, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3305, 'In one painting cats are wearing lab coats and there is a fiction atmosphere.', 3305, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3306, 'Arnold died in 2002.', 3306, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3307, 'Conrad Atkinson', 3307, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3308, 'British artist.', 3308, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3309, 'Attila', 3309, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3310, 'Russian figurative painter, born in 1960s who is one of the few Russian artists to be commercially successful in the west during the early 1990s.', 3310, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3311, 'Fabienne Audeoud', 3311, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3312, 'French artist born in the 1960s, Audeoud&#x2019;s work is often derived from her interest in classical music, for example a video works shows Audeoud as a diva singing to the point of collapse, and in another she appears as a fading diva on a self destructive binge in her bedroom.', 3312, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3313, 'There is a spare and often painful quality to these works, which are both abject and comical.', 3313, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3314, 'For one project Audeoud set herself the task of unlearning everything she knew about playing the piano which took many months.', 3314, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3315, 'Like many of her works, this was a daily practise.', 3315, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3316, 'She filmed a brass band rehearsing, whose discordance is at odds with their calm appearance.', 3316, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3317, 'She has also made several collaborative painting exhibitions with former Bank artist John Russell.', 3317, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3318, 'These are room sized narrative figurative paintings, quickly and badly made, with text added.', 3318, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3319, 'Donald Baechler', 3319, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3320, 'Alex Bag', 3320, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3321, 'American artist who worked in video in the 1990s and made a video about being an art student.', 3321, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3322, 'Stefan Balkenhol', 3322, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3323, 'German artist who carves large figures from whole tree trunks that are often over three metres high.', 3323, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3324, 'The figures are carved roughly and all the chisel marks are visible with no attempt being made to smooth the surface of the wood and they are then painted.', 3324, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3325, 'Balkenhol has made site specific work such as the six metre high figures he placed on wooden piles in the river Thames in London.', 3325, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3326, 'His carvings depict contemporary people whilst referring both to folk art and to historical polychromed sculpture.', 3326, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3327, 'Bank', 3327, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3328, 'British collaborative artists John Russell, Millie Thompson and Simon Bedwell, born in the 1960s, worked as Bank in the 1990s until Russell left in 2001.', 3328, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3329, 'Thompson and Bedwell continued to work as Bank until 2003.', 3329, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3330, 'Bank produced a large body of painting, sculpture, printed matter and texts as well as curating several seminal group exhibitions.', 3330, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3331, 'They directed their attentions at the art world making ironic and satirical work underpinned by a detailed knowledge of and love for art history, a sense of humour and a disrespect for the establishment (which could be seen as Bank&#x2019;s trademark).', 3331, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3332, 'Bank&#x2019;s painting spanned a range of styles including highly realistic still life featuring the detritus of their studio done in old master style, &#x2018;bad&#x2019; figurative painting, &#x2018;serious&#x2019; abstraction, and self portraits.', 3332, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3333, 'They explored the world of painting as iconoclasts.', 3333, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3334, 'Most of Bank&#x2019;s exhibitions were accompanied by a printed text in the form of a polemic on the state of art, of the world and of artists.', 3334, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3335, 'Bank Newspaper was self published for ten years, featuring news about the art world, drawings and photographs on a tabloid model.', 3335, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3336, 'Irreverent and downright rude, those (especially their targets) who failed to get the joke found nothing in Bank&#x2019;s work for them.', 3336, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3337, 'In 2000 Bank published their ongoing fax back series as a book.', 3337, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3338, 'For several years they had been returning press releases to the gallery that sent them, edited, corrected and with suggestions.', 3338, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3339, 'These served to highlight the pomposity, inaccuracy, bad grammar and inflated claims made about artist by their dealers to hilarious effect.', 3339, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3340, 'Bank also curated exhibitions the first of which was in a bank giving the group their name.', 3340, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3341, 'But most were held in Bank&#x2019;s studio in London&#x2019;s East End.', 3341, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3342, 'Other shows were titled Gallerie Poo Poo and Cocaine Orgasm which featured a life size self portrait sculpture of the group members on crucifixes.', 3342, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3343, 'In 2003 Thompson and Bedwell posed semi naked for a series of photos dressed as classical figures from paintings but using their untidy studio as a background and anything to hand as costumes and props.', 3343, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3344, 'Fiona Banner', 3344, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3345, 'Banner is a British artist born in 1965 who uses text as her material, first becoming known for a work called &#x2018;The Hunt for Red October&#x2019; in which she wrote out the entire synopsis of the film of that name by watching it.', 3345, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3346, 'She typeset this text and printed it, two metres high on paper in landscape format.', 3346, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3347, 'The text represented the entire film but was not possible to read due to the line length.', 3347, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3348, 'The viewer is forced to read vertically, skipping from line to line, producing their own unique reading of the text.', 3348, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3349, 'Banner followed this with several similar film synopsis works, culminating in The Nam, a huge paperback book which contains her synopsis of the film Apocalypse Now.', 3349, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3350, 'She also made an audio recording of herself reading this synopsis, which is produced in a flat vocal style.', 3350, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3351, 'Banner&#x2019;s work has most often referenced film, the book and the printed page, but she has also made work about songs and music, including a Bob Dylan song produced as a large work on canvas.', 3351, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3352, 'The words of the song are spelt out in large stencil style letters on unprimed canvases three metres high, then cut out so that the canvas is mostly gone.', 3352, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3353, 'The song stretches over several canvases.', 3353, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3354, 'Since 2000 Banner has made several sculptural works, three dimensional versions of punctuation marks which are carved from polystyrenes and painted or cast in bronze.', 3354, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3355, 'She has also made a number of works dealing with pornography, including some in which she removed all the text from a narrative leaving only the punctuation.', 3355, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3356, 'Guy Bar Amotz', 3356, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3357, 'Bar Amotz is an Israeli artist born in the 1970s who lives in London.', 3357, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3358, 'His work deals with sound and music in the form of sculptures that often incorporate speakers made from household objects, or especially made fibreglass structures which house audio and computer equipment which have a futuristic appearance.', 3358, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3359, 'He made a giant karaoke machine which can entered by the viewer and an amplifier which is worn as a backpack housed in a rigid fibreglass lacquered shell.', 3359, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3360, 'Bar Amotz sometimes uses metallic car spray to finish his sculptures.', 3360, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3361, 'In 2003 he made a machine to be worn by a dancer whose movements triggered various sensors so that the movement created the music.', 3361, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3362, 'Sally Barker', 3362, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3363, 'Barker made a performance work in the early 1990s for which she assumed an alter ego; Tela, a goddess or warrior queen.', 3363, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3364, 'Barker performed as the goddess sitting on a throne, with acolytes, dressed in a cross between Roman and Viking costume with gold sprayed greaves, wristbands and a helmet.', 3364, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3365, 'Matthew Barney', 3365, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3366, 'An American artist born in 1960s, Barney&#x2019;s prolific work includes video, film, and sculpture.', 3366, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3367, 'He made a performance work in 1993 with called Drawing Restraint in which he was tethered to the back wall of a squash court with a rubber bungee and used his own strength to get himself to the opposite wall, leaving marks on it to gradually make a drawing.', 3367, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3368, 'He also scaled a lift shaft in a multi storey car park naked, using climbing equipment, with a surgical implement or machine tool inserted in his anus.', 3368, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3369, 'These performances were documented on video.', 3369, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3370, 'They are followed by a series of sculptures made from solid petroleum jelly.', 3370, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3371, 'This is known both as a medicinal aid and a lubricant with sexual associations, and Barney used it to cast ambiguous sculptures that resembled gym equipment, rendered very realistically and shown in refrigerated spaces.', 3371, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3372, 'Petroleum jelly became a significant element of Barney&#x2019;s work.', 3372, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3373, 'Barney made a series of five feature length films called Cremaster I &#x2013; V, shot in 35 mm to commercial cinema standards, but made by a tiny crew and with the exception of the final film on a shoestring budget.', 3373, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3374, 'The series explores a surreal world of symbolism, perversion, fetishism and onanism.', 3374, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3375, 'The five films are conceived as a whole and were made over a period of 10 years.', 3375, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3376, 'One of the films is set on an American football pitch.', 3376, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3377, 'There is a long sequence of synchronised marching shot from above on a crane and from pitch level, featuring women dressed as glamorous grown up cheerleaders moving in tightly choreographed formation.', 3377, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3378, 'They begin at the edges of the pitch and gradually form the shape of one of the Cremaster logos, a kind of jewelled harp.', 3378, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3379, 'Another is filmed on a frozen lake on which a kind of snow fort has been constructed.', 3379, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3380, 'Cremaster Four is filmed on the Isle of Man and takes the Manx symbol of the three legs of man and the annual TT motorbike race as its main subject.', 3380, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3381, 'Barney&#x2019;s character is a kind of fawn with red furry legs and pointed ears, and there is a goblin and a peasant girl and her parents.', 3381, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3382, 'There are other exotic creatures all of which have strange mutant genitalia (a consistent theme in Barney&apos;s work).', 3382, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3383, 'Four is filmed on Giants&#x2019; Causeway and is based on the Celtic myth in which a pebble is thrown into the sea and becomes an island.', 3383, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3384, 'Another of the Cremaster series takes place both in the Guggenheim Museum in New York and in the interior of an airship with stewardesses in very chic uniforms seated round a table with a large display of grapes.', 3384, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3385, 'One of the stewardesses is under the table on a small shelf curled round the pedestal of the table.', 3385, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3386, 'She clings on precariously, while trying to and succeeding in making a hole in the table cloth above, using hairpins, and then gradually pulling grapes through.', 3386, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3387, 'The grapes are red and white.', 3387, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3388, 'She eats the grapes.', 3388, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3389, 'This is intercut with animated film of grapes in lines forming various symbols.', 3389, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3390, 'In the Guggenheim Barney, dressed as a Scottish piper in full ceremonial dress, slowly ascends the outside walls of the huge spiral stairway using climbing ropes and shackles.', 3390, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3391, 'On each level different people and groups are encountered, for example a long line of can dancing women who place one extended leg on the edge of the balcony for Barney to crawl under, an extremely beautiful woman, and a small child.', 3391, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3392, 'There is a section of the film which takes place in an empty warehouse and lots of water, Norman Mailer and Ursula Andress in a black jewelled outfit.', 3392, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3393, 'Cremaster Five is shot in a bath house in Budapest, and features an opera singer.', 3393, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3394, 'The last in the series to be made, Cremaster Three, is shot entirely on a set and features the Chrysler building in New York.', 3394, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3395, 'The film opens with a long sequenced involving a hermaphroditic almost dead person recently disinterred from a living grave being deposited in a black sedan in the centre of a hexagonal room which also contains a crow.', 3395, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3396, 'The arena is eventually recognised as an empty floor high up in the Chrysler building, and the corpse to be Gary Gilmore.', 3396, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3397, 'As the viewer imagines the crow to be pecking out the eyes of the corpse, five large apparently driverless cars emerge from the corners of the space and begin a kind of ballet, repeatedly hitting and gradually crushing the black sedan until it is no more.', 3397, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3398, 'A bar is staffed by a stereotypical Irish comedic barman who pours Guinness and becomes overwhelmed by foam.', 3398, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3399, 'Barney&#x2019;s character is a construction worker on the building.', 3399, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3400, 'He is a young handsome Irish character who has some mysterious secrets, revealed when he visits two &#x2018;doctors&#x2019; in a room in the building who reveal under his tattered clothes (including a leather apron with Masonic items in the pocket) his mutant genitalia.', 3400, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3401, 'He excretes a petroleum jelly &#x2018;turd&#x2019; which immediately mutates.', 3401, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3402, 'As the top of the building is constructed the man is involved in a kind of wedding at the pinnacle, under a floral arch with ribbons which are finally unfurled and thrown over the side of the building to float down until they are caught by the workmen and drawn in through the windows.', 3402, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3403, 'This is carefully choreographed to create a spiral of ribbons on the exterior of the skyscraper as if it were a giant maypole.', 3403, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3404, 'One the pair who is married has their head crushed by falling steel.', 3404, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3405, 'The mutant genitalia, gym equipment, logos and symbols of all the films relate to the title of the sequence, Cremaster.', 3405, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3406, 'The Cremaster is a muscle is located somewhere between the scrotum and the anus, it is significant in both sexual performance and procreation, but most people are unaware of it.', 3406, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3407, 'Barney treats the muscle as if it were one that could be worked, and as a metaphor for his own ideas about creativity and the individual.', 3407, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3408, 'Massimo Bartolini', 3408, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3409, 'Italian artist born second half of the twentieth century.', 3409, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3410, 'David Batchelor', 3410, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3411, 'British artist born in 1950s who uses coloured acrylic sheet to make strange utilitarian low trolleys in a multitude of colours which are then arranged to make an installation, or stacked to make a tower of coloured light.', 3411, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3412, 'Lolly Batty', 3412, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3413, 'British artist born in the 1960s who made a series of abstract sculptures of three dimensional polyhedrons, carved in polystyrene and painted look smooth and heavy as if they had been carved in plaster.', 3413, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3414, 'They have the appearance of one metre high geometric snow flakes smooth, clean and white.', 3414, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3415, 'Breda Beban', 3415, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3416, 'UK performance artist born 1950s.', 3416, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3417, 'Vanessa Beecroft', 3417, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3418, 'American performance artist Beecroft uses professional models to make her room sized installations, chosen for their perfect bodies and dressed alike, usually in underwear or naked but always wearing shoes and make up and usually wigs.', 3418, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3419, 'In one early work they are wearing yellow bobbed wigs and items of school uniforms, whilst in a more recent work they have natural hair but identical face and body makeup giving them an ethereal gleam, and high heels.', 3419, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3420, 'The models stand, sit or lie, however they feel comfortable, for the duration of the work usually four hours, and may engage the viewer&apos;s eye or not as they choose.', 3420, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3421, 'They do not speak.', 3421, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3422, 'Although the viewer is free to wander among them, no one does because the experience is intimidating.', 3422, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3423, 'It is Beecroft&apos;s intention to show supposedly objectified naked beautiful bodies of women rendered very powerful simply by their presentation and context.', 3423, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3424, 'The control of the situation is given to women by their very muteness, their make up and their beauty, traditionally seen as means of oppression.', 3424, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3425, 'Tony Benn', 3425, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3426, 'British figurative conceptual painter born late 1950s.', 3426, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3427, 'Bik Van der Pol', 3427, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3428, 'Dutch artist partners who make collaborative sociological investigations, setting up forums for investigation into contemporary art practises and in particular encouraging and facilitating cross nationality projects and interaction.', 3428, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3429, 'Richard Billingham', 3429, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3430, 'British photographer born around 1960 who has made a series of photographs of his own family which reveal a chronically alcoholic father who is either comatose or the life and soul, and an overweight mother who likes to laugh.', 3430, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3431, 'The pair watch a lot of television, drink, smoke and play with their other children and their dog.', 3431, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3432, 'Their house is very untidy.', 3432, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3433, 'The photographs are graphic and show Billingham&apos;s parents asleep, happy, sad, playful, and drunk.', 3433, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3434, 'The degree of intimacy permitted to the viewer is startling, asking the viewer to reconsider their preconceptions.', 3434, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3435, 'The photographs are all taken in the house with ambient light.', 3435, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3436, 'To get the image he wants, Billingham often places the camera low down or high up, using any angle necessary to get a certain part of the room or a certain number of people.', 3436, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3437, 'Billingham followed the photographs with a film, made in the same way, which reveals that his father is evidently going to die of a smoking related disease, and that the younger brother is very good at speaking on camera.', 3437, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3438, 'Billingham&#x2019;s work is characterised by its combination of casualness and thoughtfulness.', 3438, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3439, 'It could not have been made by anyone other than a family member, as it otherwise would have been intrusive and vicarious.', 3439, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3440, 'Equally it could only have been made at a time when the convention of fly on the wall documentary had been established and a fascination for the minutiae of ordinary lives become commonplace.', 3440, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3441, 'Olaf Bjornsdottir', 3441, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3442, 'Scandinavian artist.', 3442, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3443, 'Katrin Bohm', 3443, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3444, 'German artist born in 1970s who made social environments as gallery installations.', 3444, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3445, 'Bohm designed a colour coordinated social space, with various printed paper items, paper cups and pens to match.', 3445, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3446, 'She placed literature, questionnaires and other printed material in the space.', 3446, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3447, 'Nick Bolton', 3447, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3448, 'British artist born in the 1960s who has made installation and video work.', 3448, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3449, 'A telephone box with etched glass has a sensor attached to the mouthpiece so that when someone speaks on the phone, the light in the phone box becomes brighter or dimmer related to the pitch of the speakers voice.', 3449, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3450, 'Christine Borland', 3450, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3451, 'Scottish artist born around 1970 who made a number of works featuring hand guns, presenting a police blanket with a bullet hole in it and a caravan in a gallery, containing some evidence of a crime or the suggestion that a crime could be committed, with a handgun lying on a table.', 3451, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3452, 'Borland&#x2019;s work displays an interest in how material evidence can be represented as an art work and in how that visual evidence can be used by the viewer to construct a narrative.', 3452, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3453, 'Philippe Bradshaw', 3453, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3454, 'British artist born in the 1960s who makes large scale installations often using chain curtains.', 3454, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3455, 'These have photographic imagery on them and are made by a commercial technique using different coloured links to make the image.', 3455, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3456, 'An installation in a darkened room contained several of these curtains, some with photographs on, one with a nineteenth century landscape on, another with a Franz Hals painting on, placed around the space in the centre of which was a trampoline.', 3456, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3457, 'Video monitors displayed a montage of imagery and also a film of Bradshaw jumping on the trampoline naked, which had been performed as part of the installation.', 3457, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3458, 'The effect was that of multiple images, hard to grasp (the chain curtain images are hard to see at close quarters) and disorientating, but visually rich.', 3458, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3459, 'Stan Brakhage', 3459, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3460, 'Late twentieth century Canadian film maker, Brakhage has made a large body of video work.', 3460, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3461, 'He is interested in visual narrative and its disruption.', 3461, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3462, 'One work consists of a fictional tale performed by actors of the infidelity of a modern sea captain&#x2019;s wife, shown as one projection but which in fact consists of several plot lines woven together, leading the viewer to make choices about the direction of the narrative.', 3462, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3463, 'Another work takes twenty four hours to view.', 3463, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3464, 'A film set in a deserted house, shot in the dark by the light of one torch, is presented on a freestanding screen so that the viewer must walk around it.', 3464, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3465, 'Candice Brietz', 3465, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3466, 'Artist born in 1970s.', 3466, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3467, 'Cecily Brown', 3467, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3468, 'British artist born in the 1970s who paints very large splashy, dribbly and apparently messy works with tightly controlled colour choices.', 3468, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3469, 'At first glance these appear to be abstract expressionistic paintings but almost immediately they reveal themselves to be figurative, for hidden in the mass of brush marks and paint splashes is a meticulously constructed figure, or figures often in pornographic poses.', 3469, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3470, 'The works set up an expectation for the viewer and then almost immediately confound it, also making an analogy between abstract expressionism and sexual gratification.', 3470, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3471, 'Glenn Brown', 3471, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3472, 'Brown is known for his excessively meticulous paintings that reproduce exactly other works of art, or more accurately that reproduce reproductions of other works of art.', 3472, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3473, 'Brown scales up a reproduction, chosen from among many, all of which are different in colour due to the printing processes.', 3473, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3474, 'He then paints this reproduction faithfully in oil paint, using the tiniest of brushes, reproducing not only what the work depicts but also the actual brushstrokes, giving the painting a trompe l&#x2019;oeil quality.', 3474, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3475, 'In fact it is debatable whether Browns paintings are copies or trompe l&#x2019;oeil since they do seduce the viewer into thinking that their surface is thick paint textured when in fact it is flat and smooth.', 3475, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3476, 'This is particularly evident in a series of de Kooning copies, where the thickly encrusted paint is entirely realistic.', 3476, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3477, 'However on closer inspection the &#x2018;impasto&#x2019; has a plasticised quality.', 3477, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3478, 'Brown&apos;s de Kooning series culminated in a number of painted &#x2018;lumps&#x2019; &#x2013; apparently lumps of paint palette scrapings like those de Kooning reputedly had in his studio, but actually bronze casts painted by Brown to give the illusion of paint scrapings.', 3478, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3479, 'Brown subsequently copied Fragonard&apos;s Boy in a Hat, and girl on a swing, which he showed upside down, and a number of science fiction paintings by Chris Foss, which were the subject of a legal copyright action.', 3479, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3480, 'Brown&apos;s work deals with reproduction and its importance in the dissemination of the images, questioning whether what people know best is the image itself or its reproduction, and questioning the importance of the hand of the artist.', 3480, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3481, 'His main idea is to make painting the subject of itself.', 3481, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3482, 'Angela Bulloch', 3482, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3483, 'British artist born in the late 1960s.', 3483, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3484, 'Bulloch&apos;s sculptures and installations deal with the social structures of society, the rules by which we live and the deconstruction of art and image making.', 3484, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3485, 'Bulloch&#x2019;s 1990s works include a mudslinging machine which created a mud spatter &#x2018;painting&#x2019; on the wall, a drawing machine which drew a blue spattered line along a wall.', 3485, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3486, 'These machines were viewer activated in some way.', 3486, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3487, 'Often a piece of furniture designed by the artist would trigger the machines to work if sat on.', 3487, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3488, 'The machines would be presented in an environment which invited contemplation, the artist filling a space with bean bags made to her design, often large enough to seat groups of people.', 3488, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3489, 'The bean bags symbolised communality, and were a striking alternative to the customary formality of art galleries.', 3489, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3490, 'Bulloch was one of a number of artists in the 90s who were explored the relationship of the viewer to art but more particularly to the institutional context in which they found it.', 3490, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3491, 'She questioned the normalising structures by which we live by presenting such structures in new ways.', 3491, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3492, 'Her Rules works are an example of this &#x2013; presenting rules designed for specific purposes as if they are general rules to live by, rules that may be written in a small book are put on a wall using transfer lettering, giving them a perverse authority In early 2000s Bulloch made some small sculptures from chewed gum which she then cast and painted.', 3492, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3493, 'She continued her series of works made from pixel boxes, her own invention which consists of a wooden box with one opaque acrylic face, inside which is a light source with the capacity to change colour infinitely.', 3493, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3494, 'This is linked to a computer, which is able to control the change of light colours, using as its instructions of the changes the pixels in a video image, or a piece of music.', 3494, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3495, 'Bulloch stacks the pixel boxes vertically in a variety of formations and also horizontally to create the effect of an illuminated dance floor and minimal abstract sculpture.', 3495, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3496, 'In the latter case the pixels were controlled by sound.', 3496, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3497, 'Bulloch often works with sound, and in 2003 she made a number of small sculptural objects, smooth amorphous shapes sprayed with white lacquer, which on handling revealed an inbuilt and incongruous means of generating sound, perhaps in response to light levels for example.', 3497, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3498, '] ! Tom Burr.', 3498, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3499, 'American artist working in the 1990s onwards.', 3499, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3500, 'Jane Bustin', 3500, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3501, 'British painter born 1960s who makes severe abstract works that are both investigations into the effect of colour and pigment, surface and also into votive painting and the painting as symbolic or spiritual object of contemplation.', 3501, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3502, 'Bustin uses natural colours, dark reds, blues, black white.', 3502, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3503, 'There is never a figurative element in her paintings, merely subtle shifts in tone that may hint at a form.', 3503, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3504, 'Caivano Varda', 3504, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3505, 'Still life painter working in the early 2000s.', 3505, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3506, 'Ingrid Calame', 3506, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3507, 'Calame&apos;s apparently abstract paintings are in fact taken from the outlines of stains she finds on the street and in public places.', 3507, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3508, 'She photographs the ground, draws the outlines of the stains, then paints the canvas in subtle colours to create an abstract image from something very mundane and ephemeral.', 3508, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3509, 'John Callan', 3509, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3510, 'British sculptor born in 1960s who pushed paint through pin pricks following the lines on pages of text in an open book to create painted text.', 3510, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3511, 'Callan also built a small house or dog kennel out of bricks and mortar.', 3511, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3512, 'Ellen Cantor', 3512, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3513, 'British artist born in the 1960s who makes video and drawings.', 3513, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3514, 'Janet Cardiff and Georges Bures Miller', 3514, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3515, 'Canadian artist and musician/sound engineer partner working from the 1990s onwards.', 3515, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3516, 'Cardiff made a work for the Whitechapel Library in London which took the viewer on a walking tour &#x2013; the viewer was given a personal CD player which directed their steps and used sound to interpret and accompany what they were seeing.', 3516, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3517, 'She made a gallery installation with a choir in which the choir members, performing a medieval choral work, were recorded individually, and then played through individual speakers placed on speaker stands at ear height in a circle in the gallery.', 3517, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3518, 'Thus the viewer could choose how to experience the work by where they stand, and hear each voice individually.', 3518, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3519, 'This gave a sense of what it is like to be part of a choir, and also a sense of the physical space which a choir occupies and how that space is experienced aurally.', 3519, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3520, 'The gallery space is also articulated by where the sound is coming from &#x2013; this varies according to whether the whole choir is singing, or just the sopranos in one segment of the circle, or a few of each type of voice dotted round the circle.', 3520, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3521, 'The work gives the non participant a participatory experience and inverts the performer listener relationship.', 3521, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3522, 'Gillian Carnegie', 3522, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3523, 'British artist born in the late 1960s who began her career in the 1990s.', 3523, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3524, 'Carnegie makes paintings in two distinct ways.', 3524, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3525, 'She paints her own and other female bodies nearly always the back view, mainly featuring the buttocks in a realist way using muted lifelike colours.', 3525, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3526, 'These paintings are small, about forty cm high.', 3526, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3527, 'She also paints landscapes in extremely thick impasto, the canvases ranging from forty cm to 150 cm high.', 3527, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3528, 'These landscapes are usually woodland scenes, sometimes with lakes, rarely featuring people.', 3528, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3529, 'The paint is sometimes squeezed straight from the tube so that close up the image is nearly impossible to read, in particular in the paintings which are predominantly one colour, often black or very dark colours, as if it were night.', 3529, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3530, 'In these paintings the image is revealed by the sheen on the squeezes and smears of the paint, the texture and the shadows created.', 3530, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3531, 'In other landscapes more typical colours are used, blues, browns and greens, but in all the landscapes the vegetation is rendered in detail, as is the bark of trees and the ripples on water.', 3531, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3532, 'There is a sinister atmosphere in the images, although they appear timeless there is somehow the implication of a contemporary narrative.', 3532, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3533, 'Similarly with the nudes, although a traditional subject, the fact that they are often self portraits coupled with her obsession with bottoms, gives a contemporary twist to the sexual projection of these images and hints at both onanism and voyeurism.', 3533, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3534, 'Carnegie subsequently began to paint floral still lifes, using a much lighter palette although still restrained.', 3534, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3535, 'In these the background and any vessels holding the flowers are painted smoothly and the flowers are rendered in her style of thick impasto and squeezings, a few judiciously placed ones making them very convincing as flowers.', 3535, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3536, 'Carnegie&apos;s paintings make an investigation into the history of painting styles and subject matters, subverting traditional subject matter by making anachronistic and unexpected juxtaposition of style and content.', 3536, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3537, 'Melanie Carvahlo', 3537, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3538, 'British artist who is interested in how people conceptualise their world.', 3538, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3539, 'In a work from 2002 she invited a large number of people from all walks of life to make a painting of &#x2018;home&#x2019;.', 3539, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3540, 'She displayed the resulting works in a gallery as part of an installation.', 3540, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3541, 'Carvahlo also makes complex photo collages that include people, buildings and brightly coloured exotic flowers and sunsets.', 3541, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3542, 'Maurizio Cattelan', 3542, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3543, 'Sculptor and installation artist who uses stuffed animals in his work.', 3543, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3544, 'Cattalan hung a dead stuffed horse from the ceiling in a sling, made to look as if it were either dead or tranquillised.', 3544, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3545, 'He made an effigy of the pope toppling to the floor felled by a meteorite.', 3545, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3546, 'A table football game for two teams of eleven to play simultaneously.', 3546, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3547, 'A squirrel slumped at a tiny table with a gun indicating that it had committed suicide.', 3547, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3548, 'A small boy wearing a hooded sweatshirt sitting at a school desk who has speared a pencil through his hand.', 3548, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3549, 'Cattelan&#x2019;s work is often intended to be disturbing and provocative.', 3549, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3550, 'A large format photograph of the back of the Hollywood sign reversed so that it reads the right way, apparently installed in a mountainous area, it is unclear whether a huge deconstruction was undertaken to make the photograph or whether it is digitally created.', 3550, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3551, 'Brian Dawn Chalkley', 3551, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3552, 'British artist born 1950s, Chalkley is a transvestite who works as both a man and a woman.', 3552, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3553, 'He uses video and photography to investigate identity, for example in a film in which Dawn is seen in various dangerous scenarios, alone in isolated places having possibly been attacked.', 3553, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3554, 'Jake and Dinos Chapman', 3554, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3555, 'British artists born in mid 1960s the Chapmans are brothers who work together.', 3555, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3556, 'They became known in 1993 for Disasters of War, a sculpture that recreated Goya&#x2019;s disasters of war as a 1:100 scale model.', 3556, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3557, 'This grisly scene was presented on a plinth the size of a table top, realistically made and leaving nothing to the imagination.', 3557, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3558, 'Flayed corpses hang from trees, severed limbs are strewn about, headless torsos are propped up, heads stuck on bayonets.', 3558, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3559, 'They later made a series of etchings based on this work in homage to the original.', 3559, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3560, 'Another early work was Little Death Machine, a working machine built in model scale and presented in a vitrine on a plinth.', 3560, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3561, 'It was a rubber model of a brain that functioned as a pump to spurt out white liquid.', 3561, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3562, 'On one hand the Chapmans&apos; work is deeply rooted in art history, politics and subversion with implied criticism of Western capitalism and of the failure of art to deal with important issues.', 3562, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3563, 'On the other hand the artists delight in the puerile and a childish humour and set out to deliberately and defiantly shock.', 3563, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3564, 'It is the Chapmans&apos; life size sculptures of mutant children that are most notorious in this regard.', 3564, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3565, 'These children, which are adapted from shop window mannequins, are made in what has become their main medium of cast fibreglass with realistically airbrushed skin and features.', 3565, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3566, 'They have genitalia on their face and smooth skin where their genitals should be.', 3566, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3567, 'A girl might have a vagina as a mouth, or several orifices on her body where none would usually be.', 3567, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3568, 'A boy may have a penis as a nose.', 3568, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3569, 'The children are posed in apparently compromising positions and situated in a beautiful garden.', 3569, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3570, 'There are trees and plants with large fantasy flowers and grass made from a material that resembles a scaled up version of the green sand like material used as grass by model makers and model railway enthusiasts.', 3570, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3571, 'in this work, as in all their work The Chapmans have taken a basic human urge, such as the urge to kill, the sexual urge and its many perversions, and urge to power and represented it in order to confront their viewer with the possibility of discovering such urges in themselves.', 3571, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3572, 'In this sense their work is highly politicised.', 3572, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3573, 'The artists subsequently created The Disasters of War as a life size work.', 3573, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3574, 'The Chapmans made a porn film featuring people with mutant prosthetic genitalia attached to their bodies.', 3574, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3575, 'They continued to make etchings and other works on paper, and to make large scale installations and models.', 3575, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3576, 'Their McDonald&#x2019;s Concentration camp, made in 2000, is a very large 1:50 model of a fictitious concentration camp, which has McDonald&apos;s logos.', 3576, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3577, 'The camp processes people, and the viewer can see tiny figures being brought in, living in squalor, being killed and &#x2018;processed&#x2019; in various ways.', 3577, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3578, 'Much of what the model depicts is familiar to us not through experience but through fictitious depiction on film and television and the model relies on this to animate it.', 3578, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3579, 'The work makes a literal analogy between a fast food company bringing cheap food to the masses with no concern for their detrimental and social impact, and the Nazis.', 3579, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3580, 'They have also made larger scale sculptures again in their usual medium of cast fibreglass, realistically painted with an airbrush, which represents a kind of gothic heavy metal concentration camp monument with massed skulls, very black and dark.', 3580, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3581, 'In 2003 the Chapmans&apos; presented a darkened room apparently full of African tribal art, painted wood carvings which have added grass, beads and teeth.', 3581, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3582, 'The room is like a museum, darkened to lend a familiar reverence to the sculptures set on plinths.', 3582, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3583, 'There is a deadened acoustic.', 3583, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3584, 'On closer inspection the viewer can see that the carvings all in some way feature the MacDonald&#x2019;s logo, the golden M, or represent a burger or Ronald McDonald the company&#x2019;s clown mascot.', 3584, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3585, 'These are cleverly worked as &#x2018;African&#x2019; looking sculpture, Ronald McDonald a totemic figure, the burger often the mouth of a figure, the M appearing as a decorative element.', 3585, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3586, 'Lali Chetwynd', 3586, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3587, 'Artist working in London, Chetwynd made several performance works in the late 1900s and early 2000s.', 3587, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3588, 'Lisa Cheung', 3588, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3589, 'Korean artist born in the 1970s who makes photographic works often shown as slide projections.', 3589, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3590, 'Andrew Child', 3590, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3591, 'British artist born in the 1960s.', 3591, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3592, 'Billy Childish', 3592, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3593, 'British artist, poet and musician born around 1960.', 3593, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3594, 'Childish has made a large number of na&#xef;ve figurative paintings often of himself and his friends on found wooden boards, the sides of boxes, and other unconventional materials.', 3594, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3595, 'He is known equally for his poetry which includes, and makes a virtue of, his dyslexic spelling errors, and for the punk band which he fronts, Thee Headcoats.', 3595, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3596, 'Although he has worked in this way since the early 1980s, in the late 90s Childish achieved a notoriety beyond his cult following when he was immortalised by ex girlfriend Tracy Emin in several works, including her embroidered tent &#x2018;Everybody I Have Ever Slept With&#x2019;.', 3596, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3597, 'Since then Childish formed the Stuckists, a self proclaimed movement that promotes the idea that British art in particular the work of the artists that make up so called Brit Art, is simply &#x2018;stuck&#x2019;.', 3597, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3598, 'The Stuckists set out to critique it, by means of pamphleteering, demonstrating, fly postering and other public protestation and interventions.', 3598, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3599, 'John Chilver', 3599, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3600, 'Born in the 1960s the British painter Chilver has made paint itself the subject of his conceptual paintings.', 3600, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3601, 'He uses paint squeezed or piped in the way icing would be to decorate a cake, through a square nozzle, to produce a three dimensional line on the canvas.', 3601, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3602, 'He also adds paint from a traditional round nozzle.', 3602, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3603, 'The paintings depict simple scenes, for example a fence with a bird on it.', 3603, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3604, 'Or a style with a clump of grass.', 3604, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3605, 'The fence or style will be piped in square lines often black or dark grey, the bird in many colours of thinner round lines, the whole giving the impression of casualness and speed of execution when in fact the reverse is obviously the case.', 3605, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3606, 'Chilver often uses puns in his title, for example &apos;style&apos; and &apos;stile&apos;.', 3606, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3607, 'He investigates the nature of painting the painted mark, without actually painting at all since the backgrounds are entirely flat and the paint is never touched by a brush or worked at all.', 3607, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3608, 'Adam Chodzko', 3608, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3609, 'British artist born 1960s.', 3609, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3610, 'Looking for Jesus is a work made in the 1990s.', 3610, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3611, 'Chodzko placed a classified advertisement requesting people who thought they looked like Jesus to send him passport photos.', 3611, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3612, 'Often they bore no resemblance at all.', 3612, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3613, 'Chodzko made a work with Afghan refugees living in Hastings in 1990 in which he asked them to sort through and select from the archive of Cubitt, an artist run organisation in London.', 3613, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3614, 'The selection was placed in a watertight box and buried below the high water mark on the beach at Hastings.', 3614, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3615, 'Another work from 2003 was site specific, Chodzko placed a billboard in a field in Texas on which it was printed the directions to a billboard outside a gallery in London, which again had printed the directions to the billboard in Texas.', 3615, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3616, 'A kind of transatlantic endgame with the idea of encouraging a sense of place, geography, time and space.', 3616, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3617, 'A photo of the American billboard was displayed at site of the British one and vice versa.', 3617, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3618, 'Chodzko&apos;s work is usually socially engaged and often involves research, correspondence or mass participation.', 3618, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3619, 'Anne Collins', 3619, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3620, 'American artist born in the 1970s who makes photographs, for example of women in urban and rural landscapes, with a precisely controlled banality.', 3620, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3621, 'Matt Collishaw', 3621, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3622, 'British artist born in the 1960s who among other works has made a large format photograph of a bullet entrance hole in a person&apos;s scalp.', 3622, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3623, 'George Condo', 3623, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3624, 'American artist born around 1960 who makes paintings that use art historical references, often nearly remaking a particular work but with his own often fantastic twists and distortions so as to create an entirely contemporary version of a painting from history.', 3624, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3625, 'The paintings use a variety of styles and usually bright colours, and although they have a clearly historical reference they often have a science fiction or fantasy reference too.', 3625, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3626, 'Condo also paints LP covers, turning them into large paintings around a metre high.', 3626, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3627, 'Melanie Counsel', 3627, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3628, 'British artist born around 1960.', 3628, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3629, 'Keith Coventry', 3629, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3630, 'British artist born in 1960s who paints white on white paintings that reproduce famous paintings in oil paint without colour.', 3630, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3631, 'Martin Creed', 3631, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3632, 'Scottish artist born around 1960 who makes sculpture and installation from almost nothing.', 3632, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3633, 'All his work is assigned a number and a description for the title, for example, A Door Opening and Shutting, The Lights Going On and off, One A4 Sheet of Paper Screwed Into a Ball.', 3633, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3634, 'Further works include a cube made of layers of elastoplast, a cube made of layers of masking tape cubes, a bulging protrusion from the wall of a room which is plastered and painted to be as part of the wall.', 3634, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3635, 'Creed&apos;s work is sometimes active, for example one which consists of a room full of white balloons through which the viewer must push their way.', 3635, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3636, 'This references Yves Klein&#x2019;s &#x2018;Void&#x2019;, and empty gallery space.', 3636, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3637, 'The door that opens and shuts is operated by a door closer on a timed switch.', 3637, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3638, 'The lights going on and off is similar.', 3638, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3639, 'This work has also been &#x2018;performed&#x2019; by Creeds.', 3639, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3640, 'band Owada &#x2013; whenever the lights came on the band played, whenever they went off the band stopped, as if the electricity supply for the amplifiers were linked to the lights.', 3640, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3641, 'Or the other way around.', 3641, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3642, 'Owada which can be described as making minimal conceptual music gained success as an art band in the late 90s and early 2000s with tracks such as One to A Hundred, which featured Creed speaking these numbers in order and the band playing rising scales one note per number.', 3642, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3643, 'Gregory Crewsdon', 3643, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3644, 'American artist who makes photographs of staged events that appear to be crime scenes.', 3644, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3645, 'There is something of the supernatural about the images, which have an unreality due to the highly controlled lighting and decisions made in the printing.', 3645, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3646, 'A small town petrol station is seen from above at night and the disposition of people and vehicles seems strangely static, leading the viewer to guess at possibilities, perhaps to wonder whether there has been or is about to be an alien invasion.', 3646, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3647, 'Another work might show a person looking at the sky, presaging some unknown possibly extra terrestrial event.', 3647, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3648, 'The photographs are complex and ambitious in their construction of a subtly warped reality, shot on location rather than in a studio.', 3648, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3649, 'Russell Crotty', 3649, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3650, 'American artist born around 1960 who makes obsessive biro drawings sometimes on large sheets of paper, also in very large books, at least eighty cm high.', 3650, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3651, 'The drawings are made by colouring in with blue biro, using the pen for the purpose for which it is least suited, on a scale which is plainly absurd.', 3651, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3652, 'Juan Cruz', 3652, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3653, 'British artist born in the mid 1960s who works with sound and text.', 3653, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3654, 'Cruz made an installation performance in which he translated the text of Cervantes&apos; great Spanish novel Don Quixote in real time over a number of days.', 3654, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3655, 'He also made a work based on the Duende, an untranslatable Spanish word that describes the &#x2018;feeling&#x2019; needed to perform flamenco.', 3655, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3656, 'Cruz is chiefly interested in language and translation.', 3656, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3657, 'Shane Cullen', 3657, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3658, 'Northern Irish artist who made a large scale text installation for which he printed or stencilled or used transfer lettering to inscribe the letters written to him during a correspondence he had with political prisoners on remand in the H block, a notorious prison in Northern Ireland.', 3658, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3659, 'These covered the walls of the exhibition space.', 3659, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3660, 'Stewart Cumberland', 3660, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3661, 'British painter born in the 1970s.', 3661, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3662, 'John Currin', 3662, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3663, 'American painter born in 1962 who became extremely successful in the late 1990s and early 2000s.', 3663, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3664, 'Currin made his name by painting women with unfeasibly enormous breasts, made in a mixture of kitsch and old master style.', 3664, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3665, 'The women have exaggerated cartoon like features yet the colours used are entirely realistic, seeming to be there to hold the male gaze and fulfil male desire.', 3665, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3666, 'They are however often painted in pairs, absorbed with each other, ignoring the viewer.', 3666, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3667, 'Currin also paints portraits of real people, still lifes and interiors.', 3667, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3668, 'His knowing and anarchic use of virtuoso painting techniques and undeniable skill in painting and drawing is allied with subject matter that would have been entirely unacceptable in the 1980s or early.', 3668, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3669, 'Brian Cyril Griffiths', 3669, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3670, 'British artist born in the 1960s who has made a number of installations from cardboard, discarded materials, empty plastic containers and any number of banal materials.', 3670, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3671, 'Griffiths&#x2019; space ship command module control panel made in 1997 was an adult sized version of a child&#x2019;s dream.', 3671, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3672, 'Griffiths has made many objects that seem like things that the viewer may think that they could make themselves but for the scale.', 3672, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3673, 'In 2003 Griffiths made a hansom cab from a selection of second hand furniture, piecing specific parts together to make a three dimensional wooden collage.', 3673, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3674, 'He also made a large striding warrior figure in the same way.', 3674, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3675, 'Dexter Dalwood', 3675, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3676, 'British artist born in 1960 who makes figurative history paintings.', 3676, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3677, 'Dalwood began his career painting expressionistic autobiographical narratives, often depicting himself and members of his family, particularly his father.', 3677, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3678, 'He spent a year working in India and the influence of Indian miniatures is clear in his work of this period.', 3678, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3679, 'Dalwood began to use the photograph as a source for his work around 1989, when his work became less narrative.', 3679, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3680, 'He used images of multiple reflections in windows, grids and all over lattice patterns to create veil and screen effects in which appeared various motifs, for example a painted wooden toy bird.', 3680, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3681, 'Dalwood also began to make groups of small paintings which were hung together.', 3681, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3682, 'One such group depicted various personal histories, including paintings based on photographs of his father as a young man.', 3682, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3683, 'His style of painting remained eclectic using a variety of textures, methods of application and thickness of paint.', 3683, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3684, 'In 1995 Dalwood began a series of paintings of interiors which marked a change in his work.', 3684, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3685, 'These mainly featured ceilings and light fittings, and are the only works of Dalwood&#x2019;s that come close to abstraction.', 3685, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3686, 'Dalwood began to paint fictitious interiors, making a collage from magazine cuttings and then replicating it on canvas, including the cut edges of the paper and differences in colour of sky, for example, taken from two different places.', 3686, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3687, 'The interiors are imagined for a variety of well known people, such as Elvis&#x2019; Living Room, Bill Gates&#x2019; Bedroom, and also famous venues such as Studio 54 night club, Liberace&#x2019;s Drawing Room.', 3687, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3688, 'These collaged interiors function as portraits of a person but they began to include the work of other artists.', 3688, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3689, 'Dalwood combined the work of an artist whom he connected in some way with the person he was making the painting about and added a part of their work to each composition by collaging.', 3689, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3690, 'Mary Shelley is combined with Munch and Friedrich, Nixon with late Braque, Che Guevara with Piero della Francesca and Mao with Antonello da Messina.', 3690, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3691, 'A painting of the greenhouse in which Kurt Cobain committed suicide has cherry blossoms from a Van Gogh painting.', 3691, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3692, 'In this way Dalwood has made a series of portraits of famous people from a variety of walks of life.', 3692, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3693, 'In 2000 he began to make the connection with history painting more explicit by making paintings that referred to a date rather than a person.', 3693, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3694, 'Dalwood&#x2019;s paintings are between one and four metres high and he uses a range of techniques according to the artist to whom he is making reference.', 3694, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3695, 'Adam Dant', 3695, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3696, 'British artist born in the 1970s who makes wry satirical cartoon style drawings about art, artists, and the art world.', 3696, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3697, 'Dant&#x2019;s project is serious and comprehensive in its ambition to comment upon everything that happens but to make sure that art doesn&apos;t take itself too seriously.', 3697, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3698, 'He began by making a weekly self published pamphlet, much in the vein of eighteen century pamphleteers soapbox speakers.', 3698, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3699, 'The pamphlet was hand drawn and written by a pseudonymous character invented by Dant to represent himself (who was often shown in the drawings).', 3699, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3700, 'It was a bit like a diary and featured topical news about art and advice written in mock serious style.', 3700, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3701, 'It was photocopied and folded into a pocket sized booklet which Dant himself distributed wherever he went free of charge.', 3701, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3702, 'He did this every week for several years, and it was the long term nature of the project that made it successful.', 3702, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3703, 'Dant constructed a portable booth from which to distribute the pamphlet and became a presence at art fairs and museum exhibitions.', 3703, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3704, 'By a simple weekly action Dant produced a major work.', 3704, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3705, 'Ian Davenport', 3705, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3706, 'British artist born in the 1960s who began to make the drip paintings for which he became known in the 1990s.', 3706, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3707, 'Davenport poured liquid paint onto a canvas from the top, allowing gravity to take the drip to the bottom of the canvas in a perfectly vertical line.', 3707, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3708, 'He continued in this way across the width of the canvas using different colours until he had achieved a striped painting made without a single brushstroke, or any touch of the artist&#x2019;s hand.', 3708, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3709, 'At first sight the stripes would appear to have been painted with a brush perhaps even using masking tape, but on closer inspection tiny irregularities in the pour and the quality of the edge of the stripes made it obvious how the painting was made.', 3709, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3710, 'Sometimes the paintings were in sombre colours, other times they were rainbow striped.', 3710, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3711, 'Later Davenport developed various ways of making the pouring easier (fixing the paint pot to a runner for example) and he was able to make bigger canvases and even to pour directly onto a wall.', 3711, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3712, 'Davenport also made paintings by pouring a coating of one colour of paint onto a canvas placed horizontally, and then adding in a stripe, a line, and arc in a contrasting colour by pouring directly into the wet surface.', 3712, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3713, 'The two colours when dry formed a perfect flat shiny surface, in the way that the technique of enamelling can be used to combine colours.', 3713, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3714, 'Enrico David', 3714, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3715, 'British Italian artist born in early 1960s who made a series of very large embroideries mounted on stretchers in the late 1990s.', 3715, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3716, 'These were taken from collages and drawings he made from fashion magazines depicting women in fetish wear, extremely stylised clothes, very exaggerated bodies, very high heels, masks, drawn in a geometric style often with a 1920s or 30s feel.', 3716, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3717, 'Although the images were of women they depict a non specific sexuality, the women often have large masculine bodies and may seem more like cross dressed men.', 3717, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3718, 'David used woollen thread to fill in the figures with satin stitch, and due to the scale of the image (often two metres high or more), the stitches sometimes needed to be over a metre in length.', 3718, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3719, 'Sometimes the stitches represented rays of light, too, or in one case silver thread was used on a blue canvas to represent the tight binding on the body of a model.', 3719, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3720, 'David uses any craft materials or fabric that he likes to create these creatures.', 3720, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3721, 'One has a butterfly entirely concealing her face, like a mask.', 3721, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3722, 'Another is like an African queen.', 3722, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3723, 'They are decadent and often sexual images, their handcraft materials at odds with the subject matter.', 3723, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3724, 'He also made items of furniture and lamps.', 3724, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3725, 'David began to work on some photo collages in 2000, using photos of himself wearing coloured paper constructions &#x2013; red and blue, black and white, something like the costumes designed by the dada artists for Cabaret Voltaire.', 3725, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3726, 'Other collages used images from magazines and often the background paper was cut in a certain way so that the found image could be raised from the background.', 3726, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3727, 'He used brooches and other found jewellery and began to use carpentry, furniture making and decorative arts materials.', 3727, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3728, 'In 2000 David began to draw men.', 3728, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3729, 'A man in evening dress appears before the closed curtain of a theatre in a drawing in back and white that looks very much like a woodcut.', 3729, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3730, 'A sculpture of a male figure is made of plywood coloured with wood stain; the profile of the figure is cut twice from sheets of ply and slotted together at right angles to each other.', 3730, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3731, 'Turned wooden knobs are added to represent testicles.', 3731, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3732, 'A large rag doll three metres high is made of canvas, stuffed, and embroidered with facial and bodily features and decorative patterns, and presented sagged against a plywood cabinet and lying on the floor.', 3732, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3733, 'A gallery door is replaced by an etched glass and metal door that has an art nouveau style.', 3733, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3734, 'A very long plywood screen covers the length of a gallery wall, on it a repeating interlinked pattern of a stylised male figure that has a 1930s look is made by incising the wood and using wood stain to create a kind of faux marquetry.', 3734, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3735, 'A giant leather medal hangs on the wall.', 3735, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3736, 'David was briefly a member of Donatella a group of artists and musicians who produced music videos and CDs, and made work in collaboration with fashion designers Eley Kishimoto for catwalk shows.', 3736, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3737, 'Peter Davies', 3737, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3738, 'British artist born around 1970 who began his career making paintings consisting of many coloured dots on a white background on huge three or four metre wide canvases, creating patterns of waves, like an abstract pointillism.', 3738, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3739, 'Davies always uses acrylic paint applied as flat solid colour.', 3739, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3740, 'He went on to make text paintings in the later 1990s.', 3740, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3741, 'For example The Hot 100 is a numbered list drawn up as a table in two columns with the lines painted in white, of the artists personal hundred favourite artists, painted in white on a multicoloured ground, a different colour for each line of text.', 3741, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3742, 'The list functions as an illustration of subjectivity presented as a formally considered abstract painting.', 3742, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3743, 'Davies subsequently made a diagram painting describing twentieth century art in terms of interlinked artists and movements.', 3743, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3744, 'The text is painted in white on coloured elliptical or circular shapes to fit each name or title, which are linked or cross linked by coloured lines, the whole on a white background.', 3744, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3745, 'Davies then began to make a series of very large pattern paintings at least four metres wide.', 3745, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3746, 'The paintings are abstract three dimensional patterns that cover the picture plane and create a surface pattern, some painted in bright colours, some in monochrome, a bit like geometric doodles that play with simple perspective and convex and concave illusion.', 3746, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3747, 'Like the text paintings these are painted in flat acrylic paint, with hard edges to the colours painted by hand rather than masked.', 3747, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3748, 'Some of them allude vaguely to Robert Delaunay&#x2019;s paintings and to 1930s textile patterns, others to futuristic cityscapes.', 3748, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3749, 'Peter Davis', 3749, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3750, 'British artist ! Verne Dawson.', 3750, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3751, 'American artist whose paintings depict an apparent utopia, a kind of modern pastoral world, with tiny people on the scale of the people in a Bosch painting populating rural and woodland scenes.', 3751, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3752, 'Angela De la Cruz', 3752, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3753, 'British artist who makes sculptures from collapsed and destroyed paintings.', 3753, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3754, 'De la Cruz&apos;s method is to construct a canvas which may be any size (from tiny to the largest which was a large scale installation of a canvas about fifteen metres squared).', 3754, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3755, 'She paints the canvas in a plain colour, and then destroys it by breaking the stretcher and then twisting the whole into a heap.', 3755, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3756, 'This is then fixed and either displayed on the wall or the floor.', 3756, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3757, 'These deceptively humble objects assume the presence of a sculptural object, thus a painting is transformed.', 3757, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3758, 'Richard Deacon', 3758, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3759, 'British artist Deacon began making very large sculptures in the 1980s at a time when sculpture was at a zenith of popularity.', 3759, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3760, 'Deacon and his contemporaries Bill Woodrow and Grenville Davey made abstract works largely from cheap easily available materials.', 3760, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3761, 'Deacon used reclaimed wood which he cut into strips, plied and glued and bolted together to make large hollow snail shell like structures, which he later began to design on a computer.', 3761, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3762, 'The nature of the materials belied the complexity of the shape and the effort required in their construction.', 3762, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3763, 'The means of construction were very evident, for example glue spilled over from the joins where they had been compressed.', 3763, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3764, 'What would usually be hidden or on the inside of such a large work, was actually the surface of the work.', 3764, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3765, 'Tacita Dean', 3765, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3766, 'British artist born in 1960s who uses 35 mm film to make installations and simple projections.', 3766, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3767, 'One film is made inside a lighthouse.', 3767, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3768, 'A series of photographs examines the beached yacht of a sailor, Donald Crowhurst who faked a transatlantic voyage.', 3768, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3769, 'She made a number of drawings of film story boards featuring a ship in a stormy sea on blackboards.', 3769, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3770, 'Jeremy Deller', 3770, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3771, 'British artist born in the late 1960s who is interested in different social groups and how they are creative.', 3771, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3772, 'The authorship of Deller&apos;s work is always in question (an essential part of Deller&#x2019;s work) &#x2013; the creative work is as much the participants&#x2019; as it is Deller&#x2019;s, who acts as the facilitator of an idea.', 3772, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3773, 'In the mid 1990s Deller began working with groups of people brought together by a particular shared passion.', 3773, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3774, 'One of the first of these was his Manic Street Preachers project.', 3774, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3775, 'Deller asked young fans of the band to write and draw their feelings about them and their music.', 3775, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3776, 'The resulting document was collected into a book and is a testament to the power of music to represent the feelings and hopes of a generation.', 3776, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3777, 'Deller subsequently drew a chart linking acid house music with brass band music via many other forms of popular music.', 3777, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3778, 'The chart was hand drawn in white on black with circles containing text linked and cross linked by arrows.', 3778, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3779, 'Acid Brass was a project in which Deller commissioned a brass band to play acid house music.', 3779, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3780, 'The resulting hybrid was performed in concerts halls and galleries, and released as a CD.', 3780, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3781, 'Deller&#x2019;s most ambitious work, Battle of Orgreave, was a full scale re enactment of a battle fought between the police and striking miners at the peak of the miners strike in the early 1980s in Britain in which the police charged the miners on horses.', 3781, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3782, 'Deller arranged for several historical re enactment societies to come together to stage a full scale re enactment of this event.', 3782, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3783, 'The re enacted battle was filmed by director Mike Figgis and intercut with original news footage.', 3783, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3784, 'The resulting film, shown on national television, was a very accurate portrayal of what happened that also revealed the lengths to which the governments went to ensure a media cover up of the brutality of the police and their determination that the scale of the protest should be played down.', 3784, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3785, 'Guest list was a work made for Imprint 93 an artist pamphlet series published by Matthew Higgs, which reproduced the guest list for an exhibition opening at the Institute of Contemporary Arts in London.', 3785, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3786, 'The list which featured a number of celebrities revealed a degree of social ambition and perhaps sycophancy on the part of the institution.', 3786, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3787, 'The Folk museum was made by Deller with Alan Kane.', 3787, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3788, 'Together they collected hand made craft and folk objects of no intrinsic value and displayed them as if they were valuable collection of artefacts.', 3788, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3789, 'At the Venice Biennale in 2003 Deller made button badges with a road stop sign (a red circle with diagonal line bisecting it on a white ground) with the words No Vogue across it, which referred to the magazine &#x2013; Deller commented of the ubiquity of the magazine&#x2019;s presence at any art event, and the ever increasing tendency of the art world to collide with the world of socialites and celebrities and be photographed doing so.', 3789, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3790, 'Thomas Demand', 3790, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3791, 'British artist who makes photographs of complex paper &#x2018;sets&#x2019; that he constructs himself.', 3791, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3792, 'The sets replicate a real space, for example an office, which Demand then remakes entirely in card and paper.', 3792, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3793, 'The resulting construction is carefully lit and then photographed in large format and presented as a very large (about two metres high) print.', 3793, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3794, 'The image provokes a double take &#x2013; it seems to be a plausible space although oddly empty.', 3794, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3795, 'Once the viewer begins to try to decode the image, and look for clues, it becomes apparent that for example the surfaces of the furniture are too homogenous, without detail.', 3795, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3796, 'Even then it is difficult to establish why the space depicted seems unreal.', 3796, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3797, 'When the process behind the work becomes clear the work can be viewed more as an achievement in terms of its construction.', 3797, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3798, 'Xenia Dieroff', 3798, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3799, 'German artist living and working in Britain, Dieroff has made photographic work.', 3799, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3800, 'A slide installation projected onto a hospital screen uses silhouetted figures and clever dissolves to create the illusion of a patient undressing that morphs into a striptease.', 3800, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3801, 'Mark Dion', 3801, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3802, 'American artist who is interested in anthropology, material culture, ecology and natural history.', 3802, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3803, 'Dion&apos;s usually large scale multi part installations are the result of research projects into specific locations or subjects.', 3803, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3804, 'For example in London he searched an area of the muddy Thames riverbank above and below the timeline with the painstaking care of an archaeological dig.', 3804, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3805, 'The resulting &#x2018;artefacts&#x2019; or trash was cleaned up and exhibited in a number of vitrines and display cases in the Tate Gallery.', 3805, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3806, 'Rineke Djikstra', 3806, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3807, 'A Dutch artist who became known in the late 1990s for her photographic portraits of young people.', 3807, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3808, 'Like Thomas Struth and Thomas Ruff Djikstra asked her subjects to look straight at the lens and not to smile.', 3808, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3809, 'The resulting images are a true document of a generation.', 3809, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3810, 'In 2000 she began to make video portraits.', 3810, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3811, 'A film portraying young people at a club shows them standing against a white backdrop, moving slightly.', 3811, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3812, 'They are listening to music which the viewer cannot hear, but Djikstra has asked them to stand still.', 3812, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3813, 'Their body language reveals a lot about them, as do their clothes.', 3813, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3814, 'Although it is a film, the participants have been captured in time as if it were a photographic portrait.', 3814, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3815, 'Their youth is very expressive.', 3815, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3816, 'Willie Docherty', 3816, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3817, 'Northern Irish artist, Docherty made a number of photographic series and video works in the 1980s and early 90s at the height of the troubles in Northern Ireland.', 3817, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3818, 'These featured empty roads, empty landscapes, cars and checkpoints.', 3818, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3819, 'A video work in his Turner prize nomination exhibition was filmed from a car driver point of view and purported to be a night drive with sinister intentions, although this was merely suggested with the greatest economy of means.', 3819, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3820, 'Docherty&apos;s work has an oneric quality although it deals with political issues.', 3820, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3821, 'He gives a glimpse of life on the border and of political strife in urban and rural landscapes.', 3821, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3822, 'Peter Doig', 3822, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3823, 'British painter who grew up in Canada, born 1957.', 3823, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3824, 'Doig is chiefly a landscape painter and was among those British artists who created a resurgence of interest in painting in Britain in the early 1990s.', 3824, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3825, 'His landscapes are often oneric, usually populated by a single figure if at all and have a strong sense of the unknown and of adventure.', 3825, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3826, 'Doig paints the seasons, the mountains, forests, lakes, vernacular architecture, and occasionally sports such as fishing, skiing, snowboarding.', 3826, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3827, 'He paints thinly and loosely, scattering the surface with blobs of thicker paint when the image is complete.', 3827, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3828, 'This often serves to represent light, for example the white blobs in an early work The Architect&apos;s House.', 3828, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3829, 'He also painted a Corbusier housing block in a similar way.', 3829, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3830, 'Both are seen through trees and use a lot of green brown, back and white with touches of yellow white and red.', 3830, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3831, 'Often the touches of paint on the surface do not read as part of the image but become very apparent on close inspection.', 3831, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3832, 'They may even be bars of colour that are not part of the image at all, or splatters.', 3832, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3833, 'Another early work, the Bean Eater, shows a boy walking in a field empty except for a red wooden house or barn.', 3833, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3834, 'A leafless branch of a tree with some kind of seed or flower painted like glowing orangey white bobbles.', 3834, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3835, 'Later works from 2000 onwards depict a steamboat apparently steaming past a jungle on a river reminiscent of (apocalypse).', 3835, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3836, 'This is a very green and lush painting.', 3836, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3837, 'A tree in the moonlight with a girl sitting on a branch high up is painted in greys and lilacs, as if it were a night scene or a nightmare.', 3837, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3838, 'A lake with a canoe on it paddled by a man with long black hair and a beard, the canoe is orange and the lake very blue.', 3838, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3839, 'This image is taken from an album cover.', 3839, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3840, 'A painting of a mountain ski slope called Red Ski Jacket is very white with only the minute people bringing in colour.', 3840, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3841, 'One of a snow boarder shows the boy in the air upside down at the top of the canvas with a group of people watching at the bottom.', 3841, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3842, 'Doig became extremely influential in the mid 1990s.', 3842, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3843, 'Kay Donachie', 3843, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3844, 'British artist born in 1970s who made process paintings during the 1990s, using a roller to transfer an image to a prepared canvas, resulting in a shadowy painting, the image always seeming slightly removed from reality due to the technique.', 3844, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3845, 'Donachie painted isolated houses, a tent, a Christmas tree, the interior of Paul Klee&apos;s studio.', 3845, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3846, 'She uses a monochrome palette, choosing a predominant colour for a painting.', 3846, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3847, 'The transfer technique brings the concept of the photographic print into the painting although no such process is involved.', 3847, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3848, 'The viewer&#x2019;s uncertainty about how the image is made is paralleled by the uncertain status of the subject of the painting.', 3848, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3849, 'Following this Donachie began to paint figures, for example groups of young women, and although not necessarily using the same technique, she gives the image the same once removed quality that places it in an uncertain time.', 3849, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3850, 'Lighter colours begin to appear.', 3850, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3851, 'Donachie&apos;s paintings are small, mostly under a metre squared.', 3851, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3852, 'Fiona Drummond', 3852, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3853, 'British artist born 1962 who takes portrait photographs and still lifes.', 3853, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3854, 'She often uses flowers and references seventeenth century Dutch painting especially in terms of light, using studio set and lighting, also paints dogs and flowers.', 3854, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3855, 'Dubossarsky and Vinogradov', 3855, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3856, 'Russian painters born in the 1970s who paint collaboratively.', 3856, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3857, 'Dubossarsky and Vinogradov are among the few Russian artists to gain commercial success in the America and Europe.', 3857, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3858, 'Their work alludes to both history painting and to Russian Socialist Realist art.', 3858, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3859, 'They often ask other artists to paint parts of the work for them and they may make several versions of the same painting or small versions of sections of larger works, for example a book on a snowy muddy ground with a frog diving into a hole.', 3859, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3860, 'Keith Edmier', 3860, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3861, 'American artist born in the 1960s who makes resin cast sculptures of plants and flowers from scaled up models of a plant, such as a water lily up to four metres high, in pale pink or yellow resin.', 3861, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3862, 'The sculpture has very realistic detail and despite its size looks very fragile.', 3862, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3863, 'Edmier has used a variety of plants in this way, and sometimes makes very small sculptures.', 3863, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3864, 'Volker Eichmann', 3864, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3865, 'German artist born in the late 1970s who makes photo collages using interior design magazines and strips of text.', 3865, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3866, 'Olafur Eliasson', 3866, 1, '1.2', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3867, 'Norwegian artist who is interested in the effect of the environment, both built and natural, on humans and the reciprocal effect of humans.', 3867, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3868, 'Eliasson makes minimal and sometimes barely visible interventions, as in his installation at Museum of Modern Art in New York.', 3868, 1, '1.1', 0);
INSERT INTO `text` (`text_id`, `content`, `listorder`, `behaviour_id`, `fontsize`, `in_section`) VALUES (3869, 'This consists of frosted transparent tape applied in vertical stripes, covering the whole glass curtain wall in the foyer, subtly but substantially altering the visitor&apos;s experience of this public area.', 3869, 1, '1.1', 0);
